quests[13052] = { id = 13052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberwachung", description = "Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordwesten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.", sourceObjective = "Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13053] = { id = 13053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Überlebenden", description = "Gretchen Zischelfunken möchte meine Flugmaschine nutzen, um nach Überlebenden ihrer Expedition zu suchen. Offenbar glaubt sie, dass diese im Dorf im Norden gefangen gehalten werden.\n\nDas Problem ist, dass ich keinen Copiloten habe. Wenn Ihr mir aushelfen wollt, dann zeige ich Euch gern ein oder zwei hilfreiche Tricks.\n\nWas sagt Ihr, {name}? Abgemacht?Ihr erlernt:", sourceObjective = "Helft Zak Wackelspross, den Testflug zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13054] = { id = 13054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Fährtenleser", description = "Ich kann Euch nicht guten Gewissens in die Worghöhle gehen lassen, ohne Euch zu warnen, dass wir zuvor schon jemanden dorthin geschickt haben, der jedoch nicht zurückgekehrt ist.\n\nWir rechnen mit dem Schlimmsten, aber vielleicht ist er auch noch am Leben. Solltet Ihr ihm helfen können, zu uns zurückzukehren, wären wir Euch sehr dankbar - Fährtenleser Val'zij ist einer unserer wenigen Jäger.", sourceObjective = "Sucht in Gimoraks Bau östlich der Absturzstelle Grom'ash nach Fährtenleser Val'zij.", completion = "Das tut wirklich weh, Mann. Ich weiß nicht, ob ich es schaffen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13055] = { id = 13055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenmedizin", description = "Wie schön, ein freundliches Gesicht zu sehen, vielleicht das Letzte, das ich seh'n werde.\n\nEiner dieser Jormungar hat mich gestochen, bevor ich entkommen konnte. Mein Körper fühlt sich schon ganz taub an, Mann.\n\nIch brauch'ne Giftdrüse, um ein Gegengift herzustellen, und außerdem einige der Höhlenpilze, die hier wachsen... sie werden das Gift verlangsamen.\n\nBitte beeil dich - hab nich' mehr viel Zeit.", sourceObjective = "Fährtenleser Val'zij hält sich in Gimoraks Bau auf und möchte, dass Ihr ihm 1 Giftdrüse der Jormungar und 8 Höhlenpilze bringt.", progress = "Du bist wieder da, Mann?", completion = "Danke dir, Mann. Vielleicht lebe ich doch noch 'n bisschen länger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13056] = { id = 13056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Rache ist immer Zeit", description = "Ich müsste vorerst zurechtkommen, {name}. Aber ich möchte dich noch um 'nen Gefallen bitten.\n\nIch wäre diesen Würmern nie in die Hände gefallen, wenn meine Windnatter Heesha nicht vom gemeinsten Worg, den ich seit langer Zeit gesehen habe, getötet worden wäre.\n\nMach dir um mich keine Sorgen; mir wird es besser gehen, wenn der Worg keinen Atemzug mehr von sich gibt. Du solltet ihn weiter drinnen in der Höhle finden", sourceObjective = "Fährtenleser Val'zij möchte, dass Ihr Gimorak in Gimoraks Bau tötet.", progress = "Hast du diesen dreckigen Bastard schon gefunden, {name}?", completion = "Es geht mir schon viel besser, Mann. Ich weiß nicht, ob es an dem Gegengift liegt oder daran, dass der dreckige Worg bekommen hat, was er verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[13057] = { id = 13057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse der Schöpfer", description = "Es ist Zeit, {name}. Ich bin jetzt bereit, mich Loken zu stellen.\n\nBegeben wir uns nun zur Terrasse der Schöpfer, wo wir auf die Truppen meines Bruders treffen werden. Der Narr wird noch bereuen, sich je mit mir angelegt zu haben.", sourceObjective = "Findet Thorim an der südöstlichen Kante der Terrasse der Schöpfer gleich nordwestlich von Dun Niffelem.", completion = "Wir sind da, {name}. Heute werden die Truppen meines Bruders erfahren, wie es ist zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13058] = { id = 13058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windrichtung ändern", description = "Zu guter Letzt haben wir alles, was wir brauchen, um das wieder gut zu machen, was der Nordwind und seine Anhänger angerichtet haben. Ihr habt den Lehrenhammer auf Sturmhuf selbst und seine Zeit ausgerichtet.\n\nHier, nehmt wieder den Hammer an Euch, geht zum Tempel des Lebens, schlüpft mit seiner Hilfe in Sturmhufs Rolle und stellt Euch dem Nordwind. Doch wisset: Um die Zeitlinie wieder herzustellen, muss Sturmhuf sterben, sobald der Nordwind geschwächt ist.\n\nSobald dies geschehen ist, müsst Ihr das Horn des Elementarfurors an Euch bringen und mit ihm den Nordwind vernichten.", sourceObjective = "Reist mithilfe des Lehrenhammers in der Zeit zurück, schlüpft in Sturmhufs Rolle und stellt Euch dem Nordwind. Beschafft Euch das Horn des Elementarfurors, sobald Sturmhuf gestorben ist und es fallen gelassen hat, und benutzt es, um den Nordwind zu erledigen. Kehrt danach zu Xarantaur ins Camp Tunka'lo zurück.", progress = "Habt Ihr es getan? Ist die echte Zeitlinie wiederhergestellt?", completion = "Was Ihr heute getan habt, wird dafür sorgen, dass Sturmhuf und seine Geschichte niemals in Vergessenheit geraten werden. Außerdem habt Ihr Euren Namen in die Geschichtsbücher Azeroths geschrieben. Ich werde mich für alle Ewigkeit an Euch und das, was Ihr geleistet habt, erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13059] = { id = 13059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Vargul", description = "Ich habe zur Herrin des Schwertes gebetet, auf dass jemand kommen und meinen Gegner vernichten möge. Than Illskar muss dafür büßen, was er mir angetan hat!\n\nIch war einst der Champion von Than Ufrang dem Mächtigen. Während meines Kampfes um die Vormachtstellung in Valhalas hat mich Illskar mit dunkler Magie sabotiert, woraufhin ich verloren habe und zu dem wurde, was ich jetzt bin.\n\nDer Than und seine Champions befinden sich unten im Kreis des Leidens. Fordert ihn in meinem Namen heraus. Besiegt ihn.\n\nBringt ihm die Qualen bei, die auch ich ertragen muss!", sourceObjective = "Bethod Feigr im Kellergewölbe wünscht, dass Ihr sein Schwert zu Boden werft, um Than Illskar im Kreis des Leidens herauszufordern und zu töten.", completion = "Danke, {class}... habt Dank!\n\nIhr habt mir zu der Genugtuung und Gewissheit verholfen, dass dieser Feigling, der mir das angetan hat, bis in alle Ewigkeit genau so dahinsiechen wird wie ich.\n\nNun geht hinfort, bevor ich die Beherrschung verliere und Euch niederstrecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[13060] = { id = 13060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn alles andere versagt", description = "Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.\n\nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.\n\nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.\n\n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>", sourceObjective = "Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.", completion = "<Olut zuckt zusammen.>\n\nDas hat schmerzhaft ausgesehen. War aber ein ziemlich eindrucksvoller Auftritt.\n\nSeid Ihr hier, um uns dabei zu helfen, einen Weg zum Eiskronengletscher zu finden? Unser erster Abstecher in diese Richtung endete nicht sehr eindrucksvoll. Ich denke, dass wir besser damit beraten wären, den Durchbruch von der anderen Seite her zu versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13061] = { id = 13061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für den Ruhm", description = "Das war's dann also. Ich werde mich jetzt um Euren Bären kümmern, Ihr werdet ihn nicht mehr benötigen. Der große Drakkensryd wird Eure nächste Herausforderung sein.\n\nSagt Euren Freunden Lebewohl und bringt alles ins Reine, bevor Ihr loszieht. Denn Ihr werdet entweder siegreich zurückkehren... oder gar nicht.", sourceObjective = "Sprecht mit Lok'lira der Greisin in Brunnhildar.", completion = "Ihr habt es wirklich bis hierher geschafft. Niemals hätte ich gedacht, dass Ihr so schnell bei den Hyldnir aufsteigen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13062] = { id = 13062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok'liras Abschiedsgeschenk", description = "Ihr wart uns eine großartige Mitstreiterin, {name}. Doch nun kommt Eure wahre Prüfung. Dazu werdet Ihr Können, Mut und ein wenig Glück benötigen.\n\n<Lok'lira flicht eine Haarsträne in Euer Haar ein.>\n\nNun könnt Ihr nicht mehr versagen, Schwester. Sprecht mit Gretta der Schiedsfrau. Sie wird sich um Eure Abreise kümmern.", sourceObjective = "Sprecht mit Gretta der Schiedsfrau in Brunnhildar.", completion = "Bereit, loszureiten, Schwester? Es wird kein Zurück geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13063] = { id = 13063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für würdig befunden", description = "Ihr hattet dort Erfolg, wo viele versagten, Schwester. Ob es nun Eurer Stärke, Eurem Mut oder einfach nur Eurem Glück zu verdanken ist, wird sich noch zeigen.\n\nGeht zurück zum Dorf und sucht nach Astrid Bjornrittar. Erzählt ihr, was Ihr erreicht habt. Doch seid gewarnt: Sie ist nicht so leicht zu beeindrucken.", sourceObjective = "Brijana möchte, dass Ihr nach Brunnhildar geht und mit Astrid Bjornrittar sprecht.", completion = "So, Schwester, Ihr denkt also, dass ein paar so einfache Aufgäbelchen Euch zur Heldin machen?\n\nIhr werdet es noch lernen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13064] = { id = 13064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivalität unter Geschwistern", description = "Sif? Bist du es wirklich?\n\nNein? Nur <ein/eine:r> {race}? Aber einen Augenblick lang....\n\nGenug davon! Die Visionen meiner Sif haben mich schon viel zu lange gequält. Es wird Zeit, sie zu rächen und ihr Andenken zu ehren.\n\nMein Bruder muss bezahlen!", sourceObjective = "Thorim möchte, dass Ihr Euch seine Geschichte anhört.", completion = "Ihr wisst jetzt ein wenig über die Geschichte dieses Landes... meines Landes.\n\nIch bitte Euch, mir zu helfen, das Unrecht wieder gutzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13065] = { id = 13065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Ohanzee", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13066] = { id = 13066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Yurauk", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13067] = { id = 13067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Chogan'gada", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13068] = { id = 13068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Erzählung von Heldenmut", description = "Ist es möglich, dass Ihr die Lobpreisungen an unseren verschollenen Helden gehört habt?\n\nKreuzfahrer Bridenbrad hat den Angriff gegen die Geißel an der Zerbrochenen Front unterstützt, als die Armee der Untoten über sie hereinbrach. Die Masse der Verbündeten floh, aber Bridenbrad allein kehrte zurück und trug mehr als ein Dutzend Männer in Sicherheit, einen nach dem anderen, inmitten des Gemetzels.\n\n{class}, er ist seitdem nicht wieder zurückgekehrt. Man hat gesehen, wie er weit nach Nordosten zog, Richtung Stille Nachtwache. Bringt ihn wieder hierher, damit ich ihm für seinen Mut Respekt zollen kann.", sourceObjective = "Hochlord Tirion Fordring auf dem Kreuzfahrerturm wünscht, dass Ihr den Helden Kreuzfahrer Bridenbrad in der Stillen Nachtwache im Nordosten der Eiskrone aufspürt. Seine Feuergrube wird aus der Luft gesehen wahrscheinlich der deutlichste Hinweis auf seinen Aufenthaltsort sein.", completion = "Zurück! Seht Euch vor! Die Seuche hat von mir Besitz ergriffen und ich werde nicht zulassen, dass sie auf Euch oder andere überspringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13069] = { id = 13069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schießt sie ab!", description = "Jotunheim verfügt über Luftabwehr, sowohl Protodrachenreiter als auch Harpunenkanonen. Sie haben diese an ihren nördlichen und westlichen Verteidigunszonen konzentriert, weil sie dort am verwundbarsten sind.\n\nLasst uns ihre Verteidigung gegen sie selber richten!\n\n<Der Springer starrt Euch mit seinem einen Auge durchdringend an und kichert hysterisch.>\n\nBringt eine Harpunenkanone auf den Plattformen, welche die Klippen auf jeder Seite von Valhalas gen Südwesten überragen, unter Eure Kontrolle. Kümmert Euch um die Protodrachen und ihre Reiter. Schießt sie ab!", sourceObjective = "Der Springer beim Schattengewölbe möchte, dass Ihr eine Schnellfeuerharpune von Jotunheim dazu verwendet, 15 Protodrachen von Jotunheim mitsamt ihren Reitern abzuschießen.", completion = "Ihr seid ein wahrer Held für unsere Sache, {name}!\n\nKommt Ihr bitte morgen wieder bei mir vorbei? Ich bin mir sicher, dass es dann wieder mehr von diesen fiesen Protodrachen abzuschießen gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13070] = { id = 13070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kaltfront nähert sich", description = "Der Frost des Todes regt sich im Westen und droht, unsere Herzen und Seelen in dieser Ödnis einzufrieren, uns an ihren dunklen Meister zu binden. Aber wir werden nicht weichen und wir werden kämpfen!\n\nDie Vorbereitungen sind angelaufen. Meldet Euch bei Belagerungsmeister Fezzik am Haupttor für Euren Auftrag.", sourceObjective = "Meldet Euch bei Belagerungsmeister Fezzik bei der Argentumvorhut in Eiskrone.", completion = "Wir müssen schnell sein, sonst wird uns die Geißel holen! Wir haben wirklich keine Zeit für Instruktionen, {race}. Ihr werdet wohl einfach hineinhüpfen und auf das Beste hoffen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13071] = { id = 13071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ekel mag Feuer!", description = "Ekel mag Feuer! Ekel mag Protodrachen!\n\n<Die Monstrosität klatscht aufgeregt in die Hände.>\n\nKleiner {name} jetzt gehen nach Jotunheim un' stehlen schöne Protodrache in Njorndar. Lass' Protodrache schöööne Feuers auf Häuser von Jotunheim machen!", sourceObjective = "Ekel im Schattengewölbe möchte, dass Ihr einen Protodrachen von Njorndar stehlt und ihn benutzt, um 8 Vrykulgebäude in der weiteren Jotunheimregion in Brand zu setzen.\n\nDie Festung Balargarde kann aufgrund ihrer Beschaffenheit nicht in Flammen gesetzt werden.", completion = "Hurra, hurra! {name} ist allerbeste Protodrachen-Klauer.\n\nDu kommen zurück morgen und wir machen meeehr Feuer!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[13072] = { id = 13072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Held verbleibt", description = "Ich weiß, warum Ihr gekommen seid... sie haben Euch geschickt um mich zurückzubringen, aber das darf nicht geschehen. Ich trage die Seuche des Todes in mir, {class}, und werde mein Schicksal nicht mit jenen teilen, die mir nahe stehen. Nein, ich werde hier bleiben. \n\nIch bedaure nur, was aus mir werden wird, wenn der Tod Besitz von mir ergriffen hat. Den Tod selbst fürchte ich nicht, aber ich verabscheue den Gedanken daran, dem Verräter Arthas zu dienen.\n\nVerlasst mich... und stellt sicher, dass niemand anderes nach mir suchen wird. Ihr würdet mir einen wahren Undienst erweisen, wenn Ihr jemanden der Seuche, die ich trage, aussetzen würdet.", sourceObjective = "Bringt die Neuigkeiten von Kreuzfahrer Bridenbrads Schicksal zu Hochlord Tirion Fordring in den Kreuzfahrerturm.", completion = "Bridenbrad wurde von der Seuche befallen? Ich kann mir kein schlimmeres Schicksal für jemanden vorstellen, der sein Leben dem Weg des Lichts gewidmet hatte; noch kann ich mir vorstellen, ihn sterbend zurückzulassen und dabei tatenlos zuzusehen.\n\nNein, der Untod soll sein Schicksal nicht sein. Wir werden einen Weg finden, diesem Helden beizustehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13073] = { id = 13073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bitte an den Bewahrer", description = "Es gibt jene in dieser Welt, die auf Kräfte stoßen, die frei sind von den Grenzen unserer sterblichen Hüllen - Kräfte der Wiederherstellung, des Lebens und des Lichts. Und Bridenbrad? Das ist kein durchschnittlicher Mann... sein Heldenmut und seine Hingabe sind ein leuchtendes Vorbild. Wir können nur hoffen, dass eines dieser Wesen einschreiten wird und diesen Helden vor einem Schicksal, das schlimmer als der Tod ist, bewahren wird.\n\nGeht nun und sprecht mit der Erzdruidin Lilliandra in der Argentumvorhut... erbittet den Zugang zur Mondlichtung und ersucht Bewahrer Remulos um Hilfe.", sourceObjective = "Hochlord Tirion Fordring im Kreuzfahrerturm hat Euch gebeten, dass Ihr bei der Erzdruidin Lilliandra Zugang erbittet und mit Bewahrer Remulos redet.", completion = "Hallo, mein Kind.\n\nIch verstehe Tirions Bitte und habe Vertrauen in sein Urteilsvermögen. Wir werden sehen, was wir für Kreuzfahrer Bridenbrad tun können. Wonach Ihr fragt, ist keine Leichtigkeit - die Geißel ist nicht von dieser Welt und viele sind im Laufe der Jahre bei dem Versuch gescheitert, ihre Verderbnis zu durchbrechen.\n\nBei einem Lebewesen von Erhabenheit und Licht ist jedoch nicht alle Hoffnung verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13074] = { id = 13074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung im Smaragdgrünen Alptraum", description = "Was wir brauchen, gibt es nur im Smaragdgrünen Traum... Eicheln, die mit einem mächtigen, regenerativen Zauber durchtränkt sind. Viele Orte in diesem heiligen Sumpf sind eng mit dem Traum verbunden und mein Schrein ist einer davon.\n\nIch werde Euch in den Traum schicken, um ein paar jener Eicheln zu besorgen. Seid aber gewarnt, {class}, denn diese Methode, den Traum zu betreten, ist gefährlich, und es ist recht wahrscheinlich, dass Ihr von Alpträumen heimgesucht werdet.\n\nBeeilt Euch und findet ein paar Eicheln. Verlasst anschließend meinen Schrein oder kneift Euch selbst in den Arm, um in unsere Welt zurückzukehren.", sourceObjective = "Bewahrer Remulos auf der Mondlichtung hat Euch aufgetragen, den Smaragdgrünen Traum zu betreten und 3 Smaragdgrüne Eicheln zu besorgen.\n\nVerlasst die nähere Umgebung des Schreins von Remulos, um nach Azeroth zurückzukehren.", progress = "Gut zu sehen, dass Ihr in Sicherheit seid. Habt Ihr alle Eicheln gefunden?", completion = "Hervorragende Arbeit, mein Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13075] = { id = 13075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remulos' Segen", description = "Ich werde ein Portal öffnen, das Euch zu dem Druiden, der Euch hergesandt hat, zurückbringen wird. Meine besten Wünsche begleiten Euch und Euren Kreuzfahrer. Ich hoffe, diese Eichel wird ihn läutern und somit vor dem abscheulichen Schicksal der Seuche bewahren können.\n\nLebt wohl, {race}.", sourceObjective = "Kehrt mit der Smaragdeichel zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.", progress = "Seid gegrüßt, {class}. Ich wusste, dass Ihr zurückkehren würdet, ungeachtet meiner Warnungen... Aber ich bin froh, dass Ihr meiner Bitte nachkommt, niemand anderen zu gefährden.\n\nWarum seid Ihr zurückgekehrt?", completion = "Tirion hat Euch zu Remulos gesandt? Ich... fühle mich geehrt. Man richtet nicht leichtfertig seine Bitten an Wesen von solcher Macht, ganz gleich, wie edel und uneigennützig sie sein mögen. Ich danke Euch, dass Ihr derartige Mühen meinetwegen auf Euch genommen habt.\n\nPflanzt den Samen ein... Ich bin bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13076] = { id = 13076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es bleibt noch Zeit", description = "Ich fühle mich erfrischt... erneuert... aber die Seuche hält mich immer noch in ihrer eisigen Umklammerung. Ich bin Euch dennoch auf ewig dankbar für die Mühen, die Ihr für mich, einen völlig Fremden, auf Euch genommen habt. Zumindest habt Ihr mir so einige wertvolle Stunden verschafft, während derer ich nicht als grässlicher Untoter die Welt verpeste.\n\nIch danke Euch, {class}. Bitte richtet auch Tirion meinen Dank aus und lasset ihn wissen, dass es mir eine Ehre war, an seiner Seite zu dienen.", sourceObjective = "Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten der Smaragdeichel.", completion = "Es erfüllt mich mit Trauer, dass es nicht funktioniert hat. Aber kein Grund zur Verzweiflung, ich habe noch andere Wesen des Guten getroffen, die uns noch immer helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13077] = { id = 13077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung eines Aspekts", description = "Die Drachenkönigin, Alexstrasza, besitzt Magien über das gesamte Sein. In der Vergangenheit hat sie große Feuer benutzt, um Untote zu verbrennen und frisches, neues Leben an ihrer Stelle zu erschaffen. Ihre Kräfte sind vielleicht in der Lage, auch unseren Bridenbrad zu retten.\n\nAlexstrasza hat sich im Wyrmruhtempel in der Drachenöde eingerichtet. Bitte geht zu Ihr und bittet sie demütigst in meinem Namen um Hilfe.", sourceObjective = "Erbittet die Hilfe von Alexstrasza der Lebensbinderin im Wyrmruhtempel.", completion = "Ich grüße Euch, {race}.\n\nDie Sorge steht Euch ins Gesicht geschrieben. Sagt mir, was Euch bedrückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13078] = { id = 13078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dahlias Tränen", description = "In dieser dunklen Stunde werde ich nicht diejenige sein, die einen Helden des Lichts im Stich lässt.\n\nWir werden etwas Heiliges brauchen, um auf die Rettung Eures Bridenbrads hoffen zu können... Das Überbleibsel eines frommen Wesens, das Opfer eben dieser Seuche wurde.\n\nGeht nun zum heiligen Boden in den Gängen außerhalb meines Rubindrachenschreins, dorthin, wo der Kampf stattfinden wird. Meine Rubinhüter werden herabfliegen und den Boden unter untoten Füßen mit Flammen überziehen. Ihr werdet dann Zeuge neuen Lebens sein. Dieses neue Leben wird auch Dahlias Tränen bergen - bringt sie mir.", sourceObjective = "Alexstrasza die Lebensbinderin im Wyrmruhtempel verlangt von Euch, dass Ihr Dahlias Tränen aus dem Boden bergt, der von den Flammen der Rubinbehüter frisch geläutert ist.", progress = "Ah, liebste Dahlia. Ich vermisse dich so...", completion = "Mithilfe von Dahlias Tränen und uralter Magie kann ich Euch ein kleines bisschen Hoffnung für Euren großen Kreuzfahrer verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13079] = { id = 13079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexstraszas Segen", description = "Ihr müsst verstehen, <junger/junge :r> {race}, dass das Läutern eines Körpers zugunsten des Lebens etwas ist, das durchaus in meiner Macht liegt... die Seuche des Untodes zu entfernen, ohne den Körper in Mitleidenschaft zu ziehen, entzieht sich jedoch meiner Kontrolle.\n\nWenn dieser Bridenbrad das Leuchtfeuer des Lichts ist, wie Ihr es beschwört, wird er vielleicht die Läuterung überstehen und sich erholen, aber ich kann nicht mit Gewissheit sagen, ob dies die Erlösung sein wird, nach der Ihr strebt. Nehmt sie und geht mit all meinem Segen.", sourceObjective = "Bringt den Atem von Alexstrasza zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone.", progress = "Ihr seid schon wieder hergekommen, {class}. Warum setzt Ihr Euch diesem Risiko aus?", completion = "Der Atem von Alexstrasza... Ihr seid zur Drachenkönigin höchstpersönlich gegangen? Ich bin Euch unsäglich dankbar.\n\nIch bin mir der Risiken einer solchen Läuterung bewusst und bin bereit. Fahrt fort, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13080] = { id = 13080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung stirbt zuletzt", description = "<Bridenbrad erhebt die Hand zum Gruße, während er wieder zu Atem kommt.>\n\nEs war fast so schmerzhaft, wie es ausgesehen hat, aber es fühlte sich an, als wäre ein Teil der Verderbnis aus meinem Körper gebrannt worden. Anscheinend ist die Seuche jedoch so einfach nicht zu bezwingen.\n\n{class}, danke für alles, was Ihr getan habt. Eure selbstlosen Taten haben meine Hoffnung genährt, dass es noch immer viel Gutes in der Welt gibt...Ich kann nun gehen, ohne Furcht davor, dass die Dunkelheit in meiner Abwesenheit obsiegen wird.\n\nIhr könnt nun ohne Bedenken gehen.", sourceObjective = "Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten des Atems von Alexstrasza.", completion = "Die Seuche der Geißel ist kein leicht zu bezwingender Feind. Alexstraszas Worte legen nahe, dass wir unseren treuen Bridenbrad noch immer vor dem unvorstellbaren Schicksal des Untodes bewahren könnten, sollte er fallen, aber so leicht gebe ich ihn nicht auf.\n\nEs gibt noch einen Weg des Lichts, den ich gerne beschreiten würde. Ein weiteres Wesen, das dieses schreckliche Schicksal abwenden könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13081] = { id = 13081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille der Naaru", description = "Ich bin dankbar für alles, was Ihr für uns getan habt, {name}. Ich habe noch einen letzten Auftrag für Euch... ein letztes Glimmen der Hoffnung für einen Paladin, der jede Erlösung verdient, die wir ihm bieten können.\n\nGeht nun nach Shattrath und sprecht mit dem Naaru A'dal. Er ist seit langem ein Leuchtfeuer des Lichts und mächtiger Verbündeter der Paladine. Berichtet ihm von Bridenbrad und erbittet jede Hilfe, die er Euch zu geben vermag.\n\nIch kann nicht genug betonen, wie wichtig es ist, dass Ihr Euch beeilt... Ich befürchte, dass unserem Kreuzfahrer nicht mehr viel Zeit in dieser Welt verbleibt.", sourceObjective = "Erbittet die Hilfe von A'dal in Shattrath in den Wäldern von Terokkar.", completion = "<Ein sanftes Klingen erfüllt Euren Kopf, als Ihr Euch dem Naaru nähert.>\n\nIch weiß, warum Ihr hergekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13082] = { id = 13082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A'dals Segen", description = "Ich bin erfreut, dass Ihr zu mir gekommen seid, {name}. Ich weiß von Kreuzfahrer Bridenbrad und von Euren Reisen, um ihn zu erretten. Bridenbrads Heldenmut hat eine bemerkenswerte Selbstlosigkeit in Euch zum Vorschein gebracht, und das ist an sich schon ein Wunder.\n\nDas Licht wird sich um die Seinen kümmern. Ich werde Bridenbrad meinen Segen zuteilwerden lassen, auf dass er die Verderbnis des Untodes nicht länger zu ertragen braucht. Ich werde Euch zurück nach Dalaran schicken und Ihr werdet zu ihm zurückkehren. Wisset, dass ich stets bei Euch sein werde.", sourceObjective = "Kehrt zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.", completion = "<Als Ihr Euch Kreuzfahrer Bridenbrad nähert, müsst Ihr feststellen, dass seine Haut eine fahle Farbe angenommen hat und sein Atem sehr flach geht. Es ist klar, dass er nicht mehr lang zu leben hat.>\n\nIhr seid zu mir zurückgekehrt, {class}. Ich muss zugeben... dass es gut ist, Euch wiederzusehen... Euer Antlitz erneuert meine Hoffnung, dass dieses Land eines nicht zu fernen Tages von Arthas' eisigem Griff befreit sein wird. Ich bin stolz darauf, Euch gekannt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13083] = { id = 13083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "<Kreuzfahrer Bridenbrads Wappenrock liegt am Boden der Truhe und beginnt leicht zu flattern, als der heulende Wind seinen Weg hineinfindet.>\n\nTirion wird dieses letzte Überbleibsel des großen Kreuzfahrers an sich nehmen wollen.", sourceObjective = "Bringt Kreuzfahrer Bridenbrads Wappenrock zu Hochlord Tirion Fordring in den Kreuzfahrerturm.", progress = "Er ist also von uns gegangen, nicht wahr? Ich habe gespürt, wie das Land um etwas Licht ärmer geworden ist.", completion = "Ich bin froh, dass Ihr ihn vor dem Untode bewahren konntet. Mit dem Segen A'dals wird ihm im Jenseits kein Übel widerfahren.\n\nWir werden uns ein Beispiel an seinem leuchtenden Vorbild und an Eurer Selbstlosigkeit nehmen. Ich danke Euch für alles, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13084] = { id = 13084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demoliert Jotunheim", description = "Lasst uns doch mal sehen, ob wir noch weiter die Entschlossenheit der Vrykul schwächen können, {name}.\n\nIch möchte, dass Ihr jeden Tag nach Jotunheim geht und ihre Banner verbrennt. Das mag sich nach einer unbedeutenden Sache anhören, aber wenn sie ihre Heimatstadt jeden Tag demoliert sehen, wird dies ihre Moral weit mehr schwächen, als es jede physische Gewaltmaßnahme je könnte.\n\nZumindest aber... kann es nicht schaden.", sourceObjective = "Herzog Lankral beim Schattengewölbe möchte, dass Ihr 10 Banner der Vrykul verbrennt.", completion = "<Der Herzog schaut Euch einen Moment lang an, dann nickt er.>\n\nIhr richtet ein verheerendes mentales Trauma unter den Vrykul von Jotunheim an. Es ist der Ort, an dem sie das erste Mal wiedererweckt wurden. Ein Ort von herausragender Bedeutung für sie, übertroffen nur von Ymirheim.\n\nIhr müsst den Druck dort aufrechterhalten, während ich die Streitkräfte des Lichkönigs vom Schattengewölbe abhalte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13085] = { id = 13085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaelen ist zurückgekehrt", description = "Ich habe soeben diesen inkompetenten Narren, Vaelen den Geschundenen, gesehen, wie er in das Schattengewölbe geschlichen ist.\n\nGeht und stellt sicher, dass er seinen Fehler wieder gutmacht und mir meine Todesritter zurückbringt!", sourceObjective = "Redet mit Vaelen dem Geschundenen im Schattengewölbe.", completion = "Ich denke, ich weiß, warum Ihr hier seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13086] = { id = 13086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Verteidigungslinie", description = "Ich habe die Verteidigungen der Basis aktiviert, {class}! Auf jedem der vier Türme der Vorhut ist eine einziehbare Kanone des Argentumkreuzzugs angebracht, von Vater Gustav persönlich geweiht. Ihr müsst zu einer der Kanonen fliegen und sie bemannen. Benutzt sie, um den Ansturm der Geißel zu vernichten, den der Lichkönig hergesandt hat.\n\nEine Warnung noch, die Geißel wird zweifelsohne ihre Frostwyrm schicken, um die Türme zu belagern. Blast sie vom Himmel! Wenn sie die Türme und Wälle der Basis zerstören, sind wir geliefert!", sourceObjective = "Benutzt eine Argentumkanone, um 100 Angreifer der Geißel zu vernichten. Außerdem müsst Ihr 3 Frostbrutzerstörer töten.\n\nSolltet Ihr erfolgreich sein, kehrt zu Belagerungsmeister Fezzik zurück.", progress = "Die Schreie der Sterbenden werden mich mein Leben lang verfolgen! Helft ihnen!", completion = "Ihr habt die Kanone wie ein echter Goblinkanonier geführt, Freund. Ihr habt die Vorhut und den Argentumkreuzzug gerettet... und dabei den Hochlord selbst auf dem Schlachtfeld unterstützt. Unglaublich!", sourceObjectiveStatus = "unverified-source-field" }
quests[13087] = { id = 13087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Also was machen wir denn da, wenn Ihr keinen Eintopf für mich habt? Ich hab' HUNGER! Ihr könnt mir zumindest ein wenig kühles Fleisch bringen, damit ich mir selbst 'nen Eintopf machen kann! Wenn Ihr das macht, dann kann ich Euch ein Rezept geben, damit Ihr Euren eigenen machen könnt. JETZT GEHT UND BRINGT MIR EIN BISSCHEN FLEISCH!", sourceObjective = "Bringt 4 Stück kühles Fleisch zu Brom Bräugießer in Valgarde. Jede Bestie in Nordend verfügt über dieses Fleisch.", progress = "WO IST MEIN FLEISCH!", completion = "Du hast mein Fleisch! Hier ist dein Rezept - ich hab' zu kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13088] = { id = 13088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Wir haben eine Menge neuer Rekruten hier und die Jungs sind hungrig! Wenn Ihr mir ein wenig kühles Fleisch für einen Eintopf besorgen könntet, würde ich Euch beibringen, wie Ihr selbst einen für Euch kochen könnt.", sourceObjective = "Bringt Rollick MacKreel in der Valianzfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.", progress = "Die Jungs brauchen Fleisch für ihren Eintopf.", completion = "Das wird unsere Rekruten satt halten! Hier ist das Kochrezept dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[13089] = { id = 13089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Nichts wärmt die Knochen besser, als ein aus lebenden Wesen zubereiteter Eintopf. Bringt mir etwas von dem kühlen Fleisch der hiesigen jämmerlichen Bestien und ich werde Euch zeigen, wie man einen warmen Eintopf zubereitet.", sourceObjective = "Bringt 4 Stück kühles Fleisch zu Thomas Kolichio im Hafen der Vergeltung. Alle Bestien in Nordend verfügen über dieses Fleisch.", progress = "Der Eintopf wartet...", completion = "Wir können das Fleisch im Handumdrehen zu Eintopf verarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13090] = { id = 13090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Die Krieger der Kriegshymnenoffensive brauchen etwas in ihren Bäuchen, um stark zu bleiben. Falls Ihr mir ein wenig kühles Fleisch von den Rhinozerossen oder den anderen Bestien besorgt, könnte ich ein bisschen Eintopf für sie kochen. Wenn Ihr mir helft, werde ich Euch das Rezept verraten.", sourceObjective = "Bringt Orn Zarthuf in der Kriegshymnenfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.", progress = "Wenn das Fleisch hier ist, wird der Eintopf gekocht.", completion = "Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[13091] = { id = 13091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst, ein Wasserschrecken zu sein", description = "Die Wasserschleuse vor meiner Höhle wimmelt nur so von Elementaren, die von den Vrykulzauberern erst noch gezähmt werden müssen. Ich werde Euch einen Trick zeigen, wie man für kurze Zeit Besitz von ihnen ergreifen kann, und Ihr werdet sie dafür einsetzen, Chaos und Zerstörung in Jotunheim anzurichten!\n\n<Die Banshee-verseuchte Vrykul entzieht der Luft Magie und berührt Eure Stirn.>\n\nGeht nun und öffnet die Tür zur Schleuse. Ein Wasserschrecken wird hervorkommen und Ihr werdet ihn kontrollieren, um unsere Feinde zu zerstören!", sourceObjective = "Die Knochenhexe in Njorndar möchte, dass Ihr Besitz von einem Wasserschrecken ergreift und ihn dazu benutzt, 10 Vrykul in der Umgebung von Jotunheim zu töten.\n\nIn Frage kommende Vrykul sind Schlafwächter, Krieger von Jotunheim, Wassermagier der Mjordin, Speerschwestern von Njorndar und Varguls von Valhalas.", progress = "Die Knochen verraten mir, dass Ihr noch nicht ganz fertig seid.", completion = "Noch nie habe ich in den Augen eines Vrykuls solches Entsetzen gesehen - und sie halten sich für die Herren ihrer Welt.\n\nWir beide werden beweisen, dass sie falsch liegen... sehr falsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13092] = { id = 13092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen lesen", description = "Einer der Vorteile davon, Besitz von dieser Kreatur zu ergreifen, ist, dass ich Zugriff auf all ihre Kräfte habe. Als Knochenhexe und Runenleserin hat sie die Macht, Knochen auszuwerfen und daraus jemandes Schicksal zu lesen.\n\n<Die Knochenhexe schmunzelt.>\n\nGut für Euch, dass es in meiner Macht steht, das Resultat zu beeinflussen.\n\nBringt mir die Knochen von Vrykul, die Ihr hier in Jotunheim tötet, und ich werde sie so werfen, dass Ihr Euer Schicksal bestimmen könnt.", sourceObjective = "Die Knochenhexe in Njorndar hat Euch aufgetragen, 15 Vrykulknochen zu besorgen.", progress = "Ich finde es bemerkenswert, dass diese Wesen jemals die Welt beherrschen konnten, wo sie lediglich über solch primitive Magie verfügten.", completion = "Nun werden wir sehen, was die Zukunft für Euch bereithält.\n\n<Die Knochenhexe wirft die Knochen auf den Teppich vor sich.>\n\nWählt Euer Schicksal, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13093] = { id = 13093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen lesen", progress = "Bringt noch mehr Vrykulknochen und wir werden dafür sorgen, dass sich das Schicksal zu Euren Gunsten wendet.", completion = "Wählt Euer Schicksal, {name}." }
quests[13094] = { id = 13094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schämen sie sich denn nicht?", description = "Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.\n\nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Horde darüber zu unterhalten, und nun ist es weg!\n\nSie müssen es gewesen sein, {class}. Bitte beschafft das Buch.", sourceObjective = "Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.", progress = "Bitte, {name}, sagt mir, dass Ihr Berinands Forschungsergebnisse gefunden habt...", completion = "Ihr habt sie gefunden?! Ja, ja, alles ist da.\n\nHier, bitte, nehmt dies als Zeichen meines Dankes. Und wenn es nicht zu viel verlangt ist, dann wäre es besser für mich, wenn Berinand nie davon erfahren würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13095] = { id = 13095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schämen sie sich denn nicht?", description = "Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.\n\nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Allianz darüber zu unterhalten, und nun ist es weg!\n\nSie müssen es gewesen sein, {class}. Bitte beschafft das Buch.", sourceObjective = "Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.", progress = "Bitte, {name}, sagt mir, dass Ihr das Buch gefunden habt...", completion = "Ihr habt es gefunden?! Ja, ja, alles ist da.\n\nHier, bitte, nehmt dies als Zeichen meines Dankes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13096] = { id = 13096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "Hast du's gesehen, Mann?\n\nEs muss wohl das Furchtbarste gewesen sein, das ich jemals gesehen hab'. Der große Akali: vor meinen Augen getötet. Schrecklich...\n\nIch habe geschworen, mich nicht in die Sache hier verwickeln zu lassen. Ich soll nur beobachten. Doch das kann so nicht hingenommen werden! Gal'darah muss dafür bezahlen!\n\nGeh nach Gundrak und such ihn auf. Komm zu mir zurück, sobald Akalis Tod gerächt wurde, Mann.", sourceObjective = "Tol'mar in Dubra'Jin möchte, dass Ihr Gal'darah in Gundrak erschlagt.", completion = "Du hast es getan?! Gal'darah gibt es nich' mehr?\n\nHier, Mann, nimm. Ist'n Geschenk dafür, dass du diesem Mistkerl seine gerechte Strafe erteilt hast.", sourceObjectiveStatus = "unverified-source-field" }
quests[13097] = { id = 13097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.\n\nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.\n\nSchnell, {name}, macht Euch von Gundrak aus in nördliche Richtung nach Dubra'Jin und sprecht mit Tol'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.", sourceObjective = "Har'koa möchte, dass Ihr mit Tol'mar in Dubra'jin sprecht.", completion = "Hör zu, Mann. Die Arbeit, die hier erledigt werden muss, is' gefährlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[13098] = { id = 13098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Gundrak ist verloren, Mann.\n\nDie Geschichte wird sich vor deinen Augen wiederholen. Wenn Trolle sich gegen ihre eigenen Götter wenden, dann ist's das sichere Ende. Es ist nur eine Frage der Zeit.\n\nWenn wir die Ereignisse bis ins Detail erfassen können, dann würde sich vielleicht verhindern lassen, dass zukünftige Generationen denselben dunklen Weg einschlagen.\n\nWenn du mutig genug bist, dann geh nach Gundrak und such nach Hinweisen darüber, was dazu geführt hat, dass das Reich der Drakkari so enden musste.", sourceObjective = "Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und 6 Geschichtstafeln der Drakkari sammelt.", progress = "Hast du die Geschichtstafeln der Drakkari gefunden, Mann?", completion = "<Bah'Kini überfliegt die Worte auf den Tafeln nur kurz und widmet Euch dann wieder ihre Aufmerksamkeit.>\n\nDie sind echt, {race}. Sie werden ihren angestammten Platz in meiner Sammlung finden.\n\nVielleicht können wir diesem Treiben endlich ein Ende machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13099] = { id = 13099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ma' nachsehen", description = "Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.\n\nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?", sourceObjective = "To'kini möchte, dass Ihr mit Bah'kini in Dubra'Jin sprecht.", completion = "Ne langjährige Schülerin? Ha!\n\nWenn'a mit \"langjährig\" n' ganzes Leben meint, dann das stimmt das sicha, eh.\n\nTo'kini is' mein feiga Vater - zu feige, sich füa nen Posten so nah bei Gundrak zu melden... deswegen hatter mich geschickt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13100] = { id = 13100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieerfüllter Pilzhackbraten", description = "Wir haben eine wichtige Lieferung zu machen! Orton Bennet bei Kuriositäten & Meer braucht einen Pilzhackbraten.\n\nBeschafft also einige energieerfüllte Pilze aus der Kanalisation von Dalaran und ein wenig kühles Fleisch und bereitet sie in Eurer Bratenform zu. Liefert den fertigen Hackbraten bei Orton ab.", sourceObjective = "Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.", progress = "Habt Ihr mir irgendwas zu essen mitgebracht?\n\nIch scheine nie von diesem Laden wegzukommen und sei es auch nur für eine Minute.", completion = "Das sieht köstlich aus! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[13101] = { id = 13101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammlung im Zauberkasten", description = "Arille Azurblick im Zauberkasten hat bald eine Versammlung bei sich und braucht so fix wie möglich ein Festmahl!\n\nIhr müsst einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen namens \"Noch ein Gläschen\" in der Mitte von Dalaran beschaffen. Der Besitzer des Käseladens schuldet mir den Wein - Ihr werdet ihn irgendwo im Laden finden.\n\nBringt die Eintöpfe und den Wein zu Arille.", sourceObjective = "Bringt 4 nordische Eintöpfe, die Ihr selbst gekocht habt, und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.", progress = "Wo ist mein Essen? Die Versammlungsmitglieder könnten jeden Augenblick hier sein!", completion = "Das ist genug Essen für alle! Ich bin mir sicher, dass die Kunden zufrieden sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13102] = { id = 13102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanaleintopf", description = "Ajay Grün, der Gastwirt in der Kanalisation von Dalaran, braucht einen Gemüseeintopf für seine Kunden, da ihnen dort unten das Essen ausgeht.\n\nSammelt 4 Kristallsangkarotten aus dem Kristallsangwald, gebt sie gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nDen Kristallsangwald könnt Ihr über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.\n\nBringt den Gemüseeintopf zu Ajay, sobald er fertig gekocht ist.", sourceObjective = "Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nBringt den fertigen Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.", progress = "Ich hab' hungrige Leute dort unten! Wir brauchen etwas Eintopf.", completion = "Das wird im Nu weg sein! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[13103] = { id = 13103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käse für Leuchtegold", description = "Ranid Leuchtegold im Lederladen in Dalaran hatte plötzlich ein heftiges Verlangen nach Wein und Käse.\n\nIm Laden \"Noch ein Gläschen\" in der Mitte von Dalaran gibt es ein Regal mit Käse - holt Euch etwas davon und sammelt dann noch einige halbvolle Weingläser ein, die überall in Dalaran verstreut herumstehen. Danach sollt Ihr den Wein in eine Flasche füllen und diesen dann gemeinsam mit dem Käse Ranid servieren.\n\nWir denken, dass er den Unterschied nicht bemerken wird.", sourceObjective = "Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.\n\nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.", progress = "Habt Ihr einen Diener mit meiner Wein- und Käseplatte gesehen? Mich hat der kleine Hunger gepackt!", completion = "Aha, das scheint mir ein guter Jahrgang zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13104] = { id = 13104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal in die Bresche, Held", description = "Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!\n\nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.\n\nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.", sourceObjective = "Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.", completion = "Meine Kenntnisse der Taktiken der Geißel sind ohne Gleichen.\n\n<Der Schwarze Wächter mustert Euch.>\n\nVor der Schlacht um die Kapelle des hoffnungsvollen Lichts dienten meine Ritter und ich dem Lichkönig... sein eisiger Griff kontrollierte jede unserer Handlungen. Das Licht der Morgendämmerung hat alles verändert...", sourceObjectiveStatus = "unverified-source-field" }
quests[13105] = { id = 13105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal in die Bresche, Held", description = "Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!\n\nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.\n\nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.", sourceObjective = "Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.", completion = "Eure Macht ist gewachsen, getreuer Ritter.\n\n<Hochlord Darion Mograines Blick ist auf Euch gefallen.>\n\nUnsere Rache wird bald vollzogen, Bruder. Koltira steht der Horde auf der Orgrims Hammer bei, während Thassarian die Allianz auf der Himmelsteiler unterstützt. Die Schwarze Klinge wird schon bald über Eiskrone hinwegfegen und die Armeen des Lichkönigs vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13106] = { id = 13106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarzwacht", description = "Die Geißel verfügt über eine große Einrichtung, genannt die Fleischwerke, die zur Produktion von Monstrositäten und Fleischriesen dient. Wenn wir sie ausschalten könnten, würden wir den Lichkönig eines Gutteils seiner Armee berauben.\n\nIch habe Dunkelreiterin Arly in die Gegend entsandt. Sie hat westlich von Corp'rethar auf einem Höhenrücken eine kleine Basis errichtet, die Schwarzwacht, von wo aus sie die Fleischwerke überblicken kann. Ich habe gehört, dass der Argentumkreuzzug jemanden entsandt hat, um ihre Bemühungen dort zu koordinieren, aber die Dunkelreiterin wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Dunkelreiterin Arly in der Schwarzwacht in Eiskrone.", completion = "Gut. Wir brauchen jede Hilfe, die wir kriegen können. Olakin hier ist der Beitrag des Argentumkreuzzugs zu unseren Bemühungen. Lassen wir das Gequatsche und machen wir uns an die Arbeit, die Geißel ihrer Krieger aus Fleisch zu berauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13107] = { id = 13107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senfwürstchen!", description = "Erzmagier Pentarus sieht sich gelegentlich gerne ein Kampfballspiel an und möchte auch gehen, doch er braucht für die Reise etwas zu essen.\n\nIhr müsst seinen Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Bereichen der Stadt zu finden.\n\nBringt ihm seinen Picknickkorb, damit er bereit für das große Spiel ist.", sourceObjective = "Füllt den leeren Picknickkorb mit 4 Rhinowürstchen, die Ihr selbst gekocht habt, und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.\n\nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran.", progress = "Bin fast startklar - muss nur noch auf das Essen und... ähm... meine Magierkollegen warten.", completion = "Perfekt! Ich hoffe nur, dass die Dalaraner Demolierer endlich mal ein Spiel gewinnen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[13108] = { id = 13108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koste es, was es wolle!", description = "So oder so, Loken wird sterben.\n\nSelbst wenn ich ihm alle Gliedmaßen einzeln herausreißen muss, wird er schon bald für seine Taten büßen.\n\nSolltet Ihr vor mir auf ihn treffen, so mögen der Ruhm und die Ehre für seine Niederlage Euer sein.\n\nKehrt zu mir mit seiner verlogenen Zunge zurück und erhaltet dafür meinen Dank und Segen.", sourceObjective = "König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Loken besiegt. Danach sollt Ihr mit Lokens Zunge zu König Jokkum zurückkehren.", progress = "Wurde Loken seiner gerechten Strafe zugeführt?", completion = "Dieser niederträchtige Wurm ist tot?\n\nIhr habt Euch für mein Volk als ein wahrer Segen erwiesen, kleiner {race}.\n\nBitte nehmt dieses Geschenk als Dank für Eure loyale Freundschaft an.", sourceObjectiveStatus = "unverified-source-field" }
quests[13109] = { id = 13109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diametral entgegengesetzt", description = "Ich muss offen zu Euch sein, <kleiner/kleine:r> {race}. Meine Leute sind nicht mehr dieselben, seit unsere Bande mit Thorim gebrochen sind.\n\nAls ihr Anführer wünsche ich mir nichts sehnlicher, als dass ihre Herzen heil werden und unsere Freundschaft mit dem Sturmherren erneuert wird. Mit Eurem Sieg über Fjorn habt ihr einen Schritt auf diesem Weg getan. Ich wünschte, Ihr würdet einen weiteren Schritt wagen...\n\nIn den Hallen der Blitze sitzt jemand, der selbst mächtiger als Fjorn ist und sich an unserer Existenz stört. Volkhan wird nicht eher ruhen, bis entweder er oder wir ausgelöscht sind.", sourceObjective = "König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Volkhan besiegt.", completion = "Volkhans Schrecken wird mein Volk nicht länger bis in den Schlaf verfolgen.\n\nSetzt Eure Bemühungen fort, kleiner {race}. Ich bin mir sicher, dass meine Leute Thorim mit der Zeit vergeben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13110] = { id = 13110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die rastlosen Toten", description = "Nicht all unsere Soldaten haben es lebend aus Geißelholme herausgeschafft. Viele wurden getötet und in entartete Reflexionen ihres früheren Selbst verwandelt. Das ist der Weg der Geißel. Für jene armen Verdammten gibt es keinen ewigen Frieden. Wir müssen ihren Seelen Ruhe verschaffen.\n\nReist durch die Bresche nach Geißelholme und tötet die skelettartigen wiedererweckten Kreuzfahrer. Sprenkelt dieses Weihwasser über ihre Gebeine, so dass ihre Seelen befreit werden können.", sourceObjective = "Vater Gustav im Tal der Echos in Eiskrone möchte, dass Ihr die Überreste von wiedererweckten Kreuzfahrern mit Weihwasser benetzt, um 10 ruhelose Seelen zu befreien.", progress = "Es ist eine makabere Aufgabe, {name}, aber sie muss getan werden.", completion = "Der Weg des rechtschaffenen Kreuzfahrers ist von Ungerechtigkeit und Übel gesäumt. Rettung kann es nur geben, wenn man nicht vom Weg abweicht. So, wie Ihr es heute vorgelebt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13111] = { id = 13111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Hör zu, Mann.\n\nAuf den ersten Blick sieht es so aus, als würde es sich hierbei wieder um die alte Leier handeln: Trolle, die verbotene Kräfte anzapfen und genau die Wesen zerstören, die sie eigentlich anbeten sollten.\n\nIn dem Fall stimmt es zwar auch, doch an diesen Drakkari ist etwas Besonderes dran. Wenn das, was ich herausgefunden habe, stimmt, dann gibt es in Gundrak einen ganz besonderen Golem - einen Golem, wie er noch nie zuvor erschaffen wurde!\n\nDu willst ein Abenteuer, Mann? Dann geh nach Gundrak und bring mir ein Stück dieses Golems, damit ich es untersuchen kann.", sourceObjective = "Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und ein Fragment des Kolosses der Drakkari beschafft.", progress = "Hast du mir ein Stück dieses Golems gebracht, Mann?", completion = "Ahh, ja Mann! Das ist es, wonach ich gesucht habe.\n\nHier, bitte schön - nimm dir was Schönes für den Ärger, den du hattest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13112] = { id = 13112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieerfüllter Pilzhackbraten", description = "Orton Bennet bei Kuriositäten & Meer braucht 'nen Pilzhackbraten.\n\nBeschafft also 'n paar energieerfüllte Pilze aus der Kanalisation von Dalaran und etwas kühles Fleisch und bereitet sie in Eurer Bratenform zu. Das Resultat liefert Ihr dann bei Orton ab.\n\nWenn der Rat mir nur erlauben würd', meine Gnomspezialität aufzutischen, ich würd' ihnen schon zeigen, was wirklich lecker ist!", sourceObjective = "Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.", progress = "Habt Ihr etwas für mich? Ich komme so selten aus meinem Laden raus.", completion = "Hat Awilo das Essen geschickt? Versprecht Ihr mir, dass da keine Gnome drin sind?", sourceObjectiveStatus = "unverified-source-field" }
quests[13113] = { id = 13113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammlung im Zauberkasten", description = "Kannst du dir das vorstellen? Die Horde hat Kannibalismus für illegal erklärt... das ist einfach nicht richtig, sag ich dir! Ich schätze mal, dass ich mich auf meine Arbeit konzentrieren sollte, wenn wir schon eine Bestellung haben.\n\nArille Azurblick im Zauberkasten hat viele Besucher bei sich, Mann. Er braucht einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen in der Mitte von Dalaran.\n\nBring also den Wein und den Eintopf zu Arille.", sourceObjective = "Bringt 4 nordische Eintöpfe und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.", progress = "Wo ist das Essen? Meine Gäste werden bald hier sein!", completion = "Meine Gäste sollten das passabel finden. Sagt ihnen nur nicht, dass es von Awilo kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13114] = { id = 13114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanaleintopf", description = "Wir haben eine neue Bestellung. Der Gastwirt in der Kanalisation von Dalaran braucht einen Gemüseeintopf, weil seine Kunden nich' so viel zu essen haben, Mann.\n\nDer hat deswegen nach einem Gemüseeintopf gefragt, da er meinen letzten Eintopf mit dem Gnom drin nicht so gern gemocht hat. Besorg dir 4 Kristallsangkarotten aus dem Kristallsangwald, koch sie gemeinsam mit 4 Stück kühlem Fleisch und bring das Resultat anschließend zu Ajay.\n\nDu kannst den Wald über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.", sourceObjective = "Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nBringt den Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.", progress = "Gebt Acht, dass diesmal kein Gnom im Eintopf ist!", completion = "Eintopf sieht gut aus. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[13115] = { id = 13115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käse für Leuchtegold", description = "Ranid Leuchtegold im Lederladen verlangt es ordentlich nach Wein und Käse. Warum er keinen leckeren Gnom mag, versteh ich nicht.\n\nHol dir den Käse aus dem Käseladen in der Mitte von Dalaran und die halbvollen Weingläser, die auf den Tischen in der Stadt stehen. Geh danach zu Ranid und servier ihm Wein und Käse.\n\nDen Wein könnte man sozusagen als \"Auslese\" bezeichnen, Mann.", sourceObjective = "Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.\n\nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.", progress = "Habt Ihr einen Diener mit meiner Wein- und Käseplatte gesehen? Mich hat der kleine Hunger gepackt!", completion = "Dieser Wein ist ziemlich beeindruckend! Ich muss wissen, woher er kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13116] = { id = 13116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senfwürstchen!", description = "Erzmagier Pentarus schaut sich gerne sein verrücktes Kampfballspiel an, doch dafür braucht er auch was zu essen.\n\nDu musst seinen Picknickkorb mit 4 gekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Ecken der Stadt zu finden.\n\nFüll seinen Korb mit den leckeren Senfwürstchen auf, Mann.", sourceObjective = "Füllt den leeren Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.\n\nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran.", progress = "Stellt sicher, dass die wilden Senfwürstchen 100% Rhinozeros sind und dass kein Gnom drin ist!", completion = "Perfekt! Ich hoffe nur, dass die Dalaraner Demolierer endlich mal ein Spiel gewinnen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[13117] = { id = 13117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo kommen sie her?", description = "Die unermüdlichen Lakaien des Lichkönigs arbeiten Tag und Nacht an der Erschaffung zahlloser neuer Monstrositäten und Fleischriesen da unten in den Fleischwerken.\n\nAber das war noch nicht alles. Mehr und mehr skelettene Arbeiter tauchen auf und beschleunigen die Arbeit noch zusätzlich.\n\nWenn wir nicht herausfinden, wo sie herkommen und wie sie so schnell arbeiten können, werden wir überrannt, bevor wir die Initiative übernehmen können. Sucht im Südosten und findet die Quelle dieser Skelette!", sourceObjective = "Untersucht einen Beschwörungsaltar im östlichen Teil der Fleischwerke und berichtet dann Dunkelreiterin Arly bei der Schwarzwacht davon.", progress = "Habt Ihr den Ursprung dieser Skelette gefunden?", completion = "<Ihr berichtet der Dunkelreiterin von Euren Entdeckungen beim Beschwörungsaltar.>\n\nSo etwas habe ich vermutet. Das dürfen wir nicht länger zulassen. Unsere oberste Priorität ist es, diese Beschwörungsaltäre zu zerstören, dann erst kümmern wir uns um das Unheil, das die Geißel hier bereits erschaffen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13118] = { id = 13118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung von Geißelholme", description = "Die Geißel hat ihre Armeen gegen den Argentumkreuzzug gesandt und ist zurückgeschlagen worden. Was sie jetzt macht, nennt sich \"zuschlagen und niederbrennen\". Alle Gefangenen, die sie in Geißelholme gefangen halten, werden hingerichtet und als Diener des Lichkönigs wiederbelebt.\n\nOhne Zweifel wird der Argentumkreuzzug wünschen, dass Ihr seine Soldaten in Ehren verabschiedet. Etwas Derartiges werde ich nicht von Euch verlangen. Um zu siegen, müssen wir die Geißel unterschiedslos ausmerzen.\n\nZieht nach Geißelholme, nordwestlich durch die Bresche, und mäht alle nieder, die sich Euch in den Weg stellen.", sourceObjective = "Der Schwarze Wächter im Tal der Echos möchte, dass Ihr 3 Hohepriester der Vergessenen Tiefen, 3 Unterkönige der Vergessenen Tiefen und 8 wiedererweckte Kreuzfahrer tötet.", completion = "Das habt Ihr gut gemacht, {name}. Ihre Zahlen gering zu halten wird dem Argentumkreuzzug die Zeit geben, die er braucht, um Fuß fassen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13119] = { id = 13119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Altäre", description = "Sie beschwören also ihre Arbeiter und Krieger an diesen Altären?\n\nDie werden als Erstes verschwinden müssen. Der Meisterbeschwörer sollte einen Stab haben, mit dem er das Portal aktivieren kann. Wenn Ihr ihn also tötet und seinen Stab nehmt, dann könnt Ihr mit ihm das Beschwörungsportal überladen und dessen Altar zerstören.\n\nFührt diese Prozedur bei allen vier Altären durch und kehrt zu mir zurück, sobald sie zerstört wurden.", sourceObjective = "Tötet Meisterbeschwörer Zarod und benutzt seinen Beschwörerstab, um den ersten, zweiten, dritten und vierten Beschwörungsaltar zu zerstören. Habt Ihr diese Aufgabe erledigt, kehrt zu Dunkelreiterin Arly bei der Scharzwacht zurück.", completion = "<Dunkelreiterin Arly nickt anerkennend.>\n\nGut. Jetzt können wir unser Augenmerk darauf richten, den Rest der Fleischwerke zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13120] = { id = 13120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesblick", description = "Die Fleischwerke sind eine gewaltige Operation, und es wird schwer, alles, was sich dort abspielt, im Auge zu behalten. Zum Glück habe ich einen Plan.\n\n<Arly holt eine Kugel aus den Falten ihres Umhangs hervor und zeigt sie Euch.>\n\nDies ist eine Kugel des Todesblicks. Mit ihr können wir die Aktionen der Geißel verfolgen und entscheiden, wie wir am besten zuschlagen.\n\nLegt diese Kugeln auf die Halterungen, die in drei äußerst wichtigen Bereichen zu finden sind: im Monstrositäten- und Fleischriesenlabor gen Südwesten und auch in der Gegend um den riesigen grünen Kessel weit im Westen.", sourceObjective = "Benutzt die Kugel des Todesblicks, um Kugeln in die Kugelhalterung des Monstrositätenlabors, des Fleischriesenlabors und des Kesselbereichs zu legen. Kehrt anschließend zu Dunkelreiterin Arly in die Schwarzwacht zurück.", progress = "Habt Ihr diese Kugeln in ihre Halterung gelegt?", completion = "<Dunkelreiterin Arly schließt ihre Augen und scheint sich auf etwas zu konzentrieren, das weit in der Ferne liegt.>\n\nMit den Augen des Todes selbst beobachte ich unseren Feind. Dieses Wissen wird uns helfen, ihn endgültig zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13121] = { id = 13121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Innere Auge", description = "Wir müssen die Werkzeuge des Lichkönigs gegen ihn richten, wenn wir unseren nächsten Schritt in die Wege leiten wollen.\n\nHinter den Bergen im Südwesten liegt die Feste Kul'galar. In ihr halten sich die Orakel von Jotunheim auf, die Befehle von ihrem Meister empfangen und andere durch das Auge des Lichkönigs ausspionieren.\n\nEs ist jenes Auge, zu dem Ihr Euch durchkämpfen müsst. Obwohl man es nicht dazu verwenden kann, den Schleier um die Eiskronenzitadelle zu durchdringen, solltet Ihr dennoch Wertvolles mit seiner Hilfe herausfinden können, so dass wir wissen werden, wie wir am besten weiter vorgehen.", sourceObjective = "Die Knochenhexe in Njorndar hat Euch beauftragt, das Auge des Lichkönigs zu benutzen, um an Informationen zu gelangen.", completion = "Perfekt! Es ist wahr, dass Iskalder angeblich der größte Vrykulkrieger sein soll, der je existiert hat. Und Vardmadra selbst wird herkommen, um ihn zu bewerten!\n\nWir müssen sofort handeln, wenn wir vor ihnen zu diesem alten Helden gelangen wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13122] = { id = 13122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geißelstein", description = "Ein Geißelstein ist ein Gegenstand, der allen Einheiten der Geißel bei Geburt oder Erschaffung übergeben wird. Es verleiht dem Träger gewisse Vorteile, aber was wichtiger ist, gewährt den Anführern der Geißel jederzeit Einblick in den Aufenthaltsort und die Bewegungen all ihrer Einheiten.\n\nMit genügend Geißelsteinen sollte ich in der Lage sein, die Bewegungen anderer Geißeleinheiten in Eiskrone zu überwachen.\n\nSammelt alle Geißelsteine, die Ihr finden könnt, während Ihr Geißelkrieger in Geißelholme tötet. Kehrt zu mir zurück, wenn eure Taschen voll sind.", sourceObjective = "Der Schwarze Wächter im Tal der Echos möchte, dass Ihr ihm 15 Geißelsteine bringt.", progress = "Geißelsteine werden uns dabei helfen, den Gegner aufzuspüren.", completion = "Dann lasst uns doch mal sehen, ob ich uns mit diesen Steinen nicht ein wenig Einblick verschaffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13124] = { id = 13124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf geht weiter", description = "Malygos und seine Handlanger werden von Tag zu Tag stärker. Jetzt hat man auch noch unsere jüngste Angriffseinheit gefangengenommen und hält sie im Oculus fest.\n\nWir müssen versuchen, sie zu befreien! Belgaristrasz und seine Gefährten sind für uns unerlässlich.", sourceObjective = "Raelorasz möchte, dass Ihr Belgaristrasz und seine Gefährten aus dem Oculus befreit.", completion = "Hört gut zu, {race}.\n\nEure Arbeit hier hat gerade erst begonnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13125] = { id = 13125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luft steht still", description = "Ihr müsst die Herren von Geißelholme besiegen, wenn dieser Ort vom Würgegriff der Geißel befreit werden soll.\n\nSalranax der Zerfleischer steht dem Tempel auf der ersten Ebene von Geißelholme vor. In der Nähe von Salranax findet Ihr den Hohepriester Yath'amon, der beim Geisterturm auf der zweiten Ebene predigt. Unterkönig Talonox hält bei der Schreckensgrube Hof, die obere Straße hinauf.\n\nSie sind alle herausragende Gegner und sollten mit Bedacht angegangen werden. Benutzt dieses Kriegshorn, wenn Ihr Hilfe brauchen solltet. Die Todesritter von Acherus werden kommen.", sourceObjective = "Der Schwarze Wächter beim Tal der Echos in Eiskrone will, dass Ihr Salranax den Zerfleischer, Unterkönig Talonox und Hohepriester Yath'amon tötet.", progress = "Erledigt sie, {name}!", completion = "Ein hart erkämpfter Sieg, {name}! Die Leutnants werden ausgetauscht, aber zumindest für heute steht die Luft um Geißelholme still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13126] = { id = 13126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinte Front", description = "Von jetzt ab werden wir unsere Kräfte vereinen müssen, um weiter voranzukommen.\n\nVaros über uns versteckt sich hinter einem undurchdringlichen Schild. Um zu ihm zu gelangen, müsst Ihr die Zentrifugenkonstrukte zerstören, die diesen Schild mit Energie versorgen.\n\nJeder von uns kann Euch Drachen des jeweiligen Schwarms zur Verfügung stellen. Sie werden Euch helfen, ihn zu enthüllen.", sourceObjective = "Belgaristrasz möchte, dass Ihr 10 Zentrifugenkonstrukte zerstört, um Varos' Schild zu beseitigen. Danach müsst Ihr Varos Wolkenwanderer besiegen.", completion = "Es ist, wie ich es erhofft hatte, {race}. Wir arbeiten gut zusammen.\n\nMöge unsere fortwährende Kooperation genügen, um die vor uns liegenden Aufgaben zu bewältigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13127] = { id = 13127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierlord Urom", description = "Zwischen uns und unserem ultimativen Ziel hier steht nur noch ein Hindernis. Sein Name ist Urom.\n\nEr bewacht den dritten Ring über uns. Nehmt Euch vor seiner mächtigen Zauberei in Acht.\n\nStreckt ihn nieder. Lasst ihn dafür büßen, dass er dem Feind die Treue geschworen hat!", sourceObjective = "Belgaristrasz möchte, dass Ihr Magierlord Urom im Oculus besiegt.", progress = "Habt Ihr Euch um Magierlord Urom gekümmert?", completion = "Der Sieg ist in Reichweite, Freund.\n\nKonzentration, denn jetzt kommt die wahre Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[13128] = { id = 13128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht in den Wolken", description = "Die Zeit ist gekommen, Euch Eregos zu stellen.\n\nEr bezieht seine Kraft aus den Energien, mit deren Verteidigung er beauftragt wurde... er trinkt aus dem Brunnen des großen Aspekts Malygos.\n\nJedoch können wir dank des Sieges über den Magierlord nun die volle Kraft unserer Drachen entfesseln. Eregos wird Euch sicherlich unterliegen, wenn Ihr sie weise einsetzt.", sourceObjective = "Belgaristrasz möchte, dass Ihr Eregos im Oculus tötet.", completion = "<Raelorasz hört Euch aufmerksam zu.>\n\n{name}, das sind höchst willkommene Neuigkeiten.\n\nSeit Anbeginn dieses Konfliktes haben wir dem Lord der Magie keinen Schlag dieser Größenordnung versetzt.\n\nBitte, Freund, akzeptiert den Dank unserer vereinten Drachenschwärme.", sourceObjectiveStatus = "unverified-source-field" }
quests[13129] = { id = 13129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Psychospielchen", description = "<Kurzel reißt einen langen Streifen ihrer Bluse heraus und drückt ihn Euch in die Hand.>\n\nHier, {race}, nehmt. Taucht den Stoff in die Überreste von Novos dem Beschwörer.\n\nWir finden schon noch raus, was die Anführer der Geißel antreibt.", sourceObjective = "Kurzel möchte, dass Ihr den Fetzen von Kurzels Bluse auf die Reste von Novos dem Beschwörer anwendet und anschließend den sekretbefleckten Stoff zu ihr in die Feste Drak'Tharon bringt.", progress = "Habt Ihr das Tuch?", completion = "Hoffentlich finden wir jemanden, der bereit ist, diese Probe zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13130] = { id = 13130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stein, der eine Revolution auslöste", description = "Wenn Ihr Geißelholme heute betrachtet, mögt Ihr lediglich eine ranzige Grube der Verwesung sehen, aber eines Tages wird es ein Ort voll Pracht und Ehre sein. Hochlord Fordring hat den Namen \"Festung der Gerechtigkeit\" auserkoren.\n\nNun, selbst der Bau einer uneinnehmbaren Festung wie der Eiskronenzitadelle hat mit einem einzelnen Stein begonnen. Und so beginnt unsere Suche nach dem Stein, der eine Revolution auslösen wird.\n\nReist nach Kristallsang, südlich von hier, und sucht das Unbändige Dickicht im Osten. Sobald Ihr dort seid, sammelt kristallines Kernholz vom Boden des Dickichts und elfisches Mauerwerk von den Ruinen von Shandaral.", sourceObjective = "Kreuzzugsarchitekt Silas im Tal der Echos in Eiskrone möchte, dass Ihr 10 Stämme kristallines Kernholz und 10 Stücke altes elfisches Mauerwerk sammelt.", progress = "Habt Ihr Euch verlaufen?", completion = "Kernholz ist von Natur aus resistent gegen Verrottung, Krankheit und Seuche. Dieses Kernholz jedoch schlägt diese Dinge sogar zurück! Auch das Bauwerk, das nun noch den Auswirkungen des unbändigen Dickichts ausgesetzt ist, wird in ähnlicher Weise wirken.\n\nBald schon werden wir einen großen Schritt weiter sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13131] = { id = 13131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrott in der Truhe", description = "Seh dir das nur an! Meine Truhe war noch nie sou leer.\n\nMeine Jungs machten Luftsprünge, als sie all die Beude sah'n, und nu? Seh sie dir nur mal an! Nichts als Knochengerippe!\n\nWeiter drinnen gibt es mehr als genug Beude und sie ist nicht von der verfluchten Sorte, darauf würd ich wetten!\n\nBring mir die Beude und ich werde dich reich belounen, Kumpel.", sourceObjective = "Brigg im Turm Utgarde möchte, dass Ihr 5 blitzblanke Silberbarren, 3 glänzende Schmuckstücke, 2 goldene Kelche und eine Jadestatue beschafft.", progress = "Wie ging's dir da drin, Kumpel?", completion = "Klasse! Du hast's geschafft, Kumpel.\n\nNu kann ich mein Gesicht dem Käpt'n zeigen, ohne um mein Leben fürcht'n zu müssen - dir und deinen Kameraden sei Dank.\n\nHier ist noch ein wenig Beude als Gegenleistung für dich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13132] = { id = 13132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache ist mein!", description = "Glück allein hat mich vor dem Schicksal meiner Kumpel bewahrt. Bei dem Trubel wurde ich umgestoßen - war von Anfang an ein wenig angeheitert gewesen. Also, ich hab dann hochgeguckt und sah, wie sich die ersten von ihnen verwandelten...\n\nDa stand so'n riesen Kerl mit jeder Menge Wachen, der sich das alles ansah. Sie sangen den Namen Ymiron... Wenn Ihr ihn umbringt, werden meine Kumpel vielleicht befreit.", sourceObjective = "Brigg im Turm Utgarde möchte, dass Ihr König Ymiron tötet.", progress = "Hast du denjenigen gefunden, der hier das Sagen hat, {race}?", completion = "Großartig! Vielleicht werden meine Kumpel jetzt in Frieden ruhen können.\n\nHier, Junge. Es soll nich' heißen, dass der alde Brigg nich' großzügig zu denjenigen sei, die ihm einen Gefallen getan haben.\n\nGut, mit dir Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13133] = { id = 13133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Held aus alter Zeit", description = "Rasch, {name}, geht in den Südwesten zu den Hallen der Vorfahren!\n\nDort werdet Ihr auf die schlummernden Mjordin stoßen. Weckt sie, bis Ihr Iskalder gefunden habt. Dann setzt dieses Amulett bei ihm ein und bringt ihn zu mir.\n\nGeht jetzt. Die Zeit ist knapp!", sourceObjective = "Die Knochenhexe aus Njorndar möchte, dass Ihr mit Iskalder zurückkehrt.", progress = "Wo ist der Held aus alter Zeit?\n\nWir haben keine Zeit zum Plaudern. Geht zu den Hallen der Vorfahren und findet ihn, bevor es zu spät ist!", completion = "Er ist ein schönes Exemplar und wird uns gute Dienste erweisen.\n\nNun müssen wir dafür sorgen, dass wir Vardmadra mit ihm in die Falle locken!", sourceObjectiveStatus = "unverified-source-field" }
quests[13134] = { id = 13134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst ihr Blut fließen", description = "Die Geißel kann ihre Fleischmonster nicht ohne Blut und Balsamierungsflüssigkeit erschaffen, da die Teile geschützt und funktionsfähig bleiben müssen. Wenn wir ihnen diese Materialien nehmen würden, bräche ihre Armee auseinander und wir könnten ihre Schöpfungen mit Leichtigkeit zerstören.\n\nIn allen Laboren, in denen Fleischriesen und Monstrositäten zusammengeflickt werden, werdet Ihr Bottiche mit Balsamierungsflüssigkeit sowie riesige Kugeln voller Blut finden. Zerstört sie und bringt all jenen, die Euch aufhalten wollen, den Tod!", sourceObjective = "Dunkelreiterin Arly aus der Schwarzwacht möchte, dass Ihr 5 Bottiche mit Balsamierungsflüssigkeit und 5 Blutkugeln zerstört.", completion = "<Ein dunkles, hohles Lachen hallt Euch entgegen, als Ihr zur Dunkelreiterin kommt.>\n\nIhr riecht nach Sieg, {name}, und das sind wahrlich gute Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13135] = { id = 13135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es könnte uns alle umbringen", description = "Südöstlich von hier, am Ostrand des Kristallsangwaldes, befindet sich ein Gebiet, das man Unbändiges Dickicht nennt. Die verschiedensten Kreaturen leben dort, jedoch alle von ihnen teilen die Eigenschaft der Bindung an magische Energien. Jedes von ihnen enthält reine, kristallisierte Energie, die uns alle töten könnte, wenn sie je instabil würde!\n\nBegebt Euch ins Unbändige Dickicht und tötet seine Bewohner, um die kristallisierte Energie zu erhalten. Wir benötigen Treibstoff, sie müssen sterben - von welcher Seite man es auch betrachtet, für uns ist es von Vorteil.", sourceObjective = "Kreuzzugsingenieur Spitzpatrick aus dem Tal der Echos in Eiskrone möchte, dass Ihr 8 Stücke kristallisierte Energie besorgt.", progress = "Habt Ihr die kristallisierte Energie?", completion = "Ah, das ist perfekt, Der Bomber müsste in null Komma nichts einsatzbereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13136] = { id = 13136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezackte Splitter", description = "Ihr habt diesen gezackten, dunklen, brüchigen Splitter aus dem Körper eines Ghul gezogen. Die metallische Klinge ist nicht glatt und wurde vermutlich von einer ungeübten Hand geschmiedet oder aus einem größeren Stück herausgebrochen.\n\nIhr erinnert Euch, ähnliche Splitter in den Körper aller Ghule, die Euch in den Fleischwerken begegnet sind, gesehen zu haben, daher fragt Ihr Euch, warum ihre Schöpfer überhaupt Metall verwendet haben. Möglicherweise fällt Kreuzfahrer Olakin Sainrith dazu etwas ein, wenn Ihr ihm die Splitter aus mehreren Ghulen bringt.", sourceObjective = "Bringt Kreuzfahrer Olakin Sainrith in der Schwarzwacht 10 gezackte Splitter.", progress = "Was ist das Widerliches?", completion = "<Olakin begutachtet die Splitter vorsichtig.>\n\nIhr habt so etwas bei allen Ghulen da unten gesehen? In all meinen Kämpfen gegen die Geißel ist mir so etwas noch nie begegnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13137] = { id = 13137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht so ehrenhafter Kampf", description = "Auf dem höchsten Gipfel im Südwesten über Jotunheim liegt die Kriegsnarbenwarte. Dieser Ort ist den Vrykul heilig und hier tragen sie neben Valhalas gern ihre ehrenhaften Kämpfe aus.\n\nWir werden einen nicht so ehrenhaften Kampf dort besuchen.\n\nRuft Eure Gefährten zusammen und fliegt zum Turm. Entzündet das Signalfeuer, wenn Ihr bereit seid, und ich werde in Iskalders Gestalt erscheinen.\n\nWir werden kämpfen, Ihr werdet siegen, und Vardmadra wird gewiss anwesend sein, um sich den Kampf anzusehen!", sourceObjective = "Die Knochenhexe aus Njorndar möchte, dass Ihr Iskalder auf der Kriegsnarbenwarte besiegt.", completion = "Ich habe Vardmadra vorerst in Sicherheit gebracht, und an diesem Ort wird sie bleiben, bis wir unsere endgültige Rache nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13138] = { id = 13138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich schmelze... schmelze!", description = "<Olakin wendet einen der Splitter in seiner gepanzerten Hand.>\n\nMit genug Energie dahinter könnten sie Rüstungen durchdringen. Wir müssen herausfinden, woraus sie bestehen und was der Lichkönig mit ihnen vorhat.\n\nIm Osten in der Nähe der Eiskronenzitadelle liegt Malykriss. Aus den wenigen Berichten, die uns vorliegen, geht hervor, dass es voller Ausrüstung zum Verhütten und Schmieden ist. Bringt die Splitter dorthin und schmelzt sie in einem der offenen Hochöfen auf der untersten Ebene von Malykriss ein. Sobald das Metall eingeschmolzen und verändert ist, können wir es identifizieren.", sourceObjective = "Benutzt die Tasche mit gezackten Splittern in der Nähe eines der Hochöfen auf der untersten Ebene von Malykriss. Kehrt mit dem verhütteten Metallbarren zum Kreuzfahrer Olakin Sainrith bei der Schwarzwacht zurück.", progress = "Habt Ihr diese Fragmente schon eingeschmolzen?", completion = "Es besteht kein Zweifel, dies ist Rohsaronit. Wir haben daraus hergestellte Waffen in den Händen von Günstlingen des Lichkönig gesehen, aber dies ist das erste Mal, dass es für andere Zwecke benutzt wird. Der Umfang dieser Minenarbeiten muss riesig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13139] = { id = 13139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im gefrorenen Herzen Nordends", description = "Silas und Spitzpatrick haben nun genug Material und Treibstoff, um mit dem Bau der Festung der Gerechtigkeit zu beginnen. Ihr und die Schwarze Klinge haben dafür gesorgt, dass die Geißel in Geißelholme dezimiert wurde und ihre Leutnants besiegt sind.\n\nIch habe mich entschieden, wo wir beginnen werden, doch zuerst müsst Ihr Hochlord Tirion Fordring meinen Bericht überbringen. Auf seinen Befehl hin werden wir in Eiskrone einmarschieren.", sourceObjective = "Liefert Vater Gustavs Bericht bei Hochlord Tirion Fordring in der Argentumvorhut in Eiskrone ab.", progress = "Steht bequem, {name}. Was gibt es zu berichten?", completion = "Eure Hilfe bei der Sicherung der Front war ein wesentlicher Bestandteil. Der erste echte Sieg in diesem Krieg ist nahe - daher ist unser nächster Schritt auch von größter Wichtigkeit.\n\nSeid unbesorgt, {name}, die Geißel wird nicht kampflos aufgeben. Eure größte Herausforderung steht Euch noch bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[13140] = { id = 13140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runenschmiede von Malykriss", description = "Die Splitter, die Ihr gefunden habt, können nur von einem Ort stammen: aus Malykriss. Hier, östlich von Corp'rethar, finden alle Metallarbeiten des Lichkönigs statt.\n\nVerwirrend daran ist, dass man kein Metall benötigt, um die Monstrositäten oder Fleischriesen zusammenzuflicken oder um die Skelettdiener zu beschwören. Findet die Skelettrunenschmiede auf der untersten Ebene von Malykriss und nehmt die Platten, die sie bearbeiten, an Euch. Wir müssen herausfinden, warum dieses Metall in den Fleischwerken Verwendung findet.", sourceObjective = "Bringt Kreuzfahrer Olakin in der Schwarzwacht 5 runenverzierte Saronitplattenrüstungen.", progress = "Konntet Ihr diese runenverzierten Platten an Euch bringen?", completion = "Diese Platten sehen fast genauso aus wie die Splitter. Sie müssen die herausgeschnittenen Stücke dafür verwenden, um die hier produzierten Ghule zu verbessern. Die Geißel ist verzweifelt genug, um aus allem eine Waffe herzustellen, wie es scheint. Umso mehr ein Grund, diesen schrecklichen Ort umso schneller zu zerstören!", sourceObjectiveStatus = "unverified-source-field" }
quests[13141] = { id = 13141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Kreuzfahrerturm", description = "<Hochlord Fordring hält ein Banner des Argentumkreuzzugs in den Händen.>\n\nDieses Banner ist unvergleichlich, {name}. Es enthält einen mächtigen Segen, der große Teile verseuchten Landes reinigen kann.\n\nIhr müsst es durch die Bresche in den Nordwesten in ein Gebiet bringen, das die Geißel spöttisch Kreuzfahrerturm nennt. Stellt das Banner auf die Schädel unserer am Kreuzfahrerturm gefallenen Brüder und verteidigt es gegen alle Angriffe. Sobald das Land gereinigt ist, kehrt Ihr zu Vater Gustav zurück.\n\nGeht jetzt, {name}, und habt keine Furcht.", sourceObjective = "Begebt Euch zum Kreuzfahrerturm und platziert das gesegnete Banner des Kreuzzugs auf dem Haufen Kreuzfahrerschädel. Verteidigt das Banner gegen den Angriff der Geißel, bis das Land auf dem Turm gereinigt ist. Kehrt dann zu Vater Gustav ins Tal der Echos in Eiskrone zurück.", completion = "Gesegnetes Licht! Wir haben den Turm eingenommen! Endlich können wir mit dem Bau der Festung der Gerechtigkeit beginnen. Hochlord Fordring und die Ritter sind bereits zu unserer neuen Basis aufgebrochen. Ihr müsst Euch dort mit ihnen treffen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13142] = { id = 13142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache der Banshee", description = "Die Zeit ist gekommen, {name}. Ihr müsst mit Euren Freunden den Fürsten der Festung Balargarde, den Meister von Jotunheim, Oberthan Balargarde, herausfordern.\n\nAm höchsten Punkt der Festung, die sich am Südwestrand von Jotunheim befindet, werdet Ihr auf ein Horn stoßen. Blast hinein und lasst all jene, die unerschütterlich genug sind, Eure Herausforderung hören.\n\nBalargarde wird keine andere Wahl haben, als sich Euch zu stellen. Und ich... Verzeihung, Vardmadra wird dort sein, um das Urteil zu fällen.\n\n<Die von einer Banshee besessene Vrykul stößt ein bellendes Lachen aus.>", sourceObjective = "Die Knochenhexe aus Njorndar möchte, dass Ihr für sie Rache nehmt, indem Ihr Oberthan Balargarde herausfordert und besiegt.", completion = "Was ich im Moment fühle, lässt sich nicht in Worte fassen, {name}. Meine Rache ist vollzogen, und es gibt hier für mich nichts mehr zu tun.\n\nKönnte ich doch hier sein, wenn der Lichkönig endlich gestürzt wird.\n\nAber lasst Euch nicht täuschen, denn Jotunheim ist noch lange nicht 'erledigt'. Ich werde diese Hexe weiterhin unter Kontrolle behalten, bis die Vrykul keine Bedrohung mehr darstellen.\n\nSeht Euch um, in dieser Höhle könnt Ihr viele wertvolle Dinge sehen. Sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13143] = { id = 13143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Rekrut", description = "Eins nach dem anderen. Ich habe ein paar geschmeidige Pirscher auf den Bollwerken östlich von hier gesehen. Sie hatten uns gedient, bevor wir uns von Arthas losrissen. Außerdem sind sie so ziemlich die besten Kundschafter, die es gibt, wenn man sie mit dem Auge der Herrschaft nur ein wenig antreibt.\n\nFliegt dorthin, findet einen der Pirscher, setzt ihm ein wenig zu, wendet dann dieses Siegel der Schwarzen Klinge auf ihn an und er wird Euch gehorchen. Führt ihn anschließend zur Spitze der Felsen nordöstlich von hier und er wird seinen Weg zu mir finden.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr einen unterworfenen geschmeidigen Pirscher zur Spitze der Felsen nordöstlich der Anhöhe des Leidens bringt.", progress = "Ich bin mir sicher, dass ihre neuen Meister nicht zimperlich mit ihnen umgehen werden; doch sie werden die Striemen, die wir ihnen beibrachten, auf jeden Fall nicht vergessen. Sie werden diese Siegel fürchten, solange sie leben.", completion = "Ich habe den armen Teufel an den Pfosten dort drüben gekettet und werde mir noch mehr von ihnen schnappen.\n\nNa, dann lasst uns doch das Auge mal ein wenig benutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13144] = { id = 13144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Geißeln mit einem Skelett schlagen", description = "Einige ihrer Kreationen haben die Arbeiter in den Fleischwerken bereits fertiggestellt. Im Moment sind die Kreaturen noch an die Säulen rund um die Kante des Labors gekettet, aber wenn wir nicht schnell etwas unternehmen werden sie mit den Armeen des Lichkönigs marschieren.\n\nAus den auf dem Boden der Fleischwerke verteilten Knochenhaufen ragen gierig greifende Arme heraus. Diese Arme gehören zu Skeletten, die mit der Macht des Feuers belegt sind. Findet und befreit diese Skelette, bringt sie in die Nähe der fertigen Monstrositäten und genießt die Vorstellung!", sourceObjective = "Dunkelreiterin Arly an der Schwarzwacht möchte, dass Ihr 3 angekettete Monstrositäten mit brennenden Skeletten zerstört.", completion = "Ah, gut. Es geht doch nichts über den Geruch von verbranntem fauligen Fleisch am Morgen. Der Geruch ist ein Sieg über die Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13145] = { id = 13145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unheilvolle Festung", description = "Wir müssen wissen, mit was wir es zu tun haben.\n\nBringt mithilfe des Auges der Herrschaft einen geschmeidigen Pirscher unter Eure Kontrolle und erkundet die Gegend. Als ich hierher geflogen bin, habe ich ein paar Stellen gesehen, die Ihr für mich genauer untersuchen sollt: die Warte im Nordosten, das Gebiet der Arbeiter im Südosten, die große Schmiede in der Nähe des Zentrums und den Ritualbereich im Südwesten.\n\nDer Pirscher kann weit springen und Stürze aus größerer Höhe machen ihm nichts aus. Nutzt dies zu Eurem Vorteil und die Bollwerke werden kein Hindernis mehr darstellen.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr mithilfe eines geschmeidigen Pirschers Malykriss erkundet.", progress = "Fliegen mag zwar etwas eleganter sein, aber wir hätten ohne den Pirscher nie so nah herankommen können, ohne dabei gesehen zu werden.", completion = "Ausgezeichnete Arbeit. Es scheint, dass mehr Todesritter Arthas treu geblieben sind, als ich zuerst dachte.\n\nEr versucht Acherus mit allen Mitteln zu ersetzen, so viel steht fest. Eine Zitadelle komplett aus Saronit wäre mit Sicherheit nicht leicht zu zerstören. Doch das müssen wir gar nicht... Wir können dem Treiben hier und jetzt ein Ende bereiten und die Anführer der Todesritter aus dem Weg schaffen, bevor sie eine wirkliche Bedrohung darstellen.\n\nUnd was am allerwichtigsten ist: Wir müssen für genug Tumult sorgen, um diese Todesritter von ihren Anführern zu trennen, damit wir zuschlagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13146] = { id = 13146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Großzügigkeit", description = "Wir müssen für ein wenig Tumult sorgen, um diese Todesritter von ihren Anführern wegzubekommen. Ich nehme an, dass, sollten wir ihre Untergebenen dort unten beseitigen, sie ihren Operationen mehr Aufmerksamkeit widmen müssten.\n\nMonstrositäten sind leichte Beute - langsam, berechenbar und was am allerwichtigsten ist: sie sind dumm. Nutzt ihr Vertrauen zu den Pirschern, um die Geißelbomben, die überall in dem Gebiet herumliegen, zu ihnen zu schleifen. Ihr werdet sie anzünden können, lange bevor die Monstrositäten überhaupt herausfinden, wie ihnen geschieht.", sourceObjective = "Vereth der Gewiefte möchte, dass Ihr nach Malykriss geht und mithilfe der Eisenkette des geschmeidigen Pirschers eine Geißelbombe zu einer schwerfälligen Schreckensgestalt zieht. Tötet auf diese Weise 4 schwerfällige Schreckensgestalten.", completion = "Sie sind nicht einmal auf den Gedanken gekommen, Hand an Euch zu legen, stimmt's? Wenigstens sind sie berechenbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13147] = { id = 13147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuppler", description = "Der Hauptunterschied zwischen Vargul und niederen untoten Günstlingen ist, dass die Vargul noch über so viel Verstand verfügen, um es zu verabscheuen, als Arbeiter herangezogen zu werden. Niemals wird es einem Vargul gefallen, an der Seite von Skeletten oder Ghulen arbeiten zu müssen.\n\nWir werden uns diese Abneigung zunutze machen und Zwietracht zwischen den Umbralschlägern und den anderen Untoten in Malykriss säen. Das sollte die Produktion abbremsen und die Todesritter zum Babysitting zwingen.\n\nSollte einfach zu machen sein - ein paar Steine auf die Schläger, sobald sie sich den niederen Untoten nähern, werden genügen.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr einen geschmeidigen Pirscher benutzt, um in Malykriss Steine auf Umbralschläger zu werfen, sobald sie sich niederen Untoten nähern. Kehrt zurück, sobald Ihr 5 Kämpfe provoziert habt.", completion = "Gibt also keinen Grund, unsere eigenen Männer zu opfern, wenn sie sich so leicht beeinflussen lassen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[13148] = { id = 13148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halskettenreparatur", description = "Bei der kaputten Halskette liegt eine Rechnung, auf der steht: \"Eigentum von Jonas Timotheus - Cartier & Co., edle Juwelierwaren - Handelsmarkt der Magier - Dalaran\".\n\nVielleicht solltet Ihr sie reparieren und zu ihm zurückbringen.", sourceObjective = "Repariert die Halskette mit einem einzigen Chalzedon und bringt sie zu Jonas Timotheus im Juwelierladen auf dem Handelsmarkt der Magier in Dalaran.", progress = "Was führt Euch hierher?", completion = "Wo habt Ihr das gefunden?! Vor ein paar Wochen ging eine Lieferung von mir raus und viele dieser Halsketten wurden daraus gestohlen! Lasst mich meine Schuld begleichen und Euch dieses Juwelierssymbol geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13149] = { id = 13149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusionen bannen", description = "Der ewige Drachenschwarm möchte Prinz Arthas hinters Licht führen und auf diese Weise die Geschichte verändern.\n\nWenn er sich davon überzeugen lässt, dass keines der Körner hier verseucht ist, dann wird er seine verhängnisvolle Entscheidung niemals treffen und die Einwohner Stratholmes am Leben lassen.\n\nWendet diesen arkanen Disruptor auf alle Kornkisten an, die Euch verdächtig erscheinen.", sourceObjective = "Chromie möchte, dass Ihr den arkanen Disruptor auf die verdächtigen Kisten im Stratholme der Vergangenheit anwendet und sie anschließend am Eingang von Stratholme trefft.", completion = "Das habt Ihr gut gemacht, Freund. Arthas' Truppen haben das verseuchte Korn entdeckt.\n\nHört jetzt gut zu. Es gibt noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13150] = { id = 13150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDLost: Widget", description = "Unten am Apparat ist eine Rechnung, laut der \"Jonas Timotheus - Juwelier\" in Dalaran der Besitzer ist. Wenn Ihr ihn reparieren und zu ihm zurückbringen würdet, vielleicht würde er Euch dann belohnen.", sourceObjective = "Repariert den Apparat und bringt ihn zu Jonas Thimotheus im Juwelierladen in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[13151] = { id = 13151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eskorte des Königs", description = "Schon bald wird Arthas vor einem verzweifelten Dilemma stehen und eine folgenschwere Entscheidung treffen.\n\nIch muss Euch bitten, den Prinzen bei seiner Ausmerzaktion in Stratholme zu begleiten.\n\nArthas muss lebend durch Stratholme kommen und Ihr müsst dafür sorgen, dass er Mal'Ganis besiegt!", sourceObjective = "Chromie möchte, dass Ihr Arthas bei seiner Ausmerzaktion in Stratholme begleitet. Ihr sollt wieder mit ihr sprechen, nachdem Mal'Ganis besiegt ist.", completion = "Das habt Ihr gut gemacht, {name}.\n\nDer Plan des ewigen Drachenschwarms wurde durchkreuzt und die Geschichte bleibt, wie sie ist.\n\nEure Unterstützung war von unschätzbarem Wert - nehmt meinen Dank und auch den des gesamten bronzenen Drachenschwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[13152] = { id = 13152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch beim Doktor", description = "Sie haben diese Ghule also unten im Sanktum der Reanimation mit zerbrochenen Saronitsplittern ausgestattet? Wir müssen dem ein Ende setzen, bevor sie diese Ghule gegen unsere Truppen einsetzen.\n\nFindet den Eingang zum Sanktum der Reanimation im Gebiet um das Fleischriesenlabor in den Fleischwerken. Dort hält das Ghulgenie Doktor Sabnok seine schaurigste Schöpfung 'Flicken' fest. Befreit Flicken von seinen Ketten und helft ihm, sich am Doktor zu rächen. Möge seine eigene Kreatur sein Untergang sein.", sourceObjective = "Dunkelreiterin Arly von der Schwarzwacht möchte, dass Ihr den Metallpflock, an den 'Flicken' im Sanktum der Reanimation gekettet ist, zerstört und diesem helft, sich an Doktor Sabnok zu rächen.", progress = "Habt Ihr die Schöpfung des Doktors schon freigelassen?", completion = "<Dunkelreiterin Arly wirft den Kopf in den Nacken und lacht finster.>\n\nEin passendes Ende für den 'guten' Doktor, findet Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[13153] = { id = 13153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krieger schützen", description = "{name}, gut, Euch zu sehen. Wir müssen uns beeilen, solange sich die Schlacht etwas gelegt hat, und unsere Vorräte aufstocken. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Man hat beobachtet, wie die Horde in dieser Gegend Rüstungen einsammelt.\n\nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.\n\nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.", sourceObjective = "Zauberin Kaylana in der Tausendwinterfestung möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen abnehmt.", progress = "Habt Ihr die Rüstungen nun gefunden?", completion = "Oh, die tropfen noch immer. Hättet Ihr sie nicht zuerst abtrocknen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[13154] = { id = 13154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.\n\nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.\n\nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!\n\nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!", sourceObjective = "Bogenmacher Randolph in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Wie ist die Jagd gelaufen? Ich habe Gerüchte darüber gehört, dass es an dem Ort spuken soll. Ich gehe jedoch nie selbst dorthin.", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13155] = { id = 13155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereth der Gewiefte", description = "Ich habe schon Gerüchte über Malykriss und Arthas' neuen Todesritterorden gehört, bin jedoch davon ausgegangen, dass es sich dabei nur um etwas handelt, das dazu dienen soll, die Lücke wieder aufzufüllen. Ihre Zahl lässt jedoch darauf schließen, dass er versucht, einen Zahn zuzulegen.\n\nWir haben vor nicht allzu langer Zeit einen unserer Besten nach Malykriss entsandt - Vereth den Gewieften. Ihr solltet ihn auf der Anhöhe des Leidens gleich westlich von Malykriss im Hof der Knochen antreffen.\n\nVersucht, auf Eurem Weg dorthin nicht zu viel Aufmerksamkeit auf Euch zu ziehen.", sourceObjective = "Meldet Euch bei Vereth dem Gewieften auf der Anhöhe des Leidens in Eiskrone.", completion = "Die unheilvolle Festung... ein Zeugnis dessen, wie ungern Arthas verliert. Lasst uns die Klinge tief hineintreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13156] = { id = 13156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltenes Kraut", description = "Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.\n\nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn der Kräuterbeutel der Horde, die Ihr dort finden könnt. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.\n\nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen die Kräuter ab!", sourceObjective = "Anachoret Tessa in der Tausendwinterfestung möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel der Horde abnehmt.", progress = "Hoffe, Ihr habt aus Versehen keine dieser Peitscher herausgezogen! Die haben den Gefreiten Doane letzte Woche ziemlich übel verpeitscht.", completion = "Ausgezeichnet! Das wird helfen, unsere Truppen vor der Kälte zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13157] = { id = 13157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreuzfahrerturm", description = "Ihr könnt stolz darauf sein, dass Ihr es wart, der der Argentumdämmerung dazu verholfen hat, in Eiskrone Fuß zu fassen, {name}. Der Kreuzfahrerturm bietet dem Lichkönig und seinen missratenen Günstlingen nun direkt die Stirn.\n\nHochlord Fordring und die Kreuzfahrer, die überlebt haben, erwarten Eure Ankunft beim Kreuzfahrerturm. Durchquert erneut die Bresche und sucht den Hochlord auf!", sourceObjective = "Sucht den Hochlord Tirion Fordring beim Kreuzfahrerturm in Eiskrone auf.", completion = "Der Weg zu den Toren der Eiskronenzitadelle wird lang und beschwerlich. Ich und die Soldaten der Argentumdämmerung möchten Euch für alles danken, was Ihr bisher getan habt. Es beruhigt uns, zu wissen, dass Ihr an diesem verfluchten Ort an unserer Seite kämpfen werdet.\n\n<Hochlord Tirion Fordring salutiert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13158] = { id = 13158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretion ist der Schlüssel", description = "Hört mir zu, {race}.\n\nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans in die Wege leiten!\n\nIch möchte, dass Ihr Euch umgehend zum Gefängnis aufmacht und mit Aufseher Alturas sprecht. Er wird Euch die Einzelheiten erklären.\n\nDas ist nicht alles: Die Sache muss mit äußerster Diskretion behandelt werden. Wir müssen versuchen, die Einwohner Dalarans wenn möglich nicht zu beunruhigen. Habe ich mich klar ausgedrückt?\n\nSehr gut. Nun geht!", sourceObjective = "Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Aufseher Alturas sprecht.", completion = "Keinen Augenblick zu früh.\n\nSeid Ihr bereit, Dalaran zu verteidigen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13159] = { id = 13159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung", description = "Hier ist der Gefängnisschlüssel.\n\nMeine Männer und ich werden als letzte Verteidigungslinie hier bleiben, falls Ihr dem Angriff nicht standhalten könnt.\n\nSprecht auf jeden Fall mit Leutnant Sinclari. Sie wird Euch Zugang zu den Verteidigungsvorrichtungen des Gefängnisses beschaffen.\n\nBeeilt Euch, {race}. Es bleibt nur wenig Zeit. Die Wenigen, die ich zurückgelassen habe, werden ohne Eure Hilfe nicht lange durchhalten. Meldet Euch wieder bei mir, sobald die Invasoren erfolgreich zurückgeschlagen wurden.", sourceObjective = "Aufseher Alturas möchte, dass Ihr die Violette Festung betretet und den Invasionsstreitkräften des blauen Drachenschwarms ein Ende bereitet. Ihr sollt Euch wieder bei ihm melden, sobald Cyanigosa getötet wurde.", progress = "Ist es vorbei? Konntet Ihr dem Angriff standhalten?", completion = "Die Krise ist also abgewendet?\n\nDas sind wirklich gute Neuigkeiten. Ich werde sie an Rhonin weiterleiten.\n\nBitte, nehmt dies als Zeichen des Danks, den Euch Dalaran entgegenbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13160] = { id = 13160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine überwältigende Aussicht", description = "Gargoyles eignen sich sehr gut als Kundschafter und können tödlich sein, wenn man ihnen den Angriff aus der Luft überlässt, doch haben sie einen offensichtlichen Schwachpunkt. Die meisten von ihnen müssen längere Zeit in Steinform verbringen, um sich zu erholen und die Energie zu sammeln, die sie brauchen, um ihre schweren Körper durch die Luft zu bewegen.\n\nAls ich durch das von Euch benutzte Auge geblickt habe, sind mir Dutzende von Eishautwachposten aufgefallen, die an den östlichen und südlichen Innenwänden ruhten. Benutzt den Jäger, um zu ihnen hinauf zu gelangen und vernichtet sie, während sie schlafen.", sourceObjective = "Vereth der Gewiefte möchte, dass Ihr die Hebefähigkeiten des geschmeidigen Pirschers benutzt, um 12 schlafende Eishautwachposten zu zerstören.", completion = "Die stellen keine so große Bedrohung mehr da, wenn sie schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13161] = { id = 13161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reiter des Unheiligen", description = "Es ist Zeit, dass wir damit anfangen, den Kopf des Ganzen zu beseitigen.\n\nIch diente ziemlich lange neben Rokir. Er kennt die unheiligen Künste besser als jeder andere Todesritter, den ich getroffen habe, und er ist genau so skrupellos. Nehmt es nicht zu leicht.\n\nRokirs Stärken treten dann am stärksten hervor, wenn er sich auf seinem eigenen Grund und Boden befindet. Leider haben wir in dieser Hinsicht keine andere Wahl. Bleibt jedoch auf den Beinen, um seinen untoten Dienern aus dem Weg zu gehen, und Ihr solltet siegreich hervorgehen.\n\nSeid flink, {class}, und nehmt die Sache nicht zu leicht.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Rokir, den Reiter des Unheiligen, tötet.", completion = "Die Welt wird ohne Rokir ein viel besserer Ort sein - glaubt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13162] = { id = 13162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reiterin des Frostes", description = "Saph... So einen Todesritter wie sie gibt es kein zweites Mal. Sie wird Euch mit sanften Worten übergießen und während Ihr Euch absolut sicher seid, dass kein Funken Boshaftigkeit in ihr steckt, wird sie Euch durchlöchern - weiterhin ein Lächeln auf den Lippen. Unterschätzt sie nicht.\n\nIch mache mir keine Sorgen, dass Ihr Saph besiegen könnt, doch werdet bloß nicht zu übermütig. Ihre Stärke liegt darin, ihre Opfer in falscher Zuversicht zu wiegen und sie kurz darauf mit einem heftigen Frosthagel in tausend Einzelteile zu zerschießen.\n\nSeid immer auf der Hut und unterschätzt sie nicht.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Saph, die Reiterin des Frostes tötet.", completion = "Ich muss gestehen, dass ich ihr Lachen vermisse... und dieses Lächeln, das langsam in ihr Gesicht schlich, bevor sie jemanden tötete. Muss jetzt jedoch weniger auf der Hut sein, also nehme ich an, dass ich mich nicht beschweren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13163] = { id = 13163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reiter des Blutes", description = "Baelok ist einer der wenigen Vrykul, den ich jemals in den Rängen aufsteigen sah, und das war größtenteils seiner schieren Brutalität zu verdanken. Wenn die Konkurrenz erst einmal tot ist, gibt es um einiges weniger, mit dem man konkurrieren müsste.\n\nEure Gruppe muss sich verteilen und so viel Abstand voneinander halten wie Ihr es die Situation zulässt, wenn der Kampf beginnt. Er wird nicht zögern, Eure Lebensenergie zu rauben, also werdet Ihr ihn so oft wie möglich daran hindern müssen.\n\nIch vertraue auf Euch. Seht zu, dass er stirbt.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr Baelok, den Reiter des Blutes, tötet.", completion = "Er hat also endlich den Kürzeren gezogen? Gut zu hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13164] = { id = 13164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutbanns Schicksal", description = "Nun, da die Reiter der Heerschar des Leids tot sind, ist die Zeit gekommen, ihrem wahren Anführer ein Ende zu bereiten: Orbaz Blutbann.\n\nMograine war hier, als Ihr weg wart, und hat mir gesagt, dass er herausgefunden hat, wo sich Orbaz versteckt hält. Unter der Eiskronenzitadelle befindet sich eine riesige Grube - und Orbaz befindet sich am Rand dieser Grube.\n\nEinige der stärksten Agenten der Schwarzen Klinge wurden schon ausgesandt - holt also Hilfe und auf mit Euch in den Kampf. Es ist Zeit, dass Blutbann stirbt.", sourceObjective = "Vereth auf der Anhöhe des Leidens hat Euch ausgesandt, um Orbaz Blutbann zu töten.", progress = "Sind wir diesen jämmerlichen Möchtegernarthas los?", completion = "Also ist Mograine höchstpersönlich erschienen, um die Sache zu Ende zu bringen? Ich kann mir vorstellen, dass es böses Blut zwischen den beiden gegeben haben muss - kein Wunder also, dass er ein Stück vom Kuchen abbekommen wollte.\n\nIhr habt außerordentlich gute Arbeit geleistet, {race}, und sollt dementsprechend belohnt werden. Die Schwarze Klinge spricht Euch ihren Dank aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13165] = { id = 13165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acherus zurückerobern", description = "Der Dunstschleier hat sich gelüftet. Nun kann ich genau so klar sehen, wie an dem Tag, als ich den Aschenbringer in mein eigenes Herz rammte, um meines Vaters verfluchte Seele zu befreien - dies ist meine letzte Erinnerung an mein Leben als freier Mann.\n\nWir müssen Acherus von der Geißel zurückerobern, wenn unser Orden in dieser neuen Welt überleben will. Ich habe Euch gezeigt, wie man ein schwarzes Tor beschwören kann. Das Tor wird Euch zurück nach Acherus befördern, wenn Ihr es ruft, {name}. Ruft es herbei und trefft mich dort. Die erste Schlacht der Ritter der Schwarzen Klinge ist in vollem Gange!", sourceObjective = "Benutzt Euren Zauber 'Schwarzes Tor' und kehrt nach Acherus, der Schwarzen Festung, zurück. Meldet Euch bei Hochlord Darion Mograine, sobald Ihr dort seid.", completion = "Der Lichkönig ist nach Nordend zurückgekehrt, verwundet vom Aschenbringer, doch auf der zweiten Ebene befindet sich noch immer die letzte seiner Armeen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13166] = { id = 13166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Schwarze Festung", description = "Die Hallen des Befehls wurden gesichert, doch der Lichkönig hat uns ein kleines Geschenk im Herzen von Acherus zurückgelassen. Der zusammengenähte Schrecken Flickwerk und eine Horde von Monstrositäten haben die zweite Ebene in ihre Kontrolle gebracht.\n\nBenutzt den Teleporter, um auf die zweite Ebene zu gelangen, und zerstört die restlichen Streitkräfte der Geißel. Greift Flickwerk auf keinen Fall alleine an! Ihr müsst das Ungetüm mit anderen Todesrittern von Acherus bekämpfen!\n\nGeht, {name}. Meine Kraft wird Euch tragen!", sourceObjective = "Vernichtet 10 Diener der Geißel und helft, Flickwerk zu vernichten. Kehrt zu Hochlord Darion Mograine zurück, solltet Ihr erfolgreich sein.", progress = "Acherus wird unser sein!", completion = "Gut gemacht, {class}. Um die verbliebenen Diener der Geißel wird man sich im Nu gekümmert haben und der Wiederaufbau kann von Neuem beginnen.\n\nIch habe eine allerletzte Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13167] = { id = 13167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Verräterkönig", description = "Anub'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.\n\nNach seinem Verrat hat er unser Heimatland entstellt und verdorben und es schließlich zu dem erbärmlichen Haufen Dreck gemacht, zu dem es heute geworden ist. Er herrscht über eine Armee untoter Neruber, die wie ihr Anführer dem Lichkönig die Treue geschworen haben.\n\nSetzt der Herrschaft des Verräterkönigs ein Ende, {class}. damit würdet Ihr unseren beiden Völkern einen großen Dienst erweisen.\n\nBringt mir Anub'araks Panzer, wenn Ihr schaffen solltet, was noch keiner vor Euch geschafft hat.", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun hat Euch damit beauftragt, Anub'arak in Azjol-Nerub zu besiegen. Danach sollt Ihr Kilix Anub'araks zerbrochenen Panzer zurückbringen.", progress = "Ist es vollbracht, {class}? Hat der Verräterkönig letztendlich sein Ende gefunden?", completion = "<Kilix starrt den Panzer an und jedes einzelne seiner Augen fängt an, intensiv zu leuchten.>\n\nEs ist VOLLBRACHT!\n\n{race}! Euer Name soll in die Geschichte meines Volkes eingehen.\n\nIch stehe in Eurer Schuld...", sourceObjectiveStatus = "unverified-source-field" }
quests[13168] = { id = 13168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschiedsgeschenke", description = "Schaut, was wir hier haben... Augen der Herrschaft. Normalerweise tut der Kult alles nur Erdenkliche, um diese Dinger geheim zu halten, aber vermutlich haben sie ziemlich wenig Rückzugsmöglichkeiten, wenn wir sie in ihrem eigenen Haus erschlagen.\n\nDie Augen erlauben es jedem Wesen von relativer Macht, die Handlungen eines untoten Dieners präzise zu kontrollieren. Wie Ihr Euch vorstellen könnt, kann dies im Falle des typischen unbeholfenen Ghuls oder Skeletts extrem praktisch sein.\n\nHabt Ihr Lust, es einmal auszuprobieren? Benutzt eines der Augen bei einem der gefangenen Schatten.", sourceObjective = "Keritose Blutklinge im Schattengewölbe möchte, dass Ihr eins der Augen der Herrschaft benutzt, um die Kontrolle über einen gefangenen Eidolonwächter zu übernehmen.", progress = "Die Tricks, die durch diese Augen möglich werden, sind offenkundig. Dies werden sehr nützliche Werkzeuge sein.", completion = "Gar nicht schwer, hm? Jedes halbwegs intelligente Wesen sollte wenig Schwierigkeiten haben, niedere Untote zu kontrollieren. Ich schätze, nur ein echter Totenbeschwörer kann diese benutzen, um die Kontrolle über eines der mächtigeren untoten Geschöpfe zu ergreifen. Das dürfte allerdings kein Problem sein. Mir fallen bereits diverse Varianten der Zerstörung ein, die wir mithilfe der erbärmlichsten Diener ausführen können.\n\nSollen wir es einmal ausprobieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[13169] = { id = 13169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Freund des Untoten", description = "Unter den Untoten in der Saronitmine gen Süden ist es üblich, ihre Seuchenhunde hungern zu lassen, um sie besonders aggressiv zu halten. Benutzt den Schemen, um nahe heranzukommen und füttert einige der Hunde. Ich verspreche Euch, Ihr werdet fortan keinerlei Schwierigkeiten mehr mit ihnen haben. Vielleicht werden sie sich ihrem Wohltäter sogar anschließen.\n\nKommt den Dingern jedoch nicht zu nahe, bevor Ihr sie gefüttert habt. Ihre Nasen lassen sich von Eurem Schemen nicht so leicht hinters Licht führen.", sourceObjective = "Keritose Blutklinge im Schattengewölbe wünscht, dass Ihr mithilfe des Eidolonwächters 18 hungernde Seuchenhunde füttert.", completion = "Sie sind sofort eingeschlafen, stimmts?", sourceObjectiveStatus = "unverified-source-field" }
quests[13170] = { id = 13170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre ist was für Schwächlinge", description = "Ghule sind sehr zerbrechlich, wenn es hart auf hart kommt, und die Aufklärer in der Saronitmine den Weg hinunter in Richtung Südwesten sind da keine Ausnahme. Mithilfe eines Schattens sollte es Euch eigentlich nicht schwerfallen, ranzuschleichen und ihre Aufklärer geräuschlos auszuschalten.\n\nBeseitigt so viele Aufklärer, wie Ihr in angemessener Zeit erwischen könnt... Ihre Reihen sollen gelichtet werden, bevor wir das nächste Mal angreifen.", sourceObjective = "Keritose Blutklinge im Schattengewölbe hätte gerne, dass Ihr 20 ruhelose Aufklärer tötet.", completion = "Ohne Euch auch nur die Hände schmutzig gemacht zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13171] = { id = 13171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schickt sie zurück", description = "Meine Hauptsorge ist die Saronitmine, die sich den Weg hinunter in Richtung Südwesten befindet. Sie holen unglaubliche Mengen an Erz aus dieser Mine und ich würde schon gerne wissen, was sie damit vorhaben. Um das herauszufinden, fangen wir damit an, ihre Verteidigung zu schwächen.\n\nMir sind mehrere Kristalle aufgefallen, die in der ganzen Basis verteilt stehen, und nehme an, dass es sich hier um irgendwelche Verteidigungsanlagen handelt, ähnlich den Ziggurats. Zerstört mithilfe des Eidolonwächters jeden Kristall, den Ihr finden könnt.", sourceObjective = "Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 10 Eindämmungskristalle der Geißel zu bannen.", completion = "Ausgezeichnete Arbeit. In der Luft sollte also so gut wie keine Gefahr mehr lauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13172] = { id = 13172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos säen", description = "Effektives Werkzeug, nicht wahr? Sehr gut gemacht, wie Ihr ihre Verteidigung geschwächt habt, {class}. Nun können wir den Hauptangriff vorantreiben.\n\nDer Plan ist einfach und direkt - wir wollen alles beseitigen, was sich bewegt, und die Verwirrung ausnutzen, um ein paar Informationen in die Hände zu bekommen.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde Euch einen Skelettgreif besorgen.", sourceObjective = "Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 80 Untote im Tränenbruch abzuschlachten. Sprecht mit ihm, um Euch einen Skelettgreifen für den Angriff zu sichern.", completion = "Sie sind so gut wie schutzlos ausgeliefert. Viel einfacher geht's wohl nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13173] = { id = 13173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Durcheinander nutzen", description = "Uns ist es gelungen, eine ganze Reihe von Arbeitern in die Finger zu bekommen. Sie sollten sich gut eignen.\n\nIch möchte, dass Ihr eins der Augen benutzt, um einen Arbeiter in die Mine zu schicken. Wenn das ganze Lager in Aufruhr ist, sollte es ihnen unmöglich sein, Euch von einem der anderen Arbeiter zu unterscheiden, die nach dem Angriff umherlaufen.\n\nFindet denjenigen, der für die ganze Operation zuständig ist und macht Euch an die Arbeit. Mit etwas Glück werden wir recht schnell herausfinden, wohin das Saronit verschickt wird. Ich werde Euch durch das Auge hindurch beobachten." }
quests[13174] = { id = 13174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Durcheinander nutzen", description = "Den Betrieb zum Stillstand zu bringen ist nur die eine Hälfte des Plans. Das andere wichtige Ziel an dieser Stelle ist es, herauszufinden, wohin all das Saronit geschickt wird. Uns sind ein paar Orte bekannt, an denen es wieder auftaucht, doch bei der Menge, die sie aus dem Boden holen, liegt die Vermutung nahe, dass da ein viel größeres Projekt läuft.\n\nSeid Ihr einmal in der Mine, so nehmt alle Dokumente mit, die Ihr finden könnt. Solltet Ihr den Ort mit einem der Greifen angreifen, so könnt Ihr Euch fallen lassen, sobald Ihr die Arbeit erledigt habt.", sourceObjective = "Keritose Blutklinge im Schattengewölbe verlangt ein Dokument des Tränenbruchs, ein Geschäftsbuch des Tränenbruchs, eine Karte des Tränenbruchs und einen Zeitplan des Tränenbruchs.", progress = "Habt Ihr das, was ich wollte?", completion = "Dann lasst uns mal sehen... Was haben wir denn hier...\n\n<Keritose durchforstet die Papiere und scheint wenig zu finden, was er nicht schon vorher wusste - als er plötzlich auf das stößt, wonach er suchte...>\n\nMalykriss! Die unheilvolle Festung. Es scheint, als hätte der Verlust seiner Todesritter Arthas nicht allzu glücklich gemacht... Ich bin mir nicht sicher, was er mit dem ganzen Saronit anfängt, doch er scheint in übertriebenem Maße etwas ausgleichen zu wollen.\n\nDer Junge ist nicht daran gewöhnt, zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13175] = { id = 13175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kontrolle zurückgewinnen" }
quests[13176] = { id = 13176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lieferung vorbereiten" }
quests[13177] = { id = 13177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade für die Gnadenlosen", description = "Willkommen in der Tausendwinterfestung, {name}. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!", sourceObjective = "Hauptmann Zanneth in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Horde tötet.", completion = "Wie ruhmreich! Wahrlich, Ihr gehört zu den Champions der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13178] = { id = 13178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Willkommen in der Tausendwinterfestung, {name}. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!\n\nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.", sourceObjective = "Kommandant Dardosh in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Allianz tötet.", completion = "Lok'tar! Sieg für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13179] = { id = 13179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade für die Gnadenlosen", description = "Willkommen in Tausendwinter, {name}. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!", sourceObjective = "Hauptmann Zanneth in Tausendwinter möchte, dass Ihr 10 Mitglieder der Horde tötet.", completion = "Wie ruhmreich! Wahrlich, Ihr gehört zu den Champions der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13180] = { id = 13180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Willkommen in Tausendwinter, {name}. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!\n\nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.", sourceObjective = "Kommandant Dardosh in Tausendwinter möchte, dass Ihr 10 Mitglieder der Allianz tötet.", completion = "Lok'tar! Sieg für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13181] = { id = 13181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tausendwinter", description = "Hauptmann Zanneth mag vielleicht zufrieden damit sein, einen Haufen Hordeleichen vor sich liegen zu haben, doch die Kontrolle über die Tausendwinterfestung zu erlangen, ist für die Expedition Valianz von äußerster Wichtigkeit. Kümmert Euch darum, dass sie weiterhin in unseren Händen bleibt.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", sourceObjective = "Gewinnt einen Kampf auf dem Schlachtfeld in Tausendwinter und kehrt dann zu Taktikoffizier Ahbramis zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.", completion = "Genau das, was ich hören wollte! Ein Sieg auf dem Tausendwintersee - selbst ein vorübergehender - ist ein äußerst wichtiger Bestandteil unserer Gesamtstrategie gegen die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13182] = { id = 13182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst die Eier nicht!", description = "In ganz Azjol-Nerub liegen Eier verteilt, die von den Nerubern der Geißel gehegt und gepflegt werden und schon bald schlüpfen werden. Sie werden ihre Zahl noch zusätzlich mehren.\n\nEs würde nicht viel nützen, wenn alle Untoten aus den Höhlen getilgt und diese faulen Eier ausschlüpfen würden, nur damit sie an ihre Stelle treten.\n\nKümmert Euch auf jeden Fall darum, dass unsere uralte Heimat von allen Eiern der Geißel gereinigt wird, während Ihr den Ort erkundet, der einst Azjol-Nerub gewesen ist.", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr Azjol-Nerub betretet und 6 Eier der Geißelneruber zerstört.", completion = "Es macht mich traurig zu sehen, dass es dazu gekommen ist. Wenn wir unser Reich nur wieder zu dem machen könnten, was es einst war...", sourceObjectiveStatus = "unverified-source-field" }
quests[13183] = { id = 13183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tausendwinter", description = "Dardosh mag es zwar genügen, unsere Feinde zu töten, doch es ist von äußerster Wichtigkeit, dass wir die Tausendwinterfestung kontrollieren. Tut, was auch immer nötig ist, damit Tausendwinter uns gehört.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", sourceObjective = "Gewinnt einen Kampf in einem Schlachtfeld von Tausendwinter und kehrt anschließend zu Taktikoffizier Kilrath in Tausendwinter zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.", completion = "Ihr habt heute wahrlich etwas Großartiges fertiggebracht. Euer Opfer wird geschätzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13184] = { id = 13184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nützlichkeit überdauern" }
quests[13185] = { id = 13185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt der Belagerung ein Ende", description = "Ich sie gehört! Die Allianz bald kommen. Mach drei Belagerungsmaschinen kaputt und komm dann wieder zu Murp.", sourceObjective = "Leutnant Murp in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Allianz zerstört.", progress = "Hast du ihre Belagerungsmaschinen kaputt gemacht?", completion = "Gute Arbeit. Murp wäre gern dabei gewesen, um zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13186] = { id = 13186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt der Belagerung ein Ende", description = "Es ist nur eine Frage der Zeit, bis diese Burg von den Streitkräften der Horde belagert wird. Zerstört drei ihrer Belagerungsmaschinen und kehrt anschließend zu mir zurück.", sourceObjective = "Chefdemolierer Legoso in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Horde zerstört.", completion = "Ausgezeichnet. Das sollte ihren Angriff verlangsamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13187] = { id = 13187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gesichtslosen", description = "Jedes Mal, wenn mein Volk im Kampf gegen die Streitkräfte der Untoten an Boden verlor, grub es tiefer.\n\nVersehentlich legten sie Diener der alten Götter frei, Wesen, die nur als die Gesichtslosen bekannt sind.\n\nAm Ende konnten wir nicht an zwei Fronten kämpfen.\n\nMit Eurer Hilfe werden die Gesichtslosen hoffentlich endlich fallen.", sourceObjective = "Seher Ixit möchte, dass Ihr Herold Volazj und die drei Vergessenen an seiner Seite tötet.", completion = "Gut gemacht, {class}.\n\nMögen Eure Heldentaten die Hoffnung unseres Volkes neu entfachen, auf dass wir eines Tages die Stadt unserer Vorfahren zurückerobern werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13188] = { id = 13188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren der Könige", description = "Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, {name}, doch wisset: Einst wart Ihr ein Held der Allianz.\n\n<Darion starrt Euch an.>\n\nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Allianz zeigen.\n\nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Sturmwind. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn König Varian Wrynn bringen. Benutzt das Portal.", sourceObjective = "Bringt den Brief zu König Varian Wrynn, Anhänger der Allianz in Burg Sturmwind in Sturmwind.", progress = "Ihr habt nur noch Sekunden zu leben.", completion = "<Varian starrt in die Ferne.>\n\nIn der Tat, alter Freund... Blut und Ruhm.\n\n<Varian richtet seinen Blick auf Euch.>\n\nWäre dieser Brief von Tirion nicht, wärt Ihr nichts weiter als ein Fleck auf meinem Boden. Nur die Empfehlung eines der größten Paladine, der jemals gelebt hat, hätte Euer Überleben sichern können.\n\nWir... Wir werden zusammen gegen die Geißel kämpfen - gegen den Lichkönig!\n\nEHRE DER ALLIANZ!", sourceObjectiveStatus = "unverified-source-field" }
quests[13189] = { id = 13189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Kriegshäuptlings", description = "Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, {name}, doch wisset: Einst wart Ihr ein Held der Horde.\n\n<Darion starrt Euch an.>\n\nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Horde zeigen.\n\nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Orgrimmar. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn dem Kriegshäuptling überbringen. Benutzt das Portal.", sourceObjective = "Bringt den Brief zum Kriegshäuptling der Horde in Orgrimmar.", progress = "Eine interessante Wende der Ereignisse.", completion = "Es ist diesem Paladin zu verdanken, dass Etrigg am Leben ist. Hätte Lord Fordring ihn nicht aus Stratholme befreit, wäre er hingerichtet worden.\n\nDass Tirion Fordring alles geopfert hat, um das Leben eines Orcs zu retten... Ich kenne nur einen Menschen, der solch ein Opfer gebracht hat.\n\n<Thrall hält eine Träne zurück.>\n\nDu wirst immer in meinem Herzen bleiben, Taretha.\n\nJa. Für Tirion Fordring und Etrigg! Wir werden Euch als Mitglied der Horde akzeptieren und Euren Orden als Verbündete betrachten.\n\nBlut und Donner! Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13190] = { id = 13190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles zu seiner Zeit", description = "Ahn'kahet, woher wir einst kamen...\n\nIch träume davon, dass wir eines Tages Tod und Dunkelheit, in deren Griff sich unsere uralte Heimat befindet, überwinden werden. Zu diesem Zweck habe ich einen Plan entworfen, mit dem wir unsere Feinde entmutigen können.\n\nIhre kostbaren Wächter müssen brennen!\n\nLegt ihre Leichen auf die Kohlenpfanne tief im Inneren der Stadt. Der Geruch ihrer verbrannten Überreste wird in der Luft hängen und unseren Feind an seine Schwäche erinnern.\n\nGeht mit Bedacht vor, {class}! Ihre untoten Leichen sind äußerst zerbrechlich und werden rasch verrotten.", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr die Leiche eines Wächters der Ahn'kahar beschafft und sie auf das Kohlenbecken von Ahn'kahet in Ahn'kahet legt.\n\nDiese Quest kann nur auf dem Schwierigkeitsgrad 'Heroisch' beendet werden.", progress = "Konntet Ihr die Leiche eines Wächters verbrennen, {race}?", completion = "Aha!\n\nMöge der spöttische Geruch des Versagens an ihren leeren Seelen nagen!\n\nIch danke Euch, {class}. Ihr habt den Untoten an diesem heutigen Tage einen Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13191] = { id = 13191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "Lok'tar, {name}! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die Feuerelementare in der Gegend zu bekämpfen, bis Ihr welche findet!", sourceObjective = "Belagerungsschmied Starkhuf in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.", progress = "Nun? Konntet Ihr die Glutstücke finden? oder hat die Allianz alles gestohlen und Euch weinend zurückgelassen?", completion = "Ausgezeichnet! Das wird uns dabei helfen, die Allianz in den kommenden Schlachten zu besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13192] = { id = 13192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wälle schützen", description = "Hey, Mann. Bei dem Ort hier krieg ich 'ne Gänsehaut, weißt du?\n\nHier spuken viel zu viele Geister rum. Ich will Hoodoobarrieren aufstellen, brauch aber 'n paar Seelen dafür, Mann. Aber nich' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.\n\nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man 'ne Seele heraussaugen kann. Bring die Allianzler dort um - vielleicht haben sie das Zeug, das wir brauchen.\n\nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin', dann haben die Elementare vielleicht welche, Mann.", sourceObjective = "Hoodoomeister Fu'jin in der Tausendwinterfestung möchte, dass Ihr 10 verzauberte Brustplatten der Allianz aus dem Gebiet der Eiswasserfälle beschafft.", progress = "Hast du die Rüstungen mit dabei, Mann?", completion = "Ooh, ja, das is' das Zeug, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[13193] = { id = 13193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. {name}, ich brauche Drachenknochen für unsere Pfeilspitzen.\n\nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.\n\nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern in der Gegend bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie ihre sterbenden Opfer liebend gerne auf den Knochen aufspießen.", sourceObjective = "Leutnant Vieron Flammenfeder in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Schon so früh zurück? Verflixt, hatte gehofft, mich einen Moment lang ausruhen zu können.", completion = "Tja, ich nehme an, das heißt für mich: noch eine Nacht Knochen schärfen. Wieso bin ich nicht wie mein Bruder in Silbermond geblieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[13194] = { id = 13194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Rosen heilen", description = "Zwischen den Schlachten mag einer schon fast daran glauben, dass es Hoffnung auf Frieden in diesem Land gäbe. Leider hat unser Schicksal anderes mit uns vor.\n\nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.\n\nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen ihre Kräuterbeutel ab.\n\nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.", sourceObjective = "Primalist Mulfort möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.", progress = "Habt Ihr die Kräuter dabei? Die Verwundeten und Kranken werden von Stunde zu Stunde mehr.", completion = "Ich danke Euch, das wird uns eine große Hilfe bei der Behandlung unserer verwundeten Soldaten sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13195] = { id = 13195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltenes Kraut", description = "Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.\n\nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn Kräuterbeutel der Horde. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.\n\nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen ihre Kräuter ab!\n\nDie Peitscher in der Gegend können auch welche bei sich haben.", sourceObjective = "Anachoret Tessa in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13196] = { id = 13196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.\n\nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.\n\nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!\n\nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!", sourceObjective = "Bogenmacher Randolph in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Wie ist die Jagd gelaufen? Ich habe Gerüchte darüber gehört, dass es an dem Ort spuken soll. Ich gehe jedoch nie selbst dorthin.", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13197] = { id = 13197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "{name}! Wurde auch langsam Zeit, dass Ihr auftaucht. Wir mögen zwar die letzte Schlacht verloren haben, doch wir sollten uns noch immer auf die nächste vorbereiten! Reist zum Flammenkessel im südöstlichen Teil von Tausendwinter und beschafft mehrere Stück Immerglut.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nOh, eins noch: Falls Ihr zufällig Anhänger der Horde im Flammenkessel sehen solltet, dann zögert nicht, tötet sie und nehmt ihnen die Glutstücke weg. Wir müssen verhindern, dass die Festung in ihrer Kontrolle bleibt!", sourceObjective = "Belagerungsschmied Starkhand in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt.", progress = "Nun? Konntet Ihr die Glutstücke finden? Oder ist Euch die Horde zuvorgekommen und hat Euch weinend zurückgelassen?", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13198] = { id = 13198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krieger schützen", description = "{name}, gut, Euch zu sehen. Wir müssen uns auf unseren nächsten Angriff auf die Festung vorbereiten. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Die Horde war damit beschäftigt, in dieser Gegend Rüstungen einzusammeln.\n\nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.\n\nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.", sourceObjective = "Zauberin Kaylana in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen der Horde abnehmt.", progress = "Habt Ihr die Rüstungen nun gefunden?", completion = "Oh, die tropfen noch immer. Hättet Ihr sie nicht zuerst trocknen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[13199] = { id = 13199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. {name}, ich brauche Drachenknochen für unsere Pfeilspitzen.\n\nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.\n\nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern dort bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie liebend gerne ihre sterbenden Opfer auf den Knochen aufspießen.", sourceObjective = "Leutnant Vieron Flammenfeder in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Schon so früh zurück? Verflixt, hatte gehofft, mich einen Moment lang ausruhen zu können.", completion = "Tja, ich nehme an, das heißt für mich: noch eine Nacht Knochen schärfen. Wieso bin ich nicht wie mein Bruder in Silbermond geblieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[13200] = { id = 13200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "Lok'tar, {name}! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die dortigen Feuerelementare zu bekämpfen, bis Ihr welche findet!", sourceObjective = "Belagerungsschmied Starkhuf in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13201] = { id = 13201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Rosen heilen", description = "So viele unserer Tapferen sind in der Schlacht gefallen, doch noch mehr werden sterben, wenn sie nicht behandelt werden.\n\nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.\n\nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen die Kräuterbeutel ab.\n\nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.", sourceObjective = "Primalist Mulfort in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13202] = { id = 13202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mauern verhexen", description = "Hey, Mann. Siehst du, wie die Allianzler sich's in ihrer Festung bequem machen?\n\nDenke, die sehen ein wenig zu bequem aus, findste nich'? Ich will den Ort verhexen, aber ich brauch dafür 'n paar Seelen, Mann. Aber nich' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.\n\nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man 'ne Seele heraussaugen kann. Bring die Allianzler dort um - die haben das Zeug, das wir brauchen.\n\nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin', dann haben die Elementare vielleicht welche, Mann.", sourceObjective = "Hoodoomeister Fu'jin in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und Allianzspielern dort 10 verzauberte Brustplatten der Allianz abnehmt.", progress = "Hast du die Rüstungen mit dabei, Mann?", completion = "Ooh, ja, das is' das Zeug, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[13203] = { id = 13203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[13204] = { id = 13204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgefahrene Pilze", description = "Ein unförmiges Stück pilzähnlichen Fungus fällt von einem besonders übel riechenden, schlammbedeckten Teil des Fleischs der Höhlenbestie. Als Ihr ihn näher betrachtet, werdet Ihr von dessen Gestank überwältigt und weicht angewidert zurück.\n\nIhr wundert Euch, ob die Neruber so etwas appetitlich finden. Ihr steckt den klebrigen Organismus in Eure Tasche und seid fest dazu entschlossen, es herauszufinden...", sourceObjective = "Ihr sollt 6 groteske Pilze von den wilden Höhlenbestien in Ahn'kahet sammeln und sie bei Kilix dem Entwirrer in der Grube von Narjun abliefern.", progress = "Was im Namen der Schöpfung ist das?!", completion = "Habt Ihr irgendeine Vorstellung davon, was Ihr da mit Euch herumgetragen habt, {class}?\n\nDie Höhlenbestien, von denen Ihr das habt, sondern ihren Abfall nicht auf die dahergebrachte Art und Weise ab. Ihr solltet Eure Hände waschen...\n\nDanke, dass Ihr an uns gedacht habt, doch falls Ihr noch mehr von diesen Dingern finden solltet, dann haltet Euch davon fern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13205] = { id = 13205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Glaubt mir, <Kamerad/Fräulein>, die Waffen der Vrykul sind durchweg gefährlich!\n\nIch habe ihre Schneiden am eigenen Leib erfahren und muss sagen, dass sie etwas Unnatürliches an sich haben. Sie sind täuschend gut ausbalanciert und unverschämt scharf - kurz gesagt einfach tödlich.\n\nGelangt in ihre Festung und krallt Euch zumindest einige dieser Waffen! Vielleicht können wir etwas von ihnen lernen, vielleicht auch nicht.\n\nIm Endeffekt ist es so: Je weniger Äxte sie herumschwingen, desto besser.", sourceObjective = "Verteidiger Mordun möchte, dass Ihr Burg Utgarde betretet und 5 Waffen der Vrykul stehlt.", progress = "Habt Ihr Euch ein paar dieser Vrykuläxte gekrallt?", completion = "<Mordun pfeift.>\n\nSeht Euch die nur mal an! Unglaublich.\n\nIch hatte eigentlich erwartet, dass diese Steinzeitmenschen mit Knüppeln herumfuchteln und Steine werfen.\n\nKein Glück...", sourceObjectiveStatus = "unverified-source-field" }
quests[13206] = { id = 13206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Wir müssen hinter das Geheimnis der Waffen dieser Barbaren kommen!\n\nWenn Ihr nur gesehen hättet, wie leicht sie meine Gefährten in Stücke schnitten, würdet Ihr verstehen, weshalb ich so dränge.\n\nSucht den Ort ab. Sammelt so viele ihrer Waffen, wie Ihr nur tragen könnt.", sourceObjective = "Dunkelläuferin Marrah möchte, dass Ihr 5 Waffen der Vrykul aus Burg Utgarde stehlt und sie ihr in Burg Utgarde bringt.", progress = "Konntet Ihr ihre Waffen stehlen?", completion = "Jede Waffe, die wir ihnen abnehmen, wird nicht im Fleisch eines Soldaten landen.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[13207] = { id = 13207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen des Steins", description = "Also ich bin überrascht, an einem Ort wie diesem andere Abenteurer anzutreffen.\n\nWenn meine Untersuchungen über diese Hallen stimmen, dann sind hier gewaltige Entdeckungen zu machen!\n\nIhr könnt gerne mitkommen, wenn ich mich darauf verlassen kann, dass Ihr mir Rückendeckung gebt.", sourceObjective = "Brann Bronzebart möchte, dass Ihr ihn bei der Suche nach den Geheimnissen, die in den Hallen des Steins verborgen liegen, begleitet.", progress = "Tja, nun, es hat sich letztlich als gut herausgestellt, dass wir uns begegnet sind.", completion = "Gibt immer mehr Fragen als Antworten, nicht wahr, Kamerad?", sourceObjectiveStatus = "unverified-source-field" }
quests[13211] = { id = 13211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer wird Euch läutern", description = "Die Geißel benutzt unsere eigenen Gefallenen gegen uns, indem sie sie als Ghule oder Skelette wiederauferstehen lässt oder ihre Körper zerlegt und die Einzelteile benutzt, um neue Monstrositäten herzustellen. Das muss aufhören!\n\nDie Toten sind Helden, die in Verteidigung allen Lebens fielen und ein solch grausiges Schicksal muss ihnen erspart bleiben. Darüber hinaus können wir es uns einfach nicht leisten, ihnen im Feld erneut gegenüberzustehen, als Waffen gegen uns eingesetzt. Nehmt diese Fackel mit Euch in die Fleischwerke und verbrennt alle Leichen, die Ihr im Sanktum der Reanimation oder im Monstrositätenlabor finden könnt.", sourceObjective = "Kreuzfahrer Olakin Sainrith bei der Schwarzwacht möchte, dass Ihr mithilfe Olakins Fackel 7 eitrige Leichen verbrennt.", completion = "<Kreuzfahrer Olakin Sainrith hört aufmerksam zu, während Ihr Bericht erstattet.>\n\nEs ist nicht das Begräbnis, das sie verdient hätten, aber es ist besser als nichts und besser für die, die noch leben. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13212] = { id = 13212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Brüche gegangen", description = "Die Entführung des Kreuzzüglers Olakin lässt die Streitkräfte des Argentumkreuzzugs beim letzten Sturm auf die Fleischwerke führerlos dastehen. Obwohl für mich ein Kreuzzügler aussieht wie der andere, sehen die Argentumsoldaten das anders.\n\nEs gefällt mir gar nicht, unsere Zeit mit einer Schnitzeljagd zu verschwenden, aber ich habe keine andere Wahl. Unser heldenhafter Kreuzzügler wurde vermutlich schon längst in seine Einzelteile zerlegt und seine Überreste beim Zusammenbau von Monstrositäten verwendet. Geht hinunter in die Fleischwerke, tötet die Schrecken, die unsere Truppen bekämpfen, und bringt Olakins Körperteile zurück.", sourceObjective = "Bergt Olakins Oberkörper, Olakins Beine, Olakins linken Arm und Olakins rechten Arm und bringt sie der Dunkelreiterin Arly in der Schwarzwacht.", progress = "Habt Ihr die, äh, Überreste von Kreuzfahrer Olakin?", completion = "Nun, ich denke, es ist gut, dass wir den Kreuzfahrer \"gerettet\" haben, obwohl ich bezweifle, dass es dies war, was seine Kameraden im Sinn hatten. Dann lasst uns mal sehen, was wir tun können, um ihn wieder auf die Beine zu bringen, damit wir diese Farce hinter uns bringen und unsere Mission hier vollenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13213] = { id = 13213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas", description = "Ich sehe und höre viele Dinge, {name}, und etwas sehr Wichtiges ist passiert, seitdem Ihr Oberthan Balgarde besiegt habt: Man will gegen Euch in Valhalas kämpfen!\n\nDie Kampfgrube befindet sich gen Norden. Geht jetzt, nehmt Eure Freunde mit, und sprecht mit Geirrvif der Val'kyr. Bei den Herausforderern, die sie gegen Euch in den Ring werfen wird, werdet Ihr sicherlich Unterstützung brauchen.\n\nViel Glück.", sourceObjective = "Sprecht mit Geirrvif in Valhalas.", completion = "Ihr habt unsere besten Kämpfer besiegt. Euer Name ist in aller Munde, {name}.\n\nWomöglich denkt Ihr, das mich das stört - doch das tut es nicht. Wenn sie Euch unterliegen, dann sind sie unwürdig und nichts weiter als niedere Vargul!\n\nDoch vielleicht kann ich Euch und Euren Freunden etwas anderes geben, mit dem Ihr Euch vergnügen könnt. Valhalas ist unter anderem ein Ort, in dem Kämpfe jeglicher Art mit verschiedenartigen Gegnern geboten werden.\n\nSprecht mich wieder an, wenn Eure Freunde und Ihr bereit seid weiterzumachen. Wir werden sehen, ob Ihr wahrhaftig würdig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13214] = { id = 13214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Gefallene Helden", description = "Wenn Ihr glaubt, soweit zu sein, dann habe ich genau den richtigen Kampf für Euch, um Euch Eure ersten Sporen zu verdienen.\n\nEine andere Gruppe von Außenseitern dachte, sie wären bereit, sich der Härte Valhalas zu stellen. Sie schwangen große Reden und fielen am Ende doch wie all die anderen vor ihnen.\n\nWenn Ihr Euch für so anders haltet - wenn Ihr glaubt, Ihr hättet die Fähigkeiten und die Erfahrung, hier gegen solch sagenumwobene Krieger anzutreten - dann nehmt die Herausforderung bitte an.", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, im Einzelkampf alle sechs gefallenen Helden zu besiegen: Eldreth, Geness Halbseele, Jhadras, Masud, Rith und Talla.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Frischfleisch.\n\n<Der Todesritter der Vrykul spuckt Euch vor die Füße.>\n\nIhr denkt alle, dass Ihr das Zeug dazu habt, hier zu kämpfen.\n\nIhr seid nichts angesichts der Macht der Vrykul und der Geißel!\n\nDoch immerhin habt Ihr es geschafft, sechs inkompetente Leichen zu besiegen - Ihr müsst also was können. Doch höchstwahrscheinlich nicht genug für das, was als nächstes kommen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13215] = { id = 13215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Khit'rix der Dunkle Meister", description = "Verschiedene Wesen reisen um die ganze Welt, um sich in Valhalas selbst zu beweisen; einige kommen sogar aus der Unterwelt.\n\nKhit'rix der Dunkle Meister ist so einer.\n\nEr ist in den Tiefen dieser Erde geboren, dort, wo Wahnsinn herrscht, und er verlangt nach jemandem, der anders als die meisten ist und sich ihm im Ring stellen wird. Ihr werdet genügen.\n\nWagt Ihr es, {race}, dem nerubischen Alptraum gegenüberzutreten?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Khit'rix den Dunklen Meister zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Ihr wollt mich damit beeindrucken, dass Ihr gemeinsam mit Euren Freunden einen einzelnen nerubischen Priester umhauen konntet?\n\nGeht mir aus den Augen, bevor ich meine Ghule auf Euch hetze!", sourceObjectiveStatus = "unverified-source-field" }
quests[13216] = { id = 13216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Die Rückkehr von Sigrid Eiskind", description = "Ein alter Feind von Euch ist zurückgekehrt: Sigrid Eiskind. Vielleicht könnt Ihr Euch noch daran erinnern, wie Ihr sie auf der Wilden Klippe besiegt habt?\n\nEgal, sie kann sich noch sehr gut an Euch erinnern. Sie besteht darauf, sich noch einmal beweisen zu dürfen.\n\nIch persönlich denke, dass es eher um Rache geht, doch auch das kann hier nützlich sein.\n\nIch überlasse es Euch, {name}. Werdet Ihr Euch einmal mehr Sigrid Eiskind stellen?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Sigrid Eiskind zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Der Sieg über eine der Hyldnir ist schon ein bisschen beeindruckend, {race}, aber Ihr hattet die Hilfe Eurer Freunde.\n\nIhr hattet Glück, dass Ihr Drache nicht mit von der Partie war.", sourceObjectiveStatus = "unverified-source-field" }
quests[13217] = { id = 13217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Massaker!", description = "Ihr habt es zwar bis hierher geschafft, {name}, doch um weiterhin in Valhalas zu kämpfen, müsst Ihr einem gigantischen Schrecken gegenübertreten, wie Ihr ihn Euch gar nicht vorstellen könnt.\n\nIch muss Euch dazu raten, jetzt kehrt zu machen. Massaker ist ein Fleischberg, erschaffen von den grausamsten Köpfen, die im Dienste des Lichkönigs stehen.\n\nIch kann mir nicht vorstellen, wie Eure Freunde und Ihr ihn besiegen wollt. Die Entscheidung liegt jedoch bei Euch.", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Massaker zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Euer Können im Ring flößt mir langsam Respekt ein, {name}. Jetzt kann ich Euch wirklich nicht leiden.\n\nIch hätte es lieber gehabt, Eure Freunde und Euch an der Fußsohle dieses Fleischriesens kleben zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13218] = { id = 13218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Than Todesstoß", description = "Die Vrykul von Jotunheim haben nicht übersehen, welches Können Ihr an den Tag legt, {name}. Than Banahogg hat ein persönliches Interesse an Euch gezeigt und darauf bestanden, Euer nächster Gegner zu sein.\n\nWenn Ihr Massaker schlimm fandet, dann wäre es wohl besser, wenn Ihr jetzt nach Hause geht. Than Banahoggs Spitzname ist \"Todesstoß\". Ich denke, Ihr könnt erraten, wie er sich den verdient hat.\n\nAkzeptiert Ihr die Herausforderung des Thans?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Than Banahogg den \"Todesstoß\" zu besiegen.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Ich weiß nicht, welche Tricksereien Ihr aus dem Ärmel gezogen habt, um den Than umzuhauen - von hier aus konnte ich's nicht sehen -, doch ich kann Euch versichern, dass Ihr Euren nächsten Kampf nicht überleben werdet.\n\nJa, ich weiß, wer es ist. Rennt, {race}, rennt weg! Flieht in die letzten Ecken dieser Welt.\n\nOder bleibt und sterbt - mir ist es gleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13219] = { id = 13219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Letzte Herausforderung", description = "Ich fürchte, dass Euer Erfolg auch Euer Untergang sein wird, {name}.\n\n<Könnte die Val'kyr noch bleicher werden, dann würde sie das gerade.>\n\nNachrichten über Euren Erfolg in Valhalas sind bis tief in die Eiskronenzitadelle vorgedrungen und haben jemanden wachgerufen, den Ihr lieber nicht kennen möchtet.\n\nPrinz Sandoval höchstpersönlich ist in diesem Augenblick auf dem Weg hierher. Gjonner hat Euch gewarnt und gesagt, dass Ihr wegrennen solltet, und ich kann ihm nicht widersprechen.\n\nWas werdet Ihr tun? Er ist auf dem Weg hierher. Werdet Ihr Euch dem Blutprinzen im letzten Kampf entgegenstellen?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Prinz Sandoval zu besiegen.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Euer Sieg über Prinz Sandoval macht mich krank. Ein ungewaschener Bauer wie Ihr es seid hätte freiwillig sein Leben dafür geben sollen, auch nur die Chance zu bekommen, ihm begegnen und vor seinen Füßen niederknien zu dürfen.\n\nIhr habt Eure verdammte Belohnung verdient. Entscheidet Euch schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[13220] = { id = 13220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olakin wieder zusammensetzen", description = "Wir können es uns nicht leisten, irgendwelche Zeit zu verlieren und Olakin wieder zusammenzusetzen. Zum Glück bietet Euch die Geißel den perfekten Ort, um ihn wieder zusammenzuflicken.\n\nIn der Nähe des Fleischriesenlabors in den Fleischwerken befindet sich das Sanktum der Reanimation. Sucht in der Gegend nach einer Garnspule und dem Spalter des Doktors. Bringt anschließend Olakins sterbliche Überreste zur großen Platte in der Mitte des Sanktums und macht Euch an die Arbeit.", sourceObjective = "Beschafft Euch eine Garnspule und den Spalter des Doktors. Geht dann zur Steinplatte des Sanktums der Reanimation und versucht, Kreuzfahrer Olakins sterbliche Überreste wiederzubeleben. Kehrt zu Dunkelreiterin Arly in die Schwarzwacht zurück, sobald die Aufgabe vollbracht ist.", completion = "Olakin sollte sich glücklich schätzen. Niemand wird aus den Fängen der Geißel befreit, niemand. Kein Garn der Welt und keine heldenhafte Tat wird ihn jedoch ein zweites Mal retten. Ich werde dafür sorgen, dass er sich daran erinnert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13221] = { id = 13221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch bin ich nicht tot!", description = "Das Licht ist mir hold. Noch bin ich in diesem wahrgewordenen Alptraum nicht umgekommen, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt, zu entkommen.\n\nAlleine werde ich es nicht schaffen, mein Kind, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen, zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", sourceObjective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Absalan dem Frommen an Bord der Himmelsbrecher Bericht.", completion = "Dem Licht sei Dank. Ich glaubte, Vater Kamaros sei tot, oder ihm sei noch Schlimmeres zugestoßen. Eure Tapferkeit und Euer Mitgefühl haben dazu geführt, dass ein wichtiger Verbündeter zum Argentumkreuzzug zurückkehren konnte. Ihr habt meinen Dank und den des Kreuzzugs.", sourceObjectiveStatus = "unverified-source-field" }
quests[13222] = { id = 13222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsmaschinen verteidigen", description = "An vorderster Front, {name}! Wir starten unseren Angriff auf die Tausendwinterfestung. Diese barbarischen Hordler denken wohl, sie könnten sich feige hinter ihren Mauern verkriechen? Nun, ich denke nicht! Wir werden ihnen zeigen, wie mächtig gnomische Technologie ist, und ihre Mauern zertrümmern!\n\nDoch ohne Mannschaft ist selbst die stärkste Belagerungsmaschine hilflos ausgeliefert. Steuert oder beschützt eine unserer Belagerungsmaschinen - es müssen drei Gebäude der Horde zerstört werden.", sourceObjective = "Chefdemolierer Legoso in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder beschützt. Die Maschine muss drei Gebäude zerstören.\n\nSpieler, die den Rang \"Gefreiter\" oder höher besitzen, können Belagerungsmaschinen in Goblinwerkstätten bauen.", completion = "Das sollte ihnen zeigen, wie mächtig gnomische Erfindungen sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[13223] = { id = 13223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsmaschinen verteidigen", description = "Die Allianz die Festung nicht mehr lange halten wird. Murp würde Mauern kaputt hauen, doch Murp muss im Lager bleiben. Murp wünscht sich, er könnte Allianzler kaputt hauen, die Verwüster von Horde wehtun wollen.\n\nDu, {name}! Du gehst anstatt Murp. Beschütz 3 Belagerungsmaschinen, wenn die gerade die Allianzgebäude kaputt machen. Zeig der Allianz wie klug Murp ist!", sourceObjective = "Leutnant Murp in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder verteidigt. Die Maschinen müssen 3 Gebäude der Allianz zerstören.\n\nBelagerungsmaschinen können von Spielern der Horde, die einen Rang haben, in Goblinwerkstätten gebaut werden.", completion = "Gute Arbeit. Murp wäre gern dabei gewesen, um zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13224] = { id = 13224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrims Hammer", description = "Der Argentumkreuzzug hat meinen böse zugerichteten Körper von der Zerbrochenen Front hergeschleppt. Was für ein ruhmreicher Kampf, {race}. Meine Axt sang, als sie ohne Unterschied Allianzabschaum und Geißler niedermachte.\n\nMeine Zeit ist vorüber. Es wird ein guter Tod sein. Überbringt eine Nachricht für mich, Soldat.\n\nUnsere Basis fliegt außerhalb der Reichweite der Geißel - hoch droben, zwischen Mord'rethar und Aldur'thar. Sie wird \"Orgrims Hammer\" genannt.\n\n<Hork bemüht sich vergeblich, zu salutieren.>\n\nFliegt hoch und geht dem Monstervehikel der Allianz aus dem Weg, der Himmelsbrecher. Sagt Korm... Sagt ihm, dass ich gestorben bin... im Kampf... Für die Horde.", sourceObjective = "Sucht Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer über dem Eiskronengletscher auf.", completion = "<Korm salutiert.>\n\nVerdammt soll die Geißel sein - und die Allianz! Hork war einer unserer Besten. Wir werden unsere Rache haben. Für Höllschrei und für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13225] = { id = 13225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Himmelsbrecher", description = "Wir steckten bis zum Hals in Einheiten der Geißel und der Horde. Die Schreie der Sterbenden erfüllten das Feld. Es war die reine Folter... erbarmungslos!\n\nMein Körper hat einfach irgendwann aufgegeben und ich fiel. Der Argentumkreuzzug hat mich wieder zurückgeholt. Sie haben mich von der Zerbrochenen Front geholt und hergebracht. Ich werde es aber nicht schaffen. Bitte, gewährt Ihr einem sterbenden Soldaten einen letzten Wunsch, {race}? Unsere Basis, die Himmelsbrecher, fliegt über der Eiskrone. Dort werdet Ihr meinen befehlshabenden Offizier, Stabshauptmann Bartlett antreffen. Sagt ihm, dass ich als Soldat der Allianz gestorben bin.", sourceObjective = "Sprecht mit Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher, die über der Eiskrone fliegt.", completion = "<Stabshauptmann Bartlett salutiert.>\n\nEr war ein verdammt guter Soldat. Verflucht sei die Horde und verflucht sei die Geißel!", sourceObjectiveStatus = "unverified-source-field" }
quests[13226] = { id = 13226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag der Abrechnung kommt!", description = "Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!\n\nIch beschwöre Euch, <Bruder/Schwester>, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.\n\nGeht jetzt, {class}, der Tag der Abrechnung steht bevor!", sourceObjective = "Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.", completion = "Meine treuen Ritter haben mir einen guten Dienst erwiesen. Es scheint, dass Ihre Anwerbungsbemühungen uns einen Helden beschert haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13227] = { id = 13227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag der Abrechnung kommt!", description = "Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!\n\nIch beschwöre Euch, <Bruder/Schwester>, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.\n\nGeht jetzt, {class}, der Tag der Abrechnung steht bevor!", sourceObjective = "Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.", completion = "Meine treuen Ritter haben mir einen guten Dienst erwiesen. Es scheint, dass Ihre Anwerbungsbemühungen uns einen Helden beschert haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13228] = { id = 13228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerbrochene Front", description = "Welche Schlacht?! Diese Truppen waren auf Aufklärungsmission!\n\nUnd was soll das Gerede von wegen Allianz?\n\nJetzt hört mir mal zu, {name}! Ich muss wissen, was hier vor sich geht und ich muss es JETZT wissen!\n\nBewegt Euch und besorgt mir ein paar Antworten! Durchkämmt das Schlachtfeld und sucht nach Überlebenden - Hinweisen - irgendwas etwas!", sourceObjective = "Korm Schwarznarbe an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und einen sterbenden Berserker dazu befragt, was geschehen ist.", completion = "Sie haben gesehen, dass die Allianz das Tor angegriffen hat und sie sind ihnen in den Rücken gefallen...\n\n<Nach einer kurzen Pause bricht Korm in Gelächter aus.>\n\nDAS ist genau das, wofür die HORDE steht!\n\nWenn sie nicht gewesen wären, so würden die Allianzmaden nun vermutlich das Tor halten!\n\nIhr Mut hat uns kostbare Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13229] = { id = 13229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch bin ich nicht tot!", description = "Das Licht ist mir hold. Noch bin ich in diesem wahr gewordenen Alptraum nicht umgekommen, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt, zu entkommen.\n\nAlleine werde ich es nicht schaffen, {class}, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen, zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", sourceObjective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Bruder Keltan an Bord der Orgrims Hammer Bericht.", completion = "Ihr habt gute Arbeit geleistet. Wir glaubten Vater Kamaros verloren. Eure Tapferkeit wird allen denen, die sich der Geißel widersetzen, als Beispiel dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13230] = { id = 13230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rächt mich!", description = "Ich kann sie hören, <Bruder/Schwester>...\n\nDas Stöhnen der verwundeten Allianzler... Sie verspotten mich...\n\nBeendet, was wir hier begonnen haben, {class}. Zeigt keine Gnade... Lasst niemanden am Leben.\n\nFür die Horde...", sourceObjective = "Ein sterbender Berserker hat Euch darum gebeten, 5 sterbende Soldaten an der Zerbrochenen Front zu töten. Erstattet Himmelshäscher Korm Schwarznarbe auf der Orgrims Hammer Bericht, sobald dies erledigt ist.", completion = "Die Zeiten der Toleranz gegenüber der Allianz sind vorbei, {name}.\n\nSie haben unseren Hass verdient! Sie sollen in Angst vor der Horde zittern, solange, bis sie nicht länger unsere Welt verschmutzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13231] = { id = 13231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerbrochene Front", description = "Was?! Neeeiinn!\n\nWir haben uns doch solche Mühe gegeben, diesen Angriff geheim zu halten. Woher wusste die Horde Bescheid? Die Reserven... Die Männer... Alles verloren? Unfassbar!\n\nUnsere Pläne in Eiskrone basierten darauf, dass das Tor vor der Horde genommen werden würde. Wir müssen uns schnell neu formieren und uns darauf vorbereiten, eine weitere Offensive zu starten.\n\nBegebt Euch zum Schlachtfeld und sucht nach Überlebenden. Versucht, so viele Informationen wie möglich über diese Tragödie zu sammeln.\n\nUnd macht Euch bereit, {name}, für einen Krieg - an zwei Fronten...", sourceObjective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr Euch an die Zerbrochene Front begebt, den sterbenden Soldaten befragt und ihm dann erneut Bericht erstattet.", completion = "Wir mussten also eine Schlappe einstecken - eine verheerende Niederlage... Dies wird nicht vergessen werden.\n\nMerkt Euch meine Worte, {class}. Die Horde wird hierfür bezahlen... Es wird keine Gnade geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13232] = { id = 13232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet mich!", description = "Sie verspotten uns - selbst noch hier, während sie im Sterben liegen...\n\nIch bitte Euch... Lasst es nicht zu, dass ihr Spott das Letzte sein wird, was ich höre...\n\nTötet mich... erlöst mich von dieser Qual... und führt mich... zum Licht.\n\nGeht zu meinen Gefährten... gewährt ihnen dieselbe Gnade.\n\nHinterlasst der Geißel nichts, das sie wiederbeleben könnte!\n\nIch flehe Euch an...", sourceObjective = "Der sterbende Soldat an der Zerbrochenen Front möchte, dass Ihr 5 sterbende Soldaten erlöst und dann Stabshauptmann Justin Bartlett auf der Himmelsbrecher Bericht erstattet.", completion = "Was Ihr getan habt, war nicht einfach, {class}, aber das Richtige.\n\nLasst Euch von den Erinnerungen an das, was Ihr getan habt, nicht quälen. Nutzt Eure Gefühle aus - den Kummer und den Schmerz! Nutz sie aus und richtet sie gegen die Schuldigen.\n\nDie Horde muss bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13233] = { id = 13233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade!", description = "Es ist, wie ich es Euch gesagt habe. Es waren nicht nur leere Worte, im Zorn gesprochen.\n\nWieder und wieder hat die Horde gezeigt, dass sie nichts auf das gibt, was uns am Herzen liegt. Für ihre Sünden gegen das Licht müssen sie mit dem Leben zahlen!\n\nJeder einzelne von ihnen.\n\nStellt Euch nur vor, {name}, eine Welt ohne ihren Makel. Malt Euch aus, wie glücklich unsere Kinder aufwachsen könnten. Denkt daran, wie ehrfürchtig Eure Nachkommen Euren Namen aussprechen würden - da sie doch wissen, dass sie all ihr Glück nur Euch zu verdanken haben.\n\nGeht nun und lasst die Vision Realität werden!", sourceObjective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr in Eiskrone 15 Spieler der Horde tötet.", completion = "Gut gemacht, {name}!\n\nBringt sie zur Strecke und lasst sie dafür bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13234] = { id = 13234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie müssen zahlen!", description = "Die Zeit ist gekommen!\n\nViel zu lange mussten wir die Selbstgerechtigkeit der Allianz ertragen! Viel zu lange mussten wir uns zurückhalten, haben unsere Welt nicht von Schwachen und Verzweifelten gereinigt.\n\nJetzt endlich werden wir die Erniedrigung beenden! Jetzt werden wir ihnen die wahre Bedeutung von Angst zeigen! Jetzt werden wir der Horde Ehre machen!\n\nHier, in Eiskrone, werden wir die Allianz brechen!\n\nGeht, {class}. Geht und bringt sie zur Strecke. Brecht sie! Nehmt ihnen den Willen zu leben!", sourceObjective = "Himmelshäscher Korm Schwarznarbe möchte, dass Ihr 15 Spieler der Allianz in Eiskrone tötet.", completion = "Ihr habt gute Arbeit geleistet, {class}.\n\nSchon bald wird die Allianz ängstlich vor Euch flüchten und die Horde wird Euren Namen ehren!", sourceObjectiveStatus = "unverified-source-field" }
quests[13235] = { id = 13235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gigantische Fleischgigant", description = "Mit der Zerstörung der Fleischwerke und der Vernichtung der Diener des Lichkönigs habt Ihr gute Arbeit geleistet. Nun ist alles, was noch zu tun bleibt, die Vernichtung des Meisterwerks der Fleischwerke - die Vernichtung des Fleischgiganten namens Morbidus.\n\nEs wird kein einfacher Kampf sein, doch das Schattengewölbe hat Markgraf Dhakar mit ein paar Unterstützungstruppen entsandt. Trefft Euch mit ihm beim höchsten Punkt der Fleischwerke am westlichen Rand. Sagt ihm Bescheid, wenn Ihr angriffsbereit seid, und er wird seine Truppen in die Schlacht schicken.", sourceObjective = "Sprecht mit Markgraf Dhakar am westlichen Ende der Fleischwerke, um die Aufmerksamkeit von Morbidus zu erregen. Erstattet der Dunkelreiterin Arly an der Schwarzwacht Bericht, nachdem Ihr Morbidus getötet habt.", completion = "Nun da des Lichkönigs Fleischgigant vernichtet ist, muss ihm klar sein, dass auch der Rest seiner Truppen nicht unverwundbar ist. Mit Euch an unserer Seite wird es uns gelingen, den Lichkönig erneut das Fürchten zu lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13236] = { id = 13236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee der Verdammten", description = "Ihr glaubt wahrscheinlich, Ihr wärt ziemlich stark - wie Ihr so gegen diese Untoten kämpft und ihre Knochen mit Euren Kriegsmaschinen zermalmt.\n\nDas ist jedoch nichts im Vergleich mit der Stärke, der es bedurfte, um sie zu erschaffen.\n\nIch habe gesehen, wie der Prinz selbst es gemacht hat. Ich kann Euch zeigen, wie das geht... wenn Ihr wollt.", sourceObjective = "Matthias Lehner im Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern auferstehen lasst.", completion = "Die wahre Macht des Prinzen lag nicht darin, aus Leichen Armeen zu erschaffen... das war einfach.\n\nAber seine eigenen Männer zu töten, diejenigen, an deren Seite er viele Kämpfe bestritten hat... Die wahre Macht des Prinzen lag darin, das tun zu können, was er tun musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[13237] = { id = 13237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stechen und Stoßen", description = "Verlasst Euch drauf, während Euer Hauptmann von seinem Hass auf die Rivalen Eurer Allianz abgelenkt ist, richte ich meine volle Aufmerksamkeit auf den wahren Feind hier: den Lichkönig und seine Untergebenen.\n\nUm auch nur darauf hoffen zu können, ihn in seiner Zitadelle zu besiegen, müssen Eure Leute beide Tore erobern und halten.\n\nKonzentrieren wir uns für den Augenblick jedoch auf das Erste. Kehrt zur Front zurück und stoßt durch ihre Verteidigungslinie. Sucht nach irgendwelchen Schwachstellen, die wir ausnützen könnten.\n\nIch erwarte Euren Bericht, {class}.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten besiegt.", completion = "Wirklich, {class}?\n\nNichts Besonderes zu berichten?\n\n\n\nDa bin ich anderer Meinung...", sourceObjectiveStatus = "unverified-source-field" }
quests[13238] = { id = 13238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu etwas zu gebrauchen?", description = "Goblins! Überdrehte Wichtigtuer...\n\nHört mal, {name}. Kupferklammer, unser Hausingenieur, besteht darauf, dass er etwas Nützliches gefunden hat, was er mir unbedingt zeigen muss.\n\nIch bin nicht in der Stimmung, mir sein piepsiges Gezeter anzuhören. Das letzte Mal, dass ich ihm Aufmerksamkeit schenkte, hat er glatt eine Stunde lang durchgequäkt. Ich konnte mich gerade noch davon abhalten, ihn mit einem Tritt in Sindragosas Sturz zu befördern!\n\nIhr werdet an meiner Statt gehen und ihm Honig ums Maul schmieren. Lasst es mich wissen, falls er tatsächlich etwas herausgefunden haben sollte.", sourceObjective = "Himmelshäscher Korm Schwarznarbe möchte, dass Ihr mit dem Chefingenieur Kupferklammer an Bord der Orgrims Hammer sprecht.", completion = "Zu beschäftigt? Pühhh! Das Baby hier fliegt sich doch selbst!\n\nVergesst das. Ihr tut's auch...", sourceObjectiveStatus = "unverified-source-field" }
quests[13239] = { id = 13239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflüchtigung", description = "Wo soll ich anfangen...? Nun, Ihr müsst wissen, dass ich als Chefingenieur dieses Fahrzeugs Zugang zu allen möglichen nachrichtendienstlichen Berichten habe - ja, ja, es ist wahr, und seit Kurzem interessiere ich mich ganz besonders für die Frostwyrm, die Ihr im Süden gesichtet habt. Ich denke, ich habe einen Plan entwickelt, wie ihnen beizukommen sein könnte... Gut, ein paar Kleinigkeiten müssen noch von Euch erledigt werden, aber eigentlich nur folgendes: Ihr baut eine Attrappe aus Rüstungsteilen und bestreicht sie mit dieser Lösung hier und dann geht Ihr in Deckung!\n\n... Immer noch da, {race}?", sourceObjective = "Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt um 3 Frostbrutvollstrecker anzulocken.\n\nUm das Öl benutzen zu können, müsst Ihr auf dem Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und zurückgelassene Rüstung einsammeln.", completion = "Juhuu! Ich hab' von hier aus gesehen, wie sie in Flammen aufgegangen sind! Ich werde das mal als weiteren Erfolg verzeichnen und anfangen, das Zeug für die Invasion abzufüllen - obwohl es natürlich noch einiger weiterer Versuche bedarf, wenn es Euch interessiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[13240] = { id = 13240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Zentrifugenkonstrukte in Eurer Zukunft!", description = "Ihr müsst zum Oculus über Kaltarra reisen, {name}.\n\nIch habe eine Situation vorausgesehen, in der Ihr die dortigen Zentrifugenkonstrukte zerstören müsst. Ich kann Euch versichern, dass, solltet Ihr nicht zuerst diese magischen Schöpfungen beseitigen, Eure Gruppe versagen wird.\n\nDies habe ich gesehen und dies müsst Ihr tun.", sourceObjective = "Erzmagier Timear in Dalaran hat vorausgesehen, dass Ihr 10 Zentrifugenkonstrukte zerstören müsst.", completion = "<Der Erzmagier nickt, bevor Ihr überhaupt etwas gesagt habt.>\n\nIch weiß. Ihr habt die Konstrukte, wie ich vorhergesehen habe, zerstört und konntet dann dazu überschreiten, gegen Varos Wolkenwanderer zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13241] = { id = 13241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Berserker der Ymirjar in Eurer Zukunft!", description = "In nicht allzu ferner Zukunft werden zwischen Euch und dem Sieg lediglich König Ymirons Champions stehen.\n\nIhr werdet zur Festung namens Turm Utgarde tief in den Wäldern des Heulenden Fjords reisen. Ich kann nicht genug betonen, wie wichtig es ist, dass Ihr und Eure Reisegefährten Euch um die dortigen Berserker der Ymirjar kümmert.\n\nSolltet Ihr dies versäumen, ist es gut möglich, dass es Euch zum Verhängnis werden wird, {name}!", sourceObjective = "Erzmagier Timear in Dalaran möchte, dass Ihr 7 Berserker der Ymirjar tötet.", completion = "Ausgezeichnete Arbeit, {name}.\n\nHättet Ihr dies nicht getan, hättet Ihr im Kampf mit dem König sicherlich gegen unzählige der überlebenden Berserker kämpfen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13242] = { id = 13242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelheit regt sich", description = "Die Dunkelheit regt sich, {name}. Etwas Tragisches hat sich ereignet, das niemand außer der Zeitlose selbst voraussehen hätte können. Bald wird Euer Volk von Wut und Hass erfasst werden. Krieg ist am Horizont.\n\nDer rote Drachenschwarm hat alles getan, was in seiner Macht steht. Was als nächstes passiert, liegt in den Händen der sterblichen Völker Azeroths.\n\nLeider beginnt Eure Reise mit Schmerz. Ein Vater hat heute ein Kind verloren und Ihr müsst die schlimmen Nachrichten überbringen. Sammelt Saurfangs Rüstung ein und bringt sie zum Ältesten Saurfang zurück.", sourceObjective = "Geht aufs Schlachtfeld hinaus, sucht nach Saurfangs Schlachtrüstung und bringt sie zu Hochfürst Saurfang in der Kriegshymnenfestung in der Boreanischen Tundra.", progress = "<Saurfangs Miene verzieht sich.>\n\nMein Herz... meine Stärke...", completion = "<Saurfang blickt gen Himmel.>\n\nWie auch Brox, so starb auch mein Sohn als Held. Trauert nicht über ihn, {name}. Für einen Orc gibt es kein besseres Ende! Keine größere Ehre! In diesem Moment schwillt mein Herz vor Stolz.\n\nIch danke Euch dafür, dass Ihr unsere Schlachtrüstung zurückgebracht habt. Sie wird auf seinen Scheiterhaufen auf dem Ahnengrund in Nagrand gelegt werden.\n\nWir müssen unsere volle Aufmerksamkeit dringlicheren Angelegenheiten zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13243] = { id = 13243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Ewige Agenten in Eurer Zukunft!", description = "Die Zeitlinie wird vom ewigen Drachenschwarm bedroht. Ohne Euer Eingreifen, wird die Zeit zunichte gemacht werden!\n\nIhr müsst in die Höhlen der Zeit gehen und zu einem Zeitpunkt zurückreisen, an dem ein Ereignis namens 'das Ausmerzen von Stratholme' stattfand.\n\nMir bereitet es Kopfschmerzen, auch nur zu versuchen, in alle möglichen Vergangenheiten zu blicken, doch ich weiß, dass es äußerst wichtig für Euch ist, die ewigen Agenten zu töten.\n\nNur durch ihren Tod wird die wahre Vergangenheit beibehalten und Gegenwart und Zukunft davor bewahrt, für immer ungeschehen gemacht zu werden!", sourceObjective = "Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 4 ewige Agenten töten müsst.", completion = "Für den Augenblick sind wir gerettet. Habt Dank.\n\nUnglücklicherweise bieten sich den Ewigen aufgrund der Art und Weise ihres Eingreifens beinahe endlos viele Möglichkeiten, dies wieder zu tun.\n\nWas ich erkennen kann, ist, dass in Zukunft Ihr im Herzen des Kampfes gegen sie stehen werdet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13244] = { id = 13244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Titanvorposten in Eurer Zukunft!", description = "Ganz Azeroth ist in Gefahr. Der verrückte Gott Loken besitzt die Macht, allem ein Ende zu bereiten!\n\nIm Irdischen Wachturm in den Hallen der Blitze stehen Titanvorposten kurz davor, Lokens schrecklichen Willen auszuführen - dem würden unzählige Ahnungslose zum Opfer fallen.\n\nIch habe in die Zukunft geblickt, {name}. Ihr seid <derjenige, der/diejenige> die; sich darum kümmern wird, dass dies nicht geschieht!", sourceObjective = "Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 7 Titanvorposten töten müsst.", completion = "Wir stehen alle in Eurer Schuld, {name}.\n\nWenn ich mir über irgendetwas sicher bin, dann ist es das, dass Ihr uns in der Vergangenheit nicht enttäuscht habt und dies auch in Zukunft nicht tun werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[13245] = { id = 13245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Ingvar der Brandschatzer", description = "Ihr müsst eine Gruppe zusammenstellen und sie nach Burg Utgarde führen. Dort sollt Ihr dann nach Ingvar dem Brandschatzer suchen und ihn töten, bevor er mit seinen Vrykultruppen die nahegelegenen Städten der Allianz und Horde überfallen und plündern kann.\n\nIch brauche seine Axt als Beweis dafür, dass man sich um ihn gekümmert hat. Es wäre ja nicht so, dass ich Euch nicht vertrauen würde. Doch es ist einfach nur klug, sich absolut sicher zu sein, ob die Aufgabe nun erledigt wurde.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der Axt des Brandschatzers zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr die Axt? Ist Ingvar tot?", completion = "Sehr gut. Legt die Axt einfach bei der Wand dort drüben ab.\n\nIch bin mir sicher, dass man in Valgarde und im Hafen der Vergeltung heute Abend etwas ruhiger ist, nun, da Ihr Euch um den Barbaren gekümmert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13246] = { id = 13246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Keristrasza", description = "Seid Ihr mit der Geschichte von Keristrasza vertraut?\n\nDamit, dass sie maßgeblich daran beteiligt war, Saragosa, Malygos' Gefährtin, zu töten? Wie er wiederum Keristrasza zur Gemahlin nahm und sie in einen Block aus Eis einschloss?\n\nWir wissen nun, dass Malygos seine Magie dazu benutzt hat, um ihren Willen zu brechen, was sie in den Wahnsinn getrieben hat.\n\n{name}, Ihr müsst in den Nexus nach Kaltarra gehen und ihr ein Ende bereiten, bevor sie komplett überläuft.\n\nZwar macht es mich traurig, doch ich muss darauf bestehen, dass Ihr mir ihr Herz als Beweis bringt.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit Keristraszas gebrochenem Herzen zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wenn wir einen Weg gewusst hätten, wie wir sie erlösen können, hätten wir Euch nicht darum gebeten, ihrem Leben ein Ende zu bereiten.\n\nWir wissen jedoch, wie mächtig Malygos' Beherrschung der magischen Kräfte geworden ist. Seiner Beeinflussung der Leylinen Azeroths ist es zu verdanken, dass ihm heute niemand gleich kommt, wenn es um das Arkane geht.", completion = "Bedauerlich, doch äußerst notwendig.\n\nDie Kirin Tor könnten es sich nicht leisten, einen der wichtigsten roten Großdrachen an unseren größten Feind zu verlieren. Hätte Malygos sie im Nexuskrieg gegen uns eingesetzt, wäre dies verheerend gewesen.\n\nIch bedauere es einfach, dass wir sie stattdessen nicht haben retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13247] = { id = 13247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Leywächter Eregos", description = "Der Nexuskrieg tobt weiter und wir müssen etwas unternehmen, um das Blatt zu wenden! Seid Ihr willens, ins Herz der Schlacht zu fliegen, {name}?\n\nLeywächter Eregos ist der Beschützer des Kanals, durch den Malygos die magische Energie von Azeroths Leylinien schleust. Würde er getötet, wäre dies ein großer Rückschlag für den Feind.\n\nBitte bringt mir einen seiner Leylinienempfänger, damit wir ihn untersuchen können.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit einem Leylinienempfänger zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr Euch um den Leywächter gekümmert, {class}?\n\nIch muss Euch nicht daran erinnern, dass Malygos versucht, jeglichen Gebrauch von Magie auf der Welt zu unterbinden, und dass der blaue Drachenschwarm jeden tötet, der mit ihr umgehen kann und nicht auf ihrer Seite ist.", completion = "Habt Dank, {name}. Die Untersuchung dieses Empfängers sollte uns weitere Einblicke darüber verschaffen, wie Malygos die Leylinien manipuliert.\n\nWenn wir eine Schwachstelle in seinem Ansatz finden können, wären wir vielleicht in der Lage, sie auszunutzen und das Blatt zu wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13248] = { id = 13248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: König Ymiron", description = "König Ymiron im Turm Utgarde ist der Lieblingsvrykul des Lichkönigs. Das alleine ist Grund genug, ihm ein Ende zu bereiten.\n\nDoch sollte er die Hörner erschallen lassen und alle Anführer der Ymirjar sowie der Mjordin zu sich rufen, würden die Vrykul zu einer Macht heranwachsen, die stärker als jede andere Gruppe innerhalb der Geißel wäre!\n\nEs liegt an Euch, {name}, dafür zu sorgen, dass dies nicht geschieht. Bringt mir das Medaillon, das er um seinen Hals trägt, damit ich weiß, dass Ymiron keine Gefahr mehr darstellt.", sourceObjective = "Erzmagier Lan'dalok in Dalaran möchte, dass Ihr mit dem Medaillon der verstorbenen Königin zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ymiron darf das Reich der Vrykul nicht vereinen. Sollte er triumphierend nach Eiskrone zurückkehren, wird sehr wahrscheinlich alles verloren sein.", completion = "<Der Erzmagier nickt ernst, als Ihr ihm das etwas große geratene Schmuckstück überreicht.>\n\nWas getan ist, ist getan. Welch edles Volk, diese Vrykul. Schade nur, dass der Lichkönig seine tödlichen Haken in sie hineingetrieben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13249] = { id = 13249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Der Prophet Tharon'ja", description = "Einst war die Feste Drak'Tharon eine stolze Bastion des Drakkarireiches. Nun ist sie nichts weiter als ein Sprungbrett für den Lichkönig in seinem Kampf, Zul'Drak ein Ende zu bereiten und die Kräfte der Trollgötter an sich zu reißen.\n\nDoch sollten wir ihren Anführer Prophet Tharon'ja ausschalten, könnten wir vielleicht den Zustrom weiterer Trolle der Geißel verhindern. Das Mindeste, was dabei herauskommen könnte, wäre, dass der Argentumkreuzzug in Zul'Drak eine Sorge weniger hat.\n\nBringt mir sein Tiki, damit ich weiß, dass der Prophet tot ist.", sourceObjective = "Erzmagier Lan'dalok in Dalaran möchte, dass Ihr mit dem verzauberten Tiki des Propheten zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr Euch dem Propheten schon gestellt? Habt Ihr das Tiki bei Euch?", completion = "Mit etwas Glück wird die Feste Drak'Tharon jetzt, da sie ohne Anführer ist, ein kleineres Problem für diejenigen darstellen, die in dieser Region gegen die Geißel kämpfen.\n\n<Der Erzmagier blickt auf das Tiki in Eurer Hand.>\n\nAuch ist es gut, dass das Tiki sein Mojo verloren hat. Ich hätte keine Vorstellung davon gehabt, wie man es benutzt, geschweige denn, ob es das Richtige wäre, dergleichen zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13250] = { id = 13250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Gal'darah", description = "Die Drakkaripropheten von Zul'Drak haben das undenkbare getan: Sie haben die meisten ihrer Götter getötet und ihre Kraft in sich aufgenommen! Der gefährlichste von allen ist Akalis Hochprophet Gal'darah.\n\nGal'darah hält sich in den Tiefen von Gundrak verborgen und hat fast das gesamte Mojo des toten Akali in sich aufgesaugt. Nun ist er kurz davor, mit seinen Anhängern aus der Stadt auszubrechen. Wenn wir ihn jetzt nicht töten, werden wir in einem Meer des Wahnsinns ertrinken und von unvorstellbarer Macht erdrückt!\n\nBeeilt Euch, {name}, bringt mir, was von Akalis Mojo übrig geblieben ist.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit den Überresten von Akalis Mojo zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr das Mojo dabei?\n\nEs macht mich krank, mit ansehen zu müssen, wie ein weiteres großes Trollreich zugrunde geht.\n\nIch kann mir nur denken, dass, hätte sich der Lichkönig nicht eingemischt, die Trolle sich nicht dazu gezwungen gesehen hätten, sich gegen ihre eigenen Götter zu wenden und ihre Kraft zu stehlen, um sie als Verteidigung gegen die Geißel einzusetzen.", completion = "Habt Dank, {name}. Ich werde mich darum kümmern, dass die Essenz der Götter so lange sicher aufbewahrt wird, bis sie an den Stamm der Zandalari übergeben werden kann.\n\nVielleicht werden sie in der Lage sein, einen Weg zu finden, Akali mit dieser Essenz wieder ins Leben zu rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13251] = { id = 13251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Mal'Ganis", description = "{name}, ein Freund innerhalb des bronzenen Drachenschwarms hat mir Informationen zukommen lassen, die wir ausnützen müssen.\n\nDie mysteriösen Geschöpfe der Brennenden Legion namens Schreckenslords werden in Hinblick auf ihre Rasse auch als die Nathrezim bezeichnet. Wenig ist über ihre Heimatwelt bekannt, und selbst das ist nur ein Gerücht.\n\nEs ist jedoch bekannt, dass Mal'Ganis in der Vergangenheit einen entscheidenden Fehler gemacht hat: er hinterließ ein Artefakt seiner Heimatwelt!\n\nÜber die Höhlen der Zeit müsst Ihr in der Zeit zurückreisen und einem Ereignis beiwohnen, das auch 'das Ausmerzen von Stratholme' genannt wird. Beschafft das Artefakt.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem Artefakt aus der Heimatwelt der Nathrezim zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wir müssen Mal'ganis' Fehler ausnutzen. Es kommt nicht jeden Tag vor, dass sich uns solch eine Chance bietet.\n\nWenn wir dieses Artefakt untersuchen können, könnten wir die Nathrezim vielleicht besser verstehen!", completion = "Erstaunlich! Ich habe noch nie etwas ähnliches gesehen. Ich werde mich darum kümmern, dass es den richtigen Händen in der Violetten Zitadelle übergeben wird.\n\nWenn man Euch nur erlaubt hätte, den Lauf der Geschichte zu ändern. Wenn man Arthas vielleicht davon abgehalten hätte... nein, so etwas führt nur ins Chaos.\n\nDie Hüter der Zeit kennen sich mit solchen Angelegenheiten am besten aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13252] = { id = 13252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Sjonnir der Eisenformer", description = "Nur wenig ist über das Leiden bekannt, welches 'Fluch des Fleisches' genannt wird. In den Hallen des Steins gibt es jedoch Informationen zu holen.\n\nSjonnir der Eisenformer scheint sich ziemlich gut mit dem Fluch auszukennen. Wir wissen aus guter Quelle, dass er eine titanische Informationsscheibe bei sich hat, die all unsere Fragen beantworten könnte.\n\nBesorgt mir diese Scheibe, {name}, damit wir mehr erfahren können.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der 'Datenscheibe: Fluch des Fleisches' zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr die Scheibe?", completion = "Ist sie nicht erstaunlich, die Titanentechnologie? Die Informationen befinden sich in der Scheibe selbst!\n\nIch hoffe nur, wir können herausfinden, wie wir sie aus der Scheibe herausbekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13253] = { id = 13253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Loken", description = "Loken im Inneren der Hallen der Blitze steht kurz davor, unserer Welt ein Ende zu bereiten. Muss ich noch mehr sagen, {name}?\n\nEr sitzt dort und lauscht dem verrückten Geflüster des Alten Gottes, der unter Nordend gefangen ist. Ihr müsst umgehend mit einer Gruppe zu den Sturmgipfeln reisen!\n\nGeht zum Irdischen Wachturm und stellt Euch Loken zum Kampf. Haltet ihn auf, bevor es zu spät ist! Bringt mir seinen Rubinring, damit ich weiß, dass wir wieder sicher sind.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem himmlischen Rubinring zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wir sprechen wieder miteinander, {name}. Bedeutet das, dass wir vor Lokens Wahnsinn sicher sind? Oder sind wir dem Untergang geweiht.", completion = "<Erzmagier Lan'dalock seufzt vor Erleichterung.>\n\nUm ehrlich zu sein, hatte ich befürchtet, dass Euch das Schlimmste zugestoßen wäre. Es ist schwierig, untätig herumzustehen, während andere wie Ihr sich mit Angelegenheiten auseinandersetzen, bei denen es um Leben und Tod geht und die unsere Welt anscheinend tagtäglich beschäftigen.\n\nWas werden wir mit diesem gigantischen Ring jetzt bloß nur anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13254] = { id = 13254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Anub'arak", description = "Die Neruber der Geißel sind eine Plage für unsere Truppen.\n\nHier, über der Welt schwebend, sind wir zwar vor ihnen sicher, doch setzt man seinen Fuß auf das Land unter uns, hat man ständig den Gedanken im Hinterkopf, dass die untoten Neruber aus den Tiefen Azjol-Nerubs jeden Augenblick aus der Erde springen und angreifen könnten.\n\nEs liegt im besten Interesse von uns allen, wenn sie ins Chaos gestürzt werden. Tötet ihren früheren König, den Majordomus des Lichkönigs, den Gruftlord Anub'arak.\n\nBitte bringt mir seine Krone... es wäre ja nicht so, dass er sie noch trägt.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der unnützen Krone Anub'araks zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich bin froh, dass Ihr es seid, der nach Azjol-Nerub hinabsteigt, nicht ich.\n\nIch bin nicht gerne unter der Erde.", completion = "Welchen Schrecken Ihr begegnet sein müsst, als Ihr die Oberstadt durchquert habt.\n\n<Lan'dalock wirft einen Blick auf die stumpfe Krone in Eurer Hand.>\n\nVielleicht sollten wir das für den Zeitpunkt beiseite legen, wenn sich die Neruber dazu entschließen, einen neuen König zu krönen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13255] = { id = 13255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Herold Volazj", description = "Die Neruber von Ahn'kahet gruben zu tief, als sie versuchten, dem Überfall der Geißel zu entkommen. Sie kamen dem alten Gott in den Tiefen Nordends zu nah.\n\nDer alte Gott, von ihnen wach gerufen, hetzte seine wild gewordenen Kreaturen auf sie - die Neruber saßen also sprichwörtlich in der Klemme.\n\nHerold Volazj, der Anführer der Streitkräfte des alten Gottes, ist eines der alptraumhaften Wesen, die auch die Gesichtslosen genannt werden. Beseitigt ihn und bringt mir sein verdorrtes Gehirn.\n\nNur bitte ich Euch, dass Ihr versucht, bei Verstand zu bleiben.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem siechenden Gehirn des Gesichtslosen zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "{name}? Seid Ihr noch bei Verstand?", completion = "<Der Erzmagier beäugt das Gehirn misstrauisch.>\n\nWo ich gerade daran denke: Ich bin mir nicht so ganz sicher, ob man sich ohne Gefahr so nah an diesem Ding aufhalten kann. Ihr meint also, dass es noch immer am Leben ist?\n\n<Er schüttelt seinen Kopf.>\n\nWir haben einen Platz für solche Dinge hier in der Zitadelle. Ich werde mich darum kümmern, dass einer meiner Lehrlinge es umgehend dorthin bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13256] = { id = 13256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Cyanigosa", description = "Wir werden überfallen! Der blaue Drachenschwarm hat sich in die Violette Festung teleportiert und sie planen, von dort auszubrechen und sich im Rest von Dalaran zu verbreiten!\n\nEs gab schon Berichte von Gefangenen, die dadurch versehentlich befreit wurden. Es würde mich nicht wundern, wenn sie einige von ihnen absichtlich freilassen würden.\n\n{name}, könnt Ihr schnell ein Team zusammenstellen und Euch dorthin begeben? Cyanigosa ist die Anführerin der Invasionstruppen. Bringt mir ihren Kopf!", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit Cyanigosas Kopf zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wenn ich so darüber nachdenke: Weshalb würde sich jemand in ein Gefängnis hineinteleportieren, nur um dann wieder auszubrechen? Es handelt sich hier ja nur um den sichersten Ort in der ganzen Stadt.\n\nDie Blauen müssen wirklich verrückt geworden sein!", completion = "Die Gefahr ist vorüber und der Rest der Gefangenen, die ausgebrochen sind, sitzen einmal mehr im Gefängnis.\n\nDalaran schuldet Euch Dank, {name}!\n\nNun muss ich mit jemanden darüber sprechen, wieso es so einfach gewesen ist, den Teleportationsschutz des Gefängnisses zu umgehen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13257] = { id = 13257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbote des Krieges", description = "Champion, der Kriegshäuptling braucht Euch. Über Orgrimmar ist das Kriegsrecht verhängt worden. Alle Handels- und Dienstleistungsaktivitäten wurden eingestellt, während sich der Kriegshäuptling auf einen unvermeidlichen Konflikt vorbereitet.\n\nMehr kann ich Euch nicht sagen - nicht jetzt, nicht hier.\n\nDer Kriegshäuptling befiehlt, dass sich die stärksten Champions in seinem Thronsaal melden. Geht jetzt, {name}! Nehmt das Portal zurück nach Orgrimmar und sucht Thrall auf.", sourceObjective = "Meldet Euch bei Thrall in der Feste Grommash in Orgrimmar.", completion = "Dämonenfürst Varimathras und Chefapotheker Putress sind für diesen Verrat verantwortlich.\n\n<Thrall nickt.>\n\nDerselbe Putress, der auch das Heilmittel gegen die letzte Seuche der Geißel gefunden hat.\n\nDiejenigen, die sich ihrem Regime nicht anschließen wollten, sind hingerichtet oder verbannt worden. Sylvanas wurde bei dem Staatsstreich beinahe getötet.\n\nFür die Horde ist die Unterstadt verloren. Orgrimmar wird die Flüchtlinge der Verlassenen aufnehmen, bis diese Krise überwunden ist. Fürs erste stehen wir unter Kriegsrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13258] = { id = 13258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheit", description = "Wir sind kürzlich über Schemata gestolpert, die auf eine Schwachstelle in der Eiskronenzitadelle hinweisen - eine offene Stelle in ihrer Verteidigung, bildlich und wörtlich genommen.\n\nDie Pläne, die gefunden wurden, zeigen eine Öffnung, die mehrere hundert Meter in den Boden geht. Wir sind uns nicht sicher, welchem Zweck sie dient, doch unseren Aufklärungsberichten zufolge ist sie für die Geißel äußerst wichtig.\n\nSprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle. Sie leitet den dortigen Angriff.", sourceObjective = "Sprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle.", completion = "Gerade rechtzeitig, {name}. Koltira hatte gute Worte für Euch übrig. Vielleicht werdet Ihr in der Lage sein, die Situation zu unseren Gunsten zu ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13259] = { id = 13259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Überlegenheit sorgen", description = "Wir haben eine einzige Chance, dieser Zitadelle ein wenig Schaden zuzufügen - sorgen wir also dafür, dass wir's richtig machen.\n\nWir sind in den Besitz von schweren Saronitbomben gelangt, die von der Geißel hergestellt wurden. Doch bevor wir sie loslassen können, müssen wir erst die Gegend sichern.\n\nWir werden die Verteidigungsstellungen der Geißel schnell unter Kontrolle bringen müssen, bevor ihre Verstärkung eintrifft.\n\nSteht meinen Männern zur Seite und kommt wieder zurück, wenn Ihr bereit für ein kleines Feuerwerk seid.", sourceObjective = "Unteroffizier Kregga an der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.", completion = "Ihr habt kurzen Prozess mit der Geißel gemacht, {name}. Lasst uns zu Ende bringen, weswegen wir hier sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13260] = { id = 13260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Insider", description = "Obwohl wir keine Gelegenheit auslassen sollten, der Allianz einen Schlag zu versetzen, dürfen wir auf gar keinen Fall die Geißel vergessen.\n\nWir haben zwar nicht genug Männer, um in den nächsten Wochen einen vernünftigen Ausfall in den Gletscher zu wagen, doch sollte uns das nicht davon abhalten, so viel wie möglich über ihre Verteidigung in Erfahrung zu bringen.\n\nIch habe unseren Todesritter gebeten, Euch in dieser Sache zu beraten. Schließlich kennt niemand den Feind besser als sie.\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.", sourceObjective = "Himmelshäscher Korm wünscht, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.", completion = "<Koltira mustert Euch.>\n\nIch hoffe für Euch, dass Ihr dem gewachsen seid, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13261] = { id = 13261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflüchtigung", description = "Wahuu! Es funktioniert! Nicht dass ich irgendwelche Zweifel an meiner übernatürlichen Genialität gehabt hätte... Ich war nur nicht ganz sicher, was für eine Art von Explosion kommen würde... Lasst uns einfach sagen, dass ich froh bin, dass Ihr Euch nicht die Augenbrauen abgefackelt habt... So, nun muss ich dem alten Korm nur zeigen, wie man die Wyrm auftaut. Dann muss er mich befördern zum... zum... zu was-auch-immer nach Chefingenieur kommt! Hier, nehmt noch eine Portion von dem Zeug und kehrt an die Front zurück, ich werde mit Korm reden...\n\nNa? Bewegt Euch!", sourceObjective = "Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt, um 3 Frostbrutvollstrecker anzulocken.\n\nUm das Öl benutzen zu können, müsst Ihr auf dem dortigen Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und eine zurückgelassene Rüstung einsammeln.", completion = "Nichtsnutz!\n\nKorm sagte bloß, er sei zu beschäftigt, und als ich ihn endlich dazu gekriegt hab', nach oben zu kommen und es sich anzusehen, hattet Ihr auch schon alles Öl aufgebraucht. Jetzt ist er verärgert und will mich bis morgen nicht einmal mehr in seiner Nähe haben...\n\nKommt dann wieder und wir versuchen es nochmal!", sourceObjectiveStatus = "unverified-source-field" }
quests[13262] = { id = 13262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt es hoch!", description = "Besser werden wir die Sache hier wohl nicht unter Kontrolle bekommen. Legen wir los, {name}.\n\nIch brauche jemanden, der die Lunten an diesen Bomben anzündet, und es sieht so aus, als wärt Ihr derjenige.", sourceObjective = "Geht zu dem nahen Saronitbombenstapel und zündet die Lunte an.", completion = "Diese Bomben sehen ziemlich durchschlagskräftig aus. Sie sollten zumindest für eine ordentliche Delle in der umgebenden Struktur sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13263] = { id = 13263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kurze Lunte", description = "Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.\n\nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.", sourceObjective = "Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.", completion = "Dieses pulsierende Objekt ist von einer dicken Eisschicht umgeben. Es schimmert geheimnisvoll unter Wasser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13264] = { id = 13264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Monstrositäten...\n\nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.\n\nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.\n\nZu Eurem Glück kenne ich diese Geheimnisse.\n\nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Seht Ihr, {class}?\n\nRaffinesse kann mitunter selbst in aussichtslos scheinenden Situationen für Chancengleichheit sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13265] = { id = 13265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Dem Schnitt Eurer Kleider nach zu urteilen nehme ich an, dass Ihr selbst ein Schneider seid und somit leicht erlernen könnt, was ich beizubringen habe.\n\nViele der Humanoiden des Nordens tragen Kleider, die recht schnell in Stoff umgewandelt werden können, wenn man den Dreh raus hat.\n\nGegen eine kleine Gebühr kann ich Euch beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", completion = "Ihr findet extra Stoff? Macht aus ihm etwas Wunderschönes!" }
quests[13266] = { id = 13266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leben ohne Reue", description = "Am Tage meines Todes möchte ich sagen können, dass ich ein Leben ohne Reue geführt habe. Diejenigen, die mein Dahinscheiden betrauern, werden wissen, dass ich ein Kriegshäuptling war, der die besten Entscheidungen für sein Volk getroffen hat.\n\nDoch Varimathras' und Putress' Verrat... Alles, wofür wir gearbeitet haben, ist umsonst gewesen.\n\n<Thrall gibt einen langen Seufzer von sich.>\n\nPortale nach Unterstadt werden vorübergehend aktiv sein. Vol'jin wird auf Euch warten. Ich werde Euch schon bald dort antreffen. Gemeinsam werden wir die Sache wieder bereinigen, {name}.", sourceObjective = "Nehmt das Portal nach Unterstadt, das sich in der Feste Grommash befindet, und meldet Euch bei Vol'jin.", completion = "Lasst mich Euch auf den neuesten Stand bringen, {name}.\n\nUnterstadt ist eine Kriegszone. Putress' Apotheker und Varimathras' Dämonen haben die Kontrolle übernommen. Sie haben sich drinnen verschanzt und setzen diese verdammte Seuche gegen unsere Truppen ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13267] = { id = 13267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Unterstadt", description = "Ganz Unterstadt steht unter Varimathras' Kontrolle. Unsere Soldaten stehen bereit und warten auf den Angriffsbefehl des Kriegshäuptlings.\n\nHelft der Horde, Unterstadt zurückzuerobern, und verdient Euch einen Platz unter unseren größten Champions! Erstattet Thrall Bericht, falls Ihr den Angriff überleben solltet.\n\nMeldet Euch beim Kriegshäuptling, sobald Ihr bereit seid loszulegen.", sourceObjective = "Unterstützt Thrall und Sylvanas, Unterstadt für die Horde zurückzuerobern.\n\nMeldet Euch bei Thrall, solltet Ihr erfolgreich sein.", completion = "Die Zukunft ist unsicher. Die Tage, an denen Horde und Allianz Seite an Seite gegen einen gemeinsamen Feind kämpften, sind gezählt. Dies ist der Beginn einer neuen Schlacht, {name} - eine Schlacht, in der es keinen Gewinner geben kann.\n\nDoch wir müssen unseren Marsch auf Eiskrone weiterführen. In dieser Hinsicht bleibt uns keine andere Wahl. Unsere Erlösung liegt in Helden wie Ihr es seid, {name}. Die Zukunft der Horde - die Zukunft der Welt - liegt in Euren Händen.\n\nKehren wir nach Orgrimmar zurück. Ihr müsst umgehend wieder nach Nordend reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13268] = { id = 13268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Ihr seht wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht - vielleicht kann ich Euch dann helfen.\n\nDie Humanoiden des Nordens tragen Kleider, die, wenn man weiß wie, recht schnell in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", completion = "Kommt wieder zurück, wenn Ihr über ausreichend Können verfügt. Ich kann Euch alles beibringen, was ein Schneider nur lernen kann." }
quests[13269] = { id = 13269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Die Humanoiden der Nordlande tragen Kleidungsstücke, die, wenn man weiß wie, in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten Humanoiden in Nordend zusätzlichen Froststoff erhalten.", completion = "Möget Ihr viele humanoide Wesen töten und ihren Stoff nehmen." }
quests[13270] = { id = 13270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Du siehst wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht, also habe ich da was für dich.\n\nDie Humanoiden vom Norden tragen Sachen, die in Stoff umgewandelt werden können, wenn man nur weiß wie.\n\nWenn du ein bisschen Geld locker machen willst, dann kann ich dir beibringen, wie man Stoffe plündert. Dadurch wirst du von den Humanoiden aus Nordend noch mehr Froststoff bekommen.", completion = "Gut, mit dir Geschäfte zu machen." }
quests[13271] = { id = 13271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stimme im Dunklen", description = "Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.\n\nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.\n\nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.\n\n\"Das hättet Ihr nicht tun sollen.\"", sourceObjective = "Untersucht die nahe Stimme in Naz'anak, den Vergessenen Tiefen.", completion = "Ich sah, wie er es weggeworfen hat, wisst Ihr? Er hat es ganz bis hier herunter geworfen.\n\nSagte, er bräuchte es nicht mehr. Sagte, es würde ihn schwach machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13272] = { id = 13272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Als Schneider meine ich, dass Ihr bereit seid, das zu lernen, was ich beizubringen habe.\n\nViele der humanoiden Wesen des Nordens tragen Kleidung, die sich mit dem geeigneten Wissen schnell in Stoff umwandeln lässt.\n\nFür ein paar Goldstücke kann ich Euch beibringen, wie man Stoffe plündert, um den Humanoiden aus Nordend zusätzlichen Stoff abzugewinnen.", completion = "Ich denke, dass Ihr diese Fähigkeit äußerst wichtig finden werdet, um zu schneiderischer Größe zu gelangen!" }
quests[13273] = { id = 13273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Kern hinterher", description = "Da wir nun Norgannons Schale in Händen halten, muss nur noch die zweite Hälfte des Archivschlüssels gefunden werden. Zum Glück habe ich die Forscherliga intensiv nach Hinweisen über den Aufenthaltsort des Kerns suchen lassen.\n\nWeit südöstlich der Bibliothek des Erfinders an den Hängen nördlich von Dun Niffelem befindet sich ein Lager, das meinen Namen trägt. Dort sind diejenigen der Forscherliga stationiert, die nach der zweiten Hälfte des Schlüssels suchen. Bringt mir die Karten und Notizen, die sie angefertigt haben, und die andere Schlüsselhälfte sollte sich finden lassen.", sourceObjective = "Geht zu Branns Basislager und sucht nach Ausgrabungsleiter Khronas Notizen und Ausgrabungsleiter Sorens Karten.", progress = "Habt Ihr diese Notizen mitgebracht?", completion = "Zerstört? Was soll das heißen. das Lager wurde zerstört?\n\n<Brann ballt wütend die Faust.>\n\nDiese Eisenzwerge werden dafür bezahlen! Wir können nur noch wenig tun. Wir müssen uns darauf konzentrieren, den Schlüssel fertig zu stellen. Doch sobald ich in die Hallen von Ulduar gelange, werden die Eisenzwerge und ihre Meister für das, was sie getan haben, zur Verantwortung gezogen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13274] = { id = 13274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter des Kerns", description = "Die Aufzeichnungen von Ausgrabungsleiter Soren erzählen uns, dass sich Norgannons Kern in der Obhut einer Schildwache namens Athan befindet - eine von Mimirs Schöpfungen.\n\nSoren meint, dass das Gewölbe, in dem Athan residiert, heutzutage \"Lokens Handel\" genannt wird.\n\nLoken, wie? Die Irdenen haben seinen Namen erwähnt.\n\nMan sagt, dass sich das Gewölbe südwestlich des zerstörten Lagers der Forscherliga befindet und dass dessen Eingang an einem Berghang mit Aussicht auf das Uralte Wintertal zu finden ist.\n\nFindet diesen Athan und beschafft Euch den Kern. Ich wäre jedoch nicht sonderlich überrascht, wenn Ihr auch kämpfen müsstet.", sourceObjective = "Beschafft Norgannons Kern.", progress = "Hatte Ausgrabungsleiter Soren recht? Habt Ihr Norgannons Kern endlich gefunden?", completion = "Das ist es! Der Schlüssel ist beinahe in Reichweite. Jetzt müssen wir nur noch herausfinden, wie wir die Schale und den Kern zu einem einzigen Schlüssel zusammenfügen können. Sehen wir einmal nach, was Ausgrabungsleiter Soren dazu zu sagen hatte...", sourceObjectiveStatus = "unverified-source-field" }
quests[13275] = { id = 13275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Verstecken", description = "Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.\n\nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.\n\nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.", sourceObjective = "Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.", progress = "Habt Ihr das Blut?", completion = "Worauf wartet Ihr dann noch? Ihr müsst Euch damit einreiben!\n\nSchnell! Oder er wird Euch sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13276] = { id = 13276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Ihr wisst, was zu tun ist, {class}.\n\nNehmt dieses Set und erschafft mit den Eingeweiden ihrer Monstrositäten Eure eigene Monstrosität. Lasst sie dann die feindlichen Truppen am Tor angreifen.\n\nIhr tätet gut daran, die Taktik noch zu verfeinern, bevor wir das Tor angreifen.", sourceObjective = "Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr das Monstrositätenwiedererweckungsset benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr dann 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Wie ich sehe, entwickelt sich Eure Fertigkeit in Bezug auf Monstrositäten gut.\n\nSeid gewissenhaft, mein Freund, und schon bald wird das Tor der Horde gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13277] = { id = 13277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Riesen", description = "Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.\n\nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.\n\nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.\n\nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.", sourceObjective = "Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr ihm 5 pustelige Wirbelsäulen von den pusteligen Schrecken auf Mord'rethar bringt.", progress = "Hattet Ihr Erfolg gegen die Riesen, {race}?", completion = "Hervorragend. Diese Exemplare sehen brauchbar aus.\n\nUnd wieder ist es an der Zeit, die Stärke des Gegners gegen ihn zu verwenden...", sourceObjectiveStatus = "unverified-source-field" }
quests[13278] = { id = 13278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koprus der Entweihte", description = "Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, {class}.\n\nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.\n\nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Koprus den Entweihten bei Mord'rethar tötet.", completion = "Gut gemacht, {class}.\n\nMit einigen Nachforschungen können wir vielleicht herausfinden, wie sie eine derartige Kreatur erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13279] = { id = 13279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundkenntnisse der Chemie", description = "<Koltira nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...\n\nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.\n\nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.\n\nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.", sourceObjective = "Koltira Todesweber an Bord der Orgims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord'rethar gießt.", completion = "Gute Arbeit, {class}.\n\nWenn unsere Armeen eintreffen, um gegen die Zitadelle zu marschieren, haben wir einen fundierten Plan, um das Tor des Todes einzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13280] = { id = 13280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Berge", description = "Ihr müsst meinen Hüpfboter nur so schnell wie möglich von Ymirheim zum Gipfel dieses Berges dort im Nordwesten bringen, {name}!\n\nDieser heimtückische, nichtsnutzige Bumm Donnerbombe arbeitet an seinem eigenen Bot und ich befürchte, dass er beinahe fertig ist. Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!\n\nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass niemand besser ist, als die Allianz - und meine Ingenieursfertigkeiten!", sourceObjective = "Fetzi Gangzwinger in Ymirheim möchte, dass Ihr ihren Hüpfboter benutzt, um die Schlachtstandarte der Allianz in den Schädelhaufen auf dem Gipfel des Berges zu stecken.", progress = "Wartet mal eine Sekunde... Ihr habt unsere Schlachtstandarte noch nicht aufgestellt?!\n\nWas hält Euch auf?", completion = "IHR HABT ES GESCHAFFT! IHR HABT ES GESCHAFFT!\n\n<Fetzi springt in die Luft und umarmt Euch innig.>\n\n\n\nAch, Ihr seid einfach der Beste, den es gibt!\n\nDenkt Ihr, dass Ihr morgen wiederkommen könntet?", sourceObjectiveStatus = "unverified-source-field" }
quests[13281] = { id = 13281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche neutralisieren", description = "Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, {race}.\n\nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.\n\nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.\n\nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord'rethar.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord'rethar schüttet.\n\npustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.", completion = "Ein Seuchenkessel weniger, um den wir uns kümmern müssen, wenn die Schlacht beginnt.\n\nEuer Kommandant wird äußerst zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13282] = { id = 13282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr an die Oberfläche", description = "Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.\n\nWir werden uns wiedersehen. Er wird nach Euch suchen.\n\nEs ist nur eine Frage der Zeit, bis er Euch findet.", sourceObjective = "Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", completion = "{name}! Wir dachten, Ihr seid tot!\n\nWir haben ein paar Männer bei der Explosion verloren... doch wir haben den Dienern der Geißel auf jeden Fall gut Schaden zugefügt. Sie sind auf schleunigstem Rückzug zur Zitadelle und hinterlassen große Lücken in ihrer Verteidigung. Es ist Zeit vorzurücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13283] = { id = 13283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Berge", description = "Also, {name}, Ihr müsst meinen Hüpfboter zum Gipfel dieses Berges dort im Südosten bringen, wie gestern!\n\nDiese weibische, selbstgerechte Fetzi Gangzwinger meint, dass ihr Hüpfboter besser sei als meiner. Ha! Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!\n\nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass die Horde und meine verrückten Ingenieursfertigkeiten die Besten sind!", sourceObjective = "Bumm Donnerbombe in Ymirheim möchte, dass Ihr seinen Hüpfboter benutzt, um die Schlachtstandarte der Horde in den Schädelhaufen auf dem Gipfel des Berges zu stecken.", progress = "Wartet mal eine Sekunde... Ihr habt unsere Schlachtstandarte noch nicht aufgestellt?!\n\nWie kommt das?", completion = "Ah, {race}, ich wusste, dass Ihr der Richtige für den Job sein würdet!\n\n\n\nIch muss zugeben, {class}, dass Euch das im Moment auf meiner Liste ganz weit oben stehen lässt!\n\nWas sagt Ihr dazu, diese Vorstellung morgen nochmal zu wiederholen? Es würde sich für Euch lohnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13284] = { id = 13284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodenangriff", description = "Grüße, {class}.\n\nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.\n\nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.", sourceObjective = "Eskortiert die Truppen der Himmelsbrecher zu den Toren von Ymirheim. Kehrt zu Feldkommandant Koup am Rand des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.", completion = "Ihr habt meinen Dank.\n\nDiese Operation war gnadenlos, doch uns blieb keine bessere Möglichkeit - unseren Lufteinheiten haben sie genauso schonungslos zugesetzt. Wir müssen diese Vrykul loswerden, wenn wir auch nur den Hauch einer Chance haben wollen, in Eiskrone weiter vorzustoßen.\n\nWir werden später höchstwahrscheinlich noch mehr Hilfe benötigen. Bitte schließt euch uns wieder an, sollte sich die Möglichkeit ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13285] = { id = 13285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlüsselstein schmieden", description = "Aha! Da ist er ja: der Tempel des Erfindungsreichtums, Sitz von Hüter Mimir höchstpersönlich! Natürlich, dort würde man hingehen, um die zwei Teile des Schlüssels zusammenzufügen.\n\nDen Notizen des Ausgrabungsleiters zufolge ist der Tempel des Erfindungsreichtums einer der höchsten Punkte auf der westlichen Seite der Terrasse der Schöpfer. Das bedeutet, dass sich der Ort ungefähr östlich der Absturzstelle Grom'ash befinden sollte.\n\nIch treffe Euch im Tempel und wir werden die zwei Teile zusammenfügen.", sourceObjective = "Brann Bronzebart möchte, dass Ihr ihn im Tempel des Erfindungsreichtums trefft und ihm dabei helft, Norgannons Schale und Norgannons Kern zusammenzufügen. Meldet Euch bei Boktar Blutfurie bei der Absturzstelle Grom'ash, sobald dies getan ist.", completion = "<Boktar nickt zustimmend, als Ihr ihm davon erzählt, wie Ihr Brann dabei geholfen habt, die Teile zu beschaffen und sie zusammenzufügen.>\n\nBrann könnte genau der Verbündete sein, den wir brauchen, um herauszufinden, was wirklich in Ulduar vor sich geht. Es war gut von Euch, ihm zu helfen. Gegen diesen Loken und seine untergebenen Eisenzwerge benötigen wir jede Hilfe, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13286] = { id = 13286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... Jede Hilfe, die wir kriegen können", description = "Schlimme Zeiten, {class}...\n\nSo ungern ich das auch tue, ich bin mittlerweile bereit, Hilfe von wirklich jedem anzunehmen - selbst von unserem Todesritter.\n\nGeht zu Thassarian und seht, ob er uns dabei helfen kann, Taktiken gegen die Geißel zu entwickeln, die uns den Sieg bringen können, sobald wir einen weiteren Angriff beginnen können.\n\nWir sind so weit gekommen... wir dürfen jetzt nicht scheitern!", sourceObjective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr mit Thassarian sprecht.", completion = "Es war weise von Stabshauptmann Bartlett, Euch zu mir zu schicken.\n\nWährend er sich um euren Konflikt mit der Horde sorgt, muss sich jemand voll und ganz auf die wahre Mission hier konzentrieren - den Marsch auf die Eiskronenzitadelle.\n\nWer könnte besser Eure Bemühungen koordinieren, als ein ehemaliger Diener des Lichkönigs?", sourceObjectiveStatus = "unverified-source-field" }
quests[13287] = { id = 13287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stechen und Stoßen", description = "Wie jemand mit Eurer Erfahrung sicher weiß, gibt es keinen besseren Weg, etwas über seinen Gegner herauszufinden, als sich ihm im Kampf gegenüberzustellen.\n\nObschon Ihr sicher nach dem Ruhm giert, die Eiskronenzitadelle einzunehmen, kann dies jedoch nicht passieren, bevor nicht jedes der Tore des Lichkönigs erobert ist. Vorerst müsst Ihr Eure Anstrengungen auf das erste der Tore konzentrieren...\n\nKehrt zur Zerbrochenen Front zurück. Verwickelt den Gegner in eine Schlacht. Sucht nach einer Schwäche, die wir ausnutzen könnten, und kehrt dann mit einem detaillierten Bericht zu mir zurück.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten bei der Zerbrochenen Front tötet.", completion = "Ehrlich, {class}?\n\nNichts besonderes zu berichten?\n\n\n\nIch erlaube mir, das Gegenteil zu behaupten...", sourceObjectiveStatus = "unverified-source-field" }
quests[13288] = { id = 13288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Monstrositäten...\n\nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.\n\nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.\n\nZu Eurem Glück kenne ich diese Geheimnisse.\n\nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Seht Ihr, {class}?\n\nRaffinesse kann mitunter selbst in aussichtslos scheinenden Situationen für Chancengleichheit sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13289] = { id = 13289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Ihr wisst, was Ihr zu tun habt, {class}.\n\nNehmt dieses Set hier und benutzt die Eingeweide ihrer Monstrositäten, um eine eigene zu erschaffen, dann befehlt ihr, die Streitkräfte des Gegners am Tor anzugreifen.\n\nIhr tätet gut daran, vor unserem nächsten Angriff auf das Tor diese Taktik zu verfeinern.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Ich sehe, dass sich Eure Fähigkeiten mit den Monstrositäten beachtlich entwickelt haben.\n\nBleibt eifrig bei der Sache, Freund, und schon bald wird das Tor in der Hand der Allianz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13290] = { id = 13290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte recht aufmerksam", description = "Chefingenieur Bolzenschlüssel hat sich als unabdingbar auf der Sturmbrecher erwiesen. Ohne seine Genialität lägen wir mittlerweile schon mehrfach über den halben Gletscher verstreut.\n\nDas Problem ist nur, dass er jede einzelne popelige Erfindung oder Entdeckung gleich diskutieren will - obwohl ich die Hälfte sowieso nicht verstehe.\n\nMein Augenmerk muss jetzt aber ausschließlich auf unseren Feinden liegen. Ich kann mir keine Ablenkungen erlauben.\n\nBitte stattet ihm einen Besuch an meiner Stelle ab, {name}. Und assistiert ihm, wenn Ihr könnt. Ihr findet ihn unter Deck.", sourceObjective = "Stabshauptmann Bartlett möchte, dass Ihr mit Chefingenieur Bolzenschlüssel in der Himmelsbrecher redet.", completion = "Cappy hat Euch an seiner Stelle geschickt, oder?\n\nNun gut, {class}. Krempelt Eure Ärmel hoch... es ist Zeit, an die Arbeit zu gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13291] = { id = 13291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geliehene Technologie", description = "Ich kapier's ja, ich kapier's ja. Cappy ist zu beschäftigt, um es sich selber anzusehen. Selbst Schuld!\n\nSeht Ihr, ich habe es geschafft, eine gewisse Lieferung Lösungen vom Feind zu 'leihen'. Und so sehr ich es auch hasse, mit minderwertiger Goblintechnologie zu hantieren, so bin ich doch versucht, hier mal eine Ausnahme zu machen.\n\nNehmt diese Probe. Ihr müsst für mich einige Feldversuche durchführen, um ihre Nützlichkeit unter Beweis zu stellen, während ich versuche, ein wenig umgekehrte Ingenieurskunst zu betreiben und den Erschaffungsprozess zu duplizieren.\n\nGeht an die Front und sammelt das Material, um eine Attrappe zu bauen, dann benutzt das Öl.", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher will, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front benutzt.\n\nUm die Lösung zu benutzen, braucht Ihr einen zurückgelassenen Helm, eine zurückgelassene Rüstung und einen Knochenhaufen, die allesamt an der Zerbrochenen Front gefunden werden müssen.", completion = "Gute Neuigkeiten!\n\nIch habe es geschafft, die Lösung zu reproduzieren - was natürlich kaum eine Errungenschaft darstellt.\n\nIch bezweifle, dass diese Neanderthaler von Goblins jemals etwas gebastelt bekommen, das wir Gnome nicht im Schlaf nachbauen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13292] = { id = 13292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lösungslösung", description = "Oh, ja, ja. Wieder zurück, hmm? Man kann nie genug Training haben, was?\n\nUnd hier ist sie, die Lösung für das ärgerliche Frostwyrmproblem.\n\nVerringert ihre Anzahl, {race}. Je mehr Ihr jetzt ausschaltet, desto weniger sitzen uns im Nacken, wenn wir uns aufmachen, die Zitadelle anzugreifen.\n\nViel Glück Euch. Und bringt doch bitte zurück, was Ihr nicht braucht.", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front einsetzt.\n\nUm die Lösung benutzen zu können, benötigt Ihr einen zurückgelassenen Helm, zurückgelassene Rüstung und einen Knochenhaufen, die alle an der Zerbrochenen Front zu finden sind.", completion = "Großartig! Wirklich großartig. Ihr werdet noch zum Wyrmtöterprofi!\n\nKommt wieder, wenn Ihr bereit seid, Ihre Reihen weiter auszudünnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13293] = { id = 13293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Ymirheim!", description = "Ihr müsst hinunter nach Ymirheim, der großen Stadt der Frostvrykul im Zentrum von Eiskrone.\n\nUnser Kumpel, Bumm Donnerbombe, ist schon da, im Westen der Stadt und repräsentiert die Kriegshymnenoffensive in einem Wettkampf gegen die Allianz. Es steht sein Hüpfboter gegen ihren in einem Wettkampf um den Titel König der Berge!\n\nLasst uns nicht im Stich, {name}. Der Stolz der goblinischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier auf dem Schiff auf Euch.\n\nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Feiglingen ordentlich in den Hintern tretet!", sourceObjective = "Redet mit Bumm Donnerbombe in Ymirheim.", completion = "Oh Mann, bin ich froh, Euch zu sehen. Hat Euch der Häuptling von der Hammer hergeschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[13294] = { id = 13294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Riesen", description = "Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.\n\nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.\n\nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.\n\nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr ihm 5 pustelige Wirbelsäulen von den pusteligen Spuken auf Mord'rethar bringt.", progress = "Hattet Ihr Erfolg gegen die Riesen, {race}?", completion = "Hervorragend. Diese Exemplare sehen brauchbar aus.\n\nUnd wieder ist es an der Zeit, die Stärke des Gegners gegen ihn zu verwenden...", sourceObjectiveStatus = "unverified-source-field" }
quests[13295] = { id = 13295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundkenntnisse der Chemie", description = "<Thassarian nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...\n\nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.\n\nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.\n\nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord'rethar gießt.", completion = "Gute Arbeit, {class}.\n\nWenn unsere Armeen eintreffen, um gegen die Zitadelle zu marschieren, haben wir einen fundierten Plan, um das Tor des Todes einzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13296] = { id = 13296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Ymirheim!", description = "Ihr müsst runter nach Ymirheim, der großen Frostvrykulstadt im Zentrum von Eiskrone.\n\nFetzi Gangzwinger ist schon da, im Süden der Stadt, und repräsentiert die Expedition 'Valianz' in einem Wettkampf gegen die Mistkerle der Horde. Es steht Fetzis Hüpfboter gegen ihren in einem Wettkampf um den Titel des Königs der Berge!\n\nLasst uns nicht im Stich, {name}. Der Stolz der gnomischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier in der Feste auf Euch.\n\nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Idioten ordentlich in den Hintern tretet!", sourceObjective = "Sprecht mit Fetzi Gangzwinger in Ymirheim.", completion = "Hat Euch der Boss von der Himmelsbrecher hier runter geschickt? Ist das nicht süß?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13297] = { id = 13297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche neutralisieren", description = "Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, {race}.\n\nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.\n\nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.\n\nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord'rethar.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord'rethar schüttet.\n\npustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.", completion = "Ein Seuchenkessel weniger, um den wir uns kümmern müssen, wenn die Schlacht beginnt.\n\nEuer Hauptmann wird äußerst zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13298] = { id = 13298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koprus der Entweihte", description = "Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, {class}.\n\nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.\n\nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Koprus den Entweihten in Mord'rethar tötet.", completion = "Gut gemacht, {class}.\n\nMit einigen Nachforschungen können wir vielleicht herausfinden, wie sie eine derartige Kreatur erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13299] = { id = 13299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDWisp Cloak" }
quests[13300] = { id = 13300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Saronit abhängig", description = "Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.\n\nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.\n\nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Expedition 'Valianz' als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, {name}?", sourceObjective = "Absalan der Fromme an Bord der Himmelsbrecher möchte, dass Ihr 10 Saronitminensklaven rettet.", completion = "Sie werden wahnsinnig gemacht? Stimmen in ihren Köpfen?\n\nStimmen in Eurem Kopf?!\n\nIch möchte, dass Ihr Eure Gedanken von dem Unheil befreit, das diesen Ort ergriffen hat, {class}.\n\nWir werden versuchen morgen den Rest von ihnen da rauszubekommen, wenn Ihr eine Chance hattet, Euch auszuruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13301] = { id = 13301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodenangriff", description = "Grüße, {class}.\n\nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.\n\nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.", sourceObjective = "Eskortiert die Truppen der Kor'kron zu den Toren von Ymirheim. Kehrt zu Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.", completion = "Ihr habt meinen Dank.\n\nDiese Operation war gnadenlos, doch uns blieb keine bessere Möglichkeit - unseren Lufteinheiten haben sie genauso schonungslos zugesetzt. Wir müssen diese Vrykul loswerden, wenn wir auch nur den Hauch einer Chance haben wollen, in Eiskrone weiter vorzustoßen.\n\nWir werden später höchstwahrscheinlich noch mehr Hilfe benötigen. Bitte schließt euch uns wieder an, sollte sich die Möglichkeit ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13302] = { id = 13302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Saronit abhängig", description = "Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.\n\nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.\n\nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Kriegshymnenoffensive als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, {name}?", sourceObjective = "Bruder Keltan an Bord der Orgrims Hammer möchte, dass Ihr 10 Saronitminensklaven rettet.", completion = "Sie werden wahnsinnig gemacht? Stimmen in ihren Köpfen?\n\nStimmen in Eurem Kopf?!\n\nIch möchte, dass Ihr Eure Gedanken von dem Unheil befreit, das diesen Ort ergriffen hat, {class}.\n\nWir werden versuchen morgen den Rest von ihnen da rauszubekommen, wenn Ihr eine Chance hattet, Euch auszuruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13304] = { id = 13304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldreparaturen", description = "Die Geißel erholt sich noch immer von unserem Angriff, {name}. Jetzt ist die Zeit, die Gunst der Stunde zu nutzen und zuzuschlagen.\n\nDas strategisch wichtige Tal unter uns ist weit offen. Wir haben in der südöstlichen Ecke des Tals der Verlorenen Hoffnung ein zerlegtes Verwüsterfahrzeug entdeckt, das sich, so glauben wir, noch in einem funktionsfähigen Zustand befindet.\n\nFalls Ihr die restlichen Teile von den Aasfressern der Geißel beschaffen könntet, solltet Ihr es wieder zum Laufen bringen können. Ein einziger funktionierender Verwüster kann unter den Bodeneinheiten des Feindes verheerenden Schaden anrichten.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken im Tal der Verlorenen Hoffnung beschafft und sie zum defekten Verwüster bringt.", progress = "Der Verwüster wurde stark beschädigt.", completion = "Der Verwüster hat schon bessere Tage gesehen, aber die Struktur hat keinen dauerhaften Schaden genommen. Die Ersatzteile, die Ihr gebracht habt, sollten ausreichen, um ihn zumindest vorübergehend wieder ans Laufen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13305] = { id = 13305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euer Schlechtestes", description = "Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.\n\nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.\n\nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.", sourceObjective = "Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.", completion = "Seht Ihr? Ihr habt Euren gerechten Anteil zwar getötet, doch für jeden Einzelnen, den Ihr vernichtet habt, kam ein weiterer aus der Erde, um dessen Platz einzunehmen.\n\nIhr wisst nicht, wem Ihr hier gegenübersteht, {name}. Lasst es mich Euch zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13306] = { id = 13306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errichtet die Barrikaden", description = "Sobald unsere Truppen sich hinter Aldur'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.\n\nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.\n\nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.", completion = "<Koltira nickt kurz.>\n\nGut. Sie bieten nicht gerade viel Schutz, aber immer noch besser als nichts. Dieses Tor ist noch immer der perfekte Engpass, wenn die Geißelanführer wissen, was sie tun. Wir müssen so viel von dem umliegenden Gebiet wie möglich einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
